window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-cardiologia-car-1"]={"block":"medcurso:medcurso-cardiologia-car-1","label":"Medcurso · CAR 1","count":434,"questions":[{"id":"medcurso-cardiologia-car-1-345439","number":"345439","sourceNumber":"345439","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre o uso de vasopressores durante o atendimento de uma parada\ncardiorrespiratória (PCR) em paciente adulto,\nassinale a afirmativa CORRETA, de acordo com as\nrecomendações da American Heart Association:","options":{"A":"É razoável que se administre epinefrina para todos os pacientes com PCR, na dose de 01mg,\ncom intervalo de 02 minutos entre cada dose.","B":"Durante uma PCR em Atividade Elétrica sem Pulso (AESP), é recomendado que se administre\nepinefrina assim que possível.","C":"Paciente com PCR em Fibrilação Ventricular (FV) deve receber adrenalina logo após a\nrealização da primeira tentativa de desfibrilação.","D":"O uso de vasopressina em substituição à primeira ou segunda dose de adrenalina deve ser feito\nsempre que disponível, já que apresenta melhores desfechos em comparação ao uso apenas de\nadrenalina."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-345451","number":"345451","sourceNumber":"345451","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Por velocidade de redução da pressão ventricular, a segunda bulha cardíaca pode\napresentar hipofonese por:","options":{"A":"Estado de baixo débito cardíaco (choque e miocardiopatia).","B":"Enfisema pulmonar.","C":"Edema Agudo de Pulmão.","D":"Hipertensão arterial sistêmica."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343854","number":"343854","sourceNumber":"343854","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual diagnóstico eletrocardiográfico (D2) da arritmia na figura abaixo?","options":{"A":"Fibrilação atrial","B":"Taquicardia paroxística supraventricular","C":"Flutter atrial com bloqueio AV variável","D":"Taquicardia ventricular"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/343854.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-283271","number":"283271","sourceNumber":"283271","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 25 anos chega à emergência referindo dor torácica de forte intensidade,\nassociada à taquicardia e palpitações. O\neletrocardiograma evidenciou taquicardia sinusal com\ncomplexo QRS estreito, encurtamento do intervalo PR e supra desnivelamento de seguimento ST,\nsendo que a investigação enzimática não mostrou elevação de marcadores de necrose miocárdica.\nEm relação aos diagnósticos possíveis, assinale a alternativa CORRETA.","options":{"A":"Síndrome de Brugada.","B":"Síndrome de Wolff-Parkinson-White.","C":"Fibrilação atrial aguda.","D":"Flutter atrial."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-281110","number":"281110","sourceNumber":"281110","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 59 anos, sexo masculino, chega ao ambulatório para consulta médica de\nrotina quando apresenta quadro súbito de inconsciência, associado a ausência de pulso e\nrespiração. Nesse momento, recomenda-se ao profissional de saúde, chamar ajuda e realizar:","options":{"A":"15 compressões, intercaladas com 05 ventilações.","B":"15 compressões, intercaladas com 02 ventilações.","C":"90 compressões por minuto, apenas.","D":"30 compressões, intercaladas com 05 ventilações.","E":"30 compressões, intercaladas com 02 ventilações."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-281119","number":"281119","sourceNumber":"281119","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O achado ocasional ao eletrocardiograma de amplitude e forma na onda \"p\", em\npaciente jovem, chama atenção para eventuais problemas:","options":{"A":"Ventrículares.","B":"No ventrículo direito.","C":"Na despolarização ventricular.","D":"Atriais.","E":"De bloqueio de ramos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-283367","number":"283367","sourceNumber":"283367","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente masculino, 65 anos, apresenta diagnóstico de hipertensão arterial há 8 anos,\nfazendo uso regular de enalapril e anlodipino. Há uma semana passou a apresentar queixa de\npalpitações e fadiga fácil, tendo sido solicitado um eletrocardiograma, que mostrou taquicardia\nsupraventricular, FC= 135 bpm, sem sinais de isquêmica miocárdica. O exame físico do paciente é\nnormal, exceto pela taquicardia, PA - 126X80 mmHg. Assinale dentre as alternativas abaixo, a\nmelhor conduta neste caso:","options":{"A":"Substituição da anlodipina pelo diltiazem.","B":"Acréscimo da furosemida.","C":"Aumento da dose do enalapril.","D":"Acréscimo da espironolactona."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182678","number":"182678","sourceNumber":"182678","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente inconsciente, não responsivo, com ausência de pulso carotídeo e com o\nseguinte traçado no monitor cardíaco: Qual a próxima medida terapêutica no atendimento de\nurgência?","options":{"A":"Desfibrilação imediata com 200 joules.","B":"Verificar cargas, ganhos e derivações da monitorização.","C":"Pedir ajuda a outros membros da equipe de saúde e iniciar imediatamente o Suporte Básico de\nVida.","D":"Acesso venoso imediato e epinefrina endovenosa."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/182678.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-159034","number":"159034","sourceNumber":"159034","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente 67 anos, com 100 kg, hipertenso e diabético, adentra a emergência do\npronto-socorro com dor torácica irradiando\npara mandíbula há 1 hora. Após o atendimento inicial,\npaciente apresentou parada cardiorrespiratória em fibrilação ventricular identificada pelo monitor\ncardíaco. A conduta mais adequada será utilizar:","options":{"A":"O desfibrilador monofásico com carga de 200 J.","B":"100 mg de lidocaína endovenosa.","C":"O desfibrilador bifásico com carga de 200 J.","D":"Amiodarona 300 mg endovenosa."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-50075","number":"50075","sourceNumber":"50075","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"F.A.S., masculino, 75 anos, procura o médico da Unidade Básica de Saúde referindo\npalpitações de início súbito na noite anterior. A ausculta cardíaca revela ritmo irregular e\nfrequência\ncardíaca de 120 batimentos por minuto, compatível com fibrilação atrial. O paciente é hipertenso,\nmas fazia controle com resposta adequada da pressão arterial com o uso de hidroclorotiazida 25\nmg uma vez ao dia e captopril 25 mg duas vezes ao dia. Entre as alternativas abaixo, qual o\nMELHOR plano de cuidado?","options":{"A":"Substituir captopril por propranolol;","B":"Encaminhar o paciente para a emergência a fim de que se avalie a possibilidade de\ncardioversão;","C":"Prescrever digoxina;","D":"Adotar conduta expectante, reavaliando o paciente após 7 dias."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-37083","number":"37083","sourceNumber":"37083","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A arritmia mais frequentemente encontrada em pacientes com estenose mitral é:","options":{"A":"Flutter atrial.","B":"Dissociação atrioventricular.","C":"Fibrilação atrial.","D":"Taquicardia atrial paroxística.","E":"Fibrilação ventricular."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-37111","number":"37111","sourceNumber":"37111","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa correta: qual a arritmia mais comum na faixa etária pediátrica?","options":{"A":"Taquicardia supraventricular.","B":"Taquicardia juncional.","C":"Taquicardia ventricular.","D":"Bloqueio atrioventricular total.","E":"Flutter atrial."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-37108","number":"37108","sourceNumber":"37108","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na toxicidade sistêmica provocada por anestésicos locais:","options":{"A":"Os bloqueadores de canal de cálcio são bem indicados.","B":"A succinilcolina inibe a atividade do sistema nervoso central.","C":"A lidocaina provoca inicialmente sintomas no sistema cardiovascular.","D":"O sucesso da ressuscitação cardiovascular é maior com a lidocaína do que com a ropivacaina.","E":"Aconselha-se evitar soluções lipídicas como o propofol."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343157","number":"343157","sourceNumber":"343157","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A classificação de acordo com sua duração em segundos da taquicardia sustentada\n(TVS) ou não sustentada (TVNS), está de\nacordo com o seguinte item correto:","options":{"A":"Se o período da arritmia for ou não superior a 90 s e/ou sem sintomas de instabilidade\nhemodinâmica.","B":"Se o período da arritmia for ou não inferior a 30 s e/ou sem sintomas de instabilidade\nhemodinâmica.","C":"Se o período da arritmia for ou não superior a 30 s e/ou sem sintomas de instabilidade\nhemodinâmica.","D":"Se o período da arritmia for ou não superior a 30 s e/ou sem considerar sintomas de\ninstabilidade hemodinâmica."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343164","number":"343164","sourceNumber":"343164","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"HMN, masculino de 57 anos, grande tabagista e obeso, analisando se ECG foi\nencontrado Sobrecarga Atrial Esquerda (SAE) com onda\nP com componente negativo aumentado\n(final lento e profundo) na derivação V1. Podemos indicar como correto que:","options":{"A":"A área da fase negativa de pelo menos 0,09 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor\nsensibilidade que o critério isolado de duração aumentada.","B":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 11 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada.","C":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta pior sensibilidade que o critério isolado de duração aumentada.","D":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343169","number":"343169","sourceNumber":"343169","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobrecarga Atrial Direita (SAD), está de acordo com o seguinte item correto:","options":{"A":"A onda P apresenta-se não apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","B":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","C":"A onda P apresenta-se apiculada com amplitude abaixo de 0,25 mV ou 2,5 mm.","D":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 3,5 mm."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-313441","number":"313441","sourceNumber":"313441","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre as Arritmias em oncopediatria, assinale a alternativa incorreta.","options":{"A":"Os pacientes que serão submetidos a quimioterapias potencialmente cardiotóxicas devem\nrealizar um ECG prévio para diagnóstico, e fazer seguimento cardiológico pós-quimioterapia.","B":"Os pacientes que apresentarem alterações no ECG devem realizar a monitoração\neletrocardiográfica de 24 horas (Holter) e a\nmonitoração hemodinâmica contínua durante a\nquimioterapia.","C":"Na rotina do paciente que apresenta alterações eletrocardiográficas, deve-se incluir o ECG antes\nde cada novo ciclo de quimioterapia,\nespecialmente nos casos de usuários de ATO (trióxido de\narsênio).","D":"Nas arritmias de QT prolongado e torsades de pointes, deve-se realizar sulfato de magnésio na\ndose de 50 a 85mg/Kg em 30 minutos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-279028","number":"279028","sourceNumber":"279028","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Nas manobras de Ressuscitação Cardiopulmonar de Pacientes com Diagnóstico ou\nSuspeita de COVID-19, está correto que.","options":{"A":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o mínimo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve?se colá-las em\nposição ântero posterior.","B":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\npromovendo sempre a desconexão do ventilador e o\nrisco de aerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve-se\ncolá-las em posição ântero posterior.","C":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, deve-se colá-las em\nposição ântero posterior.","D":"Recomenda-se que tentativas de retorno do paciente para posição supina sejam executadas\ncom o máximo de segurança ao despronar,\nevitando a desconexão do ventilador e o risco de\naerossolização. Se houver disponibilidade de pás adesivas do desfibrilador, nunca colá-las em\nposição ântero posterior."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-279031","number":"279031","sourceNumber":"279031","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Parada Cardiorrespiratória (PCR) pode ser causada por quatro ritmos: FV, TVSP,\nAESP e Assistolia. A sobrevida depende da\nintegração do SBV, do Suporte Avançado de Vida em\nCardiologia (SAVC) e dos cuidados pós-ressuscitação. Sendo correto que:","options":{"A":"O atraso no início da administração de vasopressores para além dos primeiros 15 minutos de\nPCR, bem como a demora em instalar via aérea avançada, pode estar associado a pior\nprognóstico.","B":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, bem como a demora em instalar via aérea avançada, pode estar associado a pior\nprognóstico.","C":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, mas não a demora em instalar via aérea\navançada, pode estar associado à pior prognóstico.","D":"O atraso no início da administração de vasopressores para além dos primeiros 5 minutos de\nPCR, bem como a demora em instalar via aérea avançada, não pode estar associado à pior\nprognóstico."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-278612","number":"278612","sourceNumber":"278612","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Há uma diminuição de 6% na taxa de metabolismo cerebral de oxigênio na redução da\ntemperatura corpórea a cada 1 °C. Indique o item com erro:","options":{"A":"O uso de hipotermia atua como estimulador das vias facilitadoras da morte cerebral e da\napoptose celular.","B":"Existe evidência de uma diminuição dos radicais livres durante o controle da temperatura.","C":"Há um bloqueio à ação intracelular da exposição às excitotoxina (acionadas pelo aumento do\ncálcio e do glutamato).","D":"Redução da resposta inflamatória na síndrome pós-PCR."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-279032","number":"279032","sourceNumber":"279032","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando a monitorização com desfibrilador manual revela ritmo de FV/TVSP, assinale a\nalternativa correta.","options":{"A":"A prioridade deve ser a desfibrilação precoce, uma vez que não aumenta o sucesso do\nprognóstico.","B":"A prioridade deve ser a cardioversão precoce, uma vez que aumenta o sucesso do prognóstico.","C":"A prioridade deve ser a desfibrilação precoce, uma vez que reduz o sucesso do prognóstico.","D":"A prioridade deve ser a desfibrilação precoce, uma vez que aumenta o sucesso do prognóstico."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-279033","number":"279033","sourceNumber":"279033","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando da abordagem de Assistolia e Atividade Elétrica sem Pulso, podemos indicar\ncomo correto a alternativa:","options":{"A":"São ritmos em que a desfibrilação está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas\ne procurar identificar e tratar as causas reversíveis.","B":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas e procurar identificar e tratar as causas\nreversíveis.","C":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, sem aplicar as drogas indicadas e procurar identificar e tratar as causas reversíveis.","D":"São ritmos em que a desfibrilação não está indicada. Deve-se, então, promover RCP de alta\nqualidade, além de aplicar as drogas indicadas e procurar identificar e não tratar as causas\nreversíveis."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-278084","number":"278084","sourceNumber":"278084","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O uso de escores de gravidade e sistemas de rastreamento e o disparo de códigos\namarelos:","options":{"A":"Permitem a detecção tardia de pacientes graves e podem otimizar o atendimento de eventuais\nPCRs.","B":"Permitem a detecção precoce de pacientes graves e podem otimizar o atendimento de eventuais\nPCRs.","C":"Permitem a detecção precoce de pacientes graves e não podem otimizar o atendimento de\neventuais PCRs.","D":"Não permitem a detecção precoce de pacientes graves e podem otimizar o atendimento de\neventuais PCRs."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-279034","number":"279034","sourceNumber":"279034","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O racional para o uso de vasopressores durante a RCP. Assinale a alternativa que se\nfundamenta sendo o item correto.","options":{"A":"Reduzir a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica e\na pressão no átrio direito, durante a fase de\nrelaxamento (descompressão) torácico.","B":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio esquerdo, durante a\nfase de relaxamento (descompressão) torácico.","C":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio direito, durante a fase\nde relaxamento (descompressão) torácico.","D":"Aumentar a pressão de perfusão coronariana, definida como a diferença entre a pressão aórtica\ne a pressão no átrio direito, durante a fase\nde contração (descompressão) torácico."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249382","number":"249382","sourceNumber":"249382","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para que ocorra uma melhoria nas estruturas e nos sistemas de saúde, que é um dos\npontos essenciais no sucesso do atendimento da Parada Cardiorrespiratória (PCR), sendo\ninadequado apenas:","options":{"A":"Criação de um sistema integrado com treinamento de pessoas.","B":"Auxílio de materiais de emergência.","C":"Transportes para um atendimento unificado.","D":"Disponibilidade de DEA em locais públicos com baixa movimentação de pessoas."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249385","number":"249385","sourceNumber":"249385","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Atualização da Diretriz de Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares\nde Emergência da Sociedade Brasileira de\nCardiologia ? 2019. Listamos abaixo itens referentes à\ncadeia de elos de sobrevivência diferenciadas no contexto de uma parada cardiorrespiratória (PCR)\nintra-hospitalar, determine o item que não pode ser considerado como parte da mesma:","options":{"A":"RCP imediata de alta qualidade.","B":"Rápida desfibrilação.","C":"Suporte básico de Vida.","D":"Cuidados pós-PCR."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249389","number":"249389","sourceNumber":"249389","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares inseridos nos Cuidados\npós-PCR, apresenta como importante ponto o item:","options":{"A":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom maior tolerância na variação de\ntemperatura e prevenção de febre.","B":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e prevenção\nde febre.","C":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e sem\nprevenção de febre.","D":"Ênfase na avaliação neurológica, sem o cumprimento das metas hemodinâmicas e controle\ntérmico, com menor variação de temperatura e prevenção de febre."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249393","number":"249393","sourceNumber":"249393","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A adequada abordagem de Ressuscitação Cardiopulmonar e Cuidados\nCardiovasculares com ênfase nos cuidados após o\nretorno à circulação espontânea trouxe\nmelhorias nos resultados, contribuído ao prognóstico dos pacientes. Podemos assim determinar\ncomo adequado que:","options":{"A":"O reconhecimento precoce das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","B":"O reconhecimento tardio das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","C":"O reconhecimento precoce das causas desencadeantes, desorientando a intervenção para cada\ncenário clínico.","D":"O reconhecimento precoce das causas desencadeantes, não orientando a intervenção para\ncada cenário clínico."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249216","number":"249216","sourceNumber":"249216","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa incorreta:","options":{"A":"Sintomas são as queixas apresentadas pelo paciente, relativas à doença. São dados subjetivos\ncomo dor de ouvido, dor de garganta, etc.","B":"Consideramos os sinais as queixas subjetivas apresentadas pelo paciente, aquilo que o paciente\nrefere e não são avaliados no exame\nfísico.","C":"Síndrome é definida como o conjunto de sinais e sintomas ligados a uma entidade mórbida que\nconsta no quadro geral de uma doença.","D":"É considerado sinal tudo que podemos avaliar no paciente através dos nossos sentidos."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249228","number":"249228","sourceNumber":"249228","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina, 35 anos, sem comorbidades, admitida em leito de terapia intensiva\napós laparotomia exploradora por cisto de ovário\nroto. Após 12 horas de observação clínica,\napresenta dor torácica de forte intensidade, palpitações, associada à dispneia súbita. Nega\nvômitos. Permanece estável hemodinamicamente, sem alterações neurológicas. Realizado\neletrocardiograma abaixo. A conduta mais adequada neste caso é:","options":{"A":"Amiodarona 300 mg em bolus.","B":"Cardioversão elétrica.","C":"Amiodarona 150 mg em bolus.","D":"Metoprolol 25 mg via oral."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/249228.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-216246","number":"216246","sourceNumber":"216246","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente que desenvolve Insuficiência Cardíaca - IC devido à Fibrilação atrial - FA, com\nresposta ventricular rápida (usualmente > 150 bpm), está ADEQUADO apenas que:","options":{"A":"Entidade denominada ?taquicardiomiopatia?, de prognóstico mais favorável com a correção da\nFA.","B":"Entidade denominada ?taquicardiomiopatia?, de prognóstico menos favorável com a correção da\nFA.","C":"Entidade não denominada ?taquicardiomiopatia?, de prognóstico mais favorável com a correção\nda FA.","D":"Entidade denominada ?cardiomiopatia?, de prognóstico mais favorável com a correção da FA."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-216263","number":"216263","sourceNumber":"216263","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Vários estudos documentaram a efetividade do Cardiversor desfibrilador implantável -\nCDI em reduzir o risco de morte súbita em pacientes de alto risco (prevenção secundária) quando\ncomparados às drogas antiarrítmicas. Sendo ADEQUADO que:","options":{"A":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","B":"Os estudos de prevenção primária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","C":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que não foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias ventriculares complexas, induzidas por estimulação\nventricular no estudo eletrofisiológico.","D":"Os estudos de prevenção secundária contemplaram, em sua maioria, pacientes portadores de\nmiocardiopatia de etiologia isquêmica, que foram recuperados de morte súbita ou que\napresentassem TVS e pacientes com arritmias supraventriculares complexas, induzidas por\nestimulação ventricular no estudo eletrofisiológico."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-216318","number":"216318","sourceNumber":"216318","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em pacientes com Insuficiência Cardíaca - IC e Fibrilação atrial - FA a opção por\ncardioversão elétrica de urgência só é indicada se houver deterioração hemodinâmica. Quanto à\nabordagem química das outras situações, podemos apenas considerar inteiramente CORRETO o\nitem:","options":{"A":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do ritmo sinusal, após a reversão espontânea ou\nelétrica.","B":"A amiodarona não é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do ritmo sinusal, após a reversão espontânea ou\nelétrica.","C":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, mas não para reduzir\nos paroxismos de FA e ajudar na manutenção do\nritmo sinusal, após a reversão espontânea ou\nelétrica.","D":"A amiodarona é eficaz para reverter quimicamente a FA para ritmo sinusal, reduzir os\nparoxismos de FA e ajudar na manutenção do\nritmo sinusal, após a reversão espontânea, nunca\npara a elétrica."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-216233","number":"216233","sourceNumber":"216233","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Nos pacientes com taquicardia juncional, qual é a medida terapêutica a se adotar?","options":{"A":"Resfriamento.","B":"Cardioversão.","C":"Atropina.","D":"Amiodarona."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-215530","number":"215530","sourceNumber":"215530","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Escolha, entre as alternativas a seguir, aquela que apresenta uma droga que NÃO deve\nser administrada pela cânula orotraqueal.","options":{"A":"Lidocaína.","B":"Atropina.","C":"Bicarbonato de sódio.","D":"Adrenalina."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-201758","number":"201758","sourceNumber":"201758","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 54 anos queixando-se de palpitações há 72 horas, após ingestão de bebida\nalcoólica, procura atendimento de urgência. Sem antecedentes de doença cardíaca. PA = 140 x 80\nmmHg; FC = 168 bpm, e SatO2 = 98%. Orientado, sem outras queixas. ECG mostra fibrilação\natrial. Qual a melhor conduta?","options":{"A":"Amiodarona + enoxaparina + ecocardiograma transtorácico.","B":"Metoprolol + enoxaparina + ecocardiograma\ntransesofágico.","C":"Propafenona + enoxaparina + ecocardiograma\ntransesofágico.","D":"Cardioversão elétrica + alta na reversão.","E":"Cardioversão elétrica + enoxaparina + alta na reversão."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-219902","number":"219902","sourceNumber":"219902","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 48 anos queixa-se de fraqueza generalizada e dispneia. Ao exame físico,\nausculta-se desdobramento da segunda bulha que é constante, mas aumenta quando o paciente\ninspira. O ritmo cardíaco é regular, a primeira bulha é normal e não há sopros. Qual das seguintes\nalterações eletrocardiográficas é MAIS COMPATÍVEL com os achados auscultatórios observados\nno paciente?","options":{"A":"Bloqueio completo do ramo direito do feixe de His.","B":"Elevação do segmento ST nas derivações anteriores.","C":"Redução da duração do intervalo PR.","D":"Repolarização precoce."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183596","number":"183596","sourceNumber":"183596","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os pacientes que se encontram na fase aguda de miocardite podem desenvolver tanto\ntaquiarritmias como bradiarritmias. Estando INADEQUADO que:","options":{"A":"Essas arritmias frequentemente desaparecem após a fase aguda da miocardite, sendo a terapia,\nhabitualmente, de suporte.","B":"As taquicardias supraventriculares (TSV), principalmente fibrilação e flutter atrial, podem\ninduzir\nou agravar a IC.","C":"A abordagem inicial recomendada para a TSV sustentada sintomática é a restauração do ritmo\nsinusal através de cardioversão elétrica ou química.","D":"Geralmente se recomenda terapia antiarrítmica para extrassístoles atriais e ventriculares\nassintomáticas."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183611","number":"183611","sourceNumber":"183611","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os pacientes que se encontram na fase aguda de miocardite podem desenvolver\nanormalidades de condução que muitas vezes\nsão transitórias, mas podem também desenvolver\ntaquiarritmias. Quanto a isso, assinale a alternativa INCORRETA:","options":{"A":"Taquicardias ventriculares sustentadas assintomáticas não devem receber terapia específica.","B":"As arritmias ventriculares sustentadas devem ser tratadas com drogas antiarrítmicas após a\nreversão elétrica aguda.","C":"A opção é limitada a amiodarona.","D":"Devido aos efeitos pró-arrítmicos, drogas de classe I e III (exceto a amiodarona) são geralmente\nevitadas nesses pacientes."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182822","number":"182822","sourceNumber":"182822","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"ECG compatível com Fenômeno de Ashman (ou de Gouaux-Ashman) seria\nADEQUADAMENTE descrito assim:","options":{"A":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão da diminuição do período refratário no sistema de condução, principalmente\nno ramo direito do His, sendo mais frequente na FA.","B":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão do aumento do período refratário no sistema de condução, principalmente no\nramo esquerdo do His, sendo mais frequente na FA.","C":"condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após um\nciclo longo, em razão do aumento do período refratário no sistema de condução, principalmente no\nramo direito do His, sendo mais frequente na FA.","D":"Condução aberrante, que ocorre em batimento que segue imediatamente um ciclo curto após\num ciclo longo, em razão do aumento do\nperíodo refratário no sistema de condução, principalmente\nno ramo direito do His, sendo muito raro na FA."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182729","number":"182729","sourceNumber":"182729","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os tremores musculares podem afetar o ECG da seguinte forma:","options":{"A":"Tremores musculares não podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano.","B":"Tremores musculares podem interferir na linha de base, mas não mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano.","C":"Tremores musculares podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente com paralisia.","D":"Tremores musculares podem interferir na linha de base, mimetizando alterações\neletrocardiográficas como FLA e FV no paciente parkinsoniano."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182732","number":"182732","sourceNumber":"182732","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O comprometimento agudo do sistema nervoso central, pode levar aos seguintes\nachados no ECG:","options":{"A":"ondas T negativas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; irreversibilidade das alterações.","B":"ondas T negativas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; reversibilidade das alterações.","C":"ondas T positivas gigantes, simulando isquemia subepicárdica (onda T cerebral); aumento do\nintervalo QTc; reversibilidade das alterações.","D":"ondas T negativas gigantes, mas não simulando isquemia subepicárdica (onda T cerebral);\naumento do intervalo QTc; reversibilidade das alterações."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183588","number":"183588","sourceNumber":"183588","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As alternativas abaixo apresentam causas cardíacas de síncope, EXCETO","options":{"A":"lesão obstrutiva como estenose pulmonar.","B":"arritmias cardíacas.","C":"hipercianose.","D":"DPOC."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183598","number":"183598","sourceNumber":"183598","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os sintomas prodrômicos de síncope neurogênica incluem, EXCETO","options":{"A":"sonolência.","B":"sudorese.","C":"palidez.","D":"náuseas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183115","number":"183115","sourceNumber":"183115","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa CORRETA.","options":{"A":"O tônus vagal excessivo é a forma mais comum de síncope autonômica.","B":"A síncope reflexa resulta de aumento do tônus simpático associado a determinados eventos.","C":"O tônus vagal excessivo ocorre, exclusivamente, na mudança brusca de decúbito supino para\nortostático.","D":"Na síncope autonômica a perda de consciência é repentina e não ultrapassa dois minutos de\nduração."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182746","number":"182746","sourceNumber":"182746","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O sistema Renina-Angiotensina-Aldosterona (SRAA) desempenha um papel importante\nna fisiopatologia da IC, sendo INCORRETO apenas que:","options":{"A":"A ativação do sistema Renina-Angiotensina-Aldosterona (SRAA) piora o remodelamento.","B":"A inibição desse sistema leva à melhora da evolução dos pacientes com IC tanto em\nremodelamento, mas não em mortalidade.","C":"DM causa ativação do SRAA, com aumento de renina, angiotensina II e aldosterona.","D":"A importância do sistema adrenérgico na IC é conhecida e sua ativação piora o prognóstico dos\npacientes."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161170","number":"161170","sourceNumber":"161170","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente foi trazido por resgate com mal-estar geral, prostração e dispneia de inícios\nsúbitos nesta manhã. Seu Eletrocardiograma\ndemonstrava uma taquiarritmia que você\ninadequadamente indicou terapia elétrica, causando grave complicação instantânea. Felizmente\napós diversas manobras, foi conseguida a reversão do quadro. A complicação provocada pode ser\nexplicada por uma das opções a seguir. Aponte-a.","options":{"A":"A desfibrilação e cardioversão elétrica consistem na aplicação de corrente elétrica de alta\nenergia para reversão de arritmias cardíacas geradas pelo mecanismo de reentrada.","B":"Na desfibrilação, esta corrente elétrica é aplicada em qualquer momento do ciclo cardíaco.","C":"Na cardioversão elétrica, esta corrente é sempre sincronizada com os complexos QRS do\neletrocardiograma.","D":"Na cardioversão elétrica, esta corrente é sempre sincronizada para que não seja administrada\ndurante o período vulnerável da\nrepolarização ventricular (onda T)."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161176","number":"161176","sourceNumber":"161176","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente foi trazido ao Hospital por familiares com quadro de palpitação e mal-estar\nsúbitos nesta tarde, previamente hipertenso e\netilista. Seu Eletrocardiograma demonstrava uma\narritmia cardíaca, que foi adequadamente tratada com choque elétrico com bons resultados. Frente\na esse quadro, indique a alternativa CORRETA.","options":{"A":"Nos desfibriladores externos, o choque elétrico é aplicado por intermédio das pás manuais, as\nquais o operador posiciona sobre o tórax, exercendo pressão de aproximadamente 3 kg.","B":"No caso de flutter atrial, considera-se iniciar o procedimento com 150 J.","C":"Caso o ritmo for fibrilação atrial, considera-se o uso de energia inicial de 300 J.","D":"No caso de taquicardia supraventricular, considera-se iniciar o procedimento com 50 J."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161330","number":"161330","sourceNumber":"161330","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente previamente cardiopata evoluiu com súbito mal-estar seguido de perda de\nconsciência. Foi levado ao hospital, sendo desde sua chegada iniciado processo de reanimação.\nQuanto ao uso e indicações de desfibrilador, podemos afirmar que existem cuidados a serem\nrealizados durante sua utilização. Assinale a alternativa CORRETA em relação a esses cuidados.","options":{"A":"Não existe necessidade de depilação quando do excesso de pelos torácicos.","B":"Na presença de marcapasso definitivo, não existe maiores cuidados no uso do desfibrilados.","C":"Tórax molhado: não necessita de secar por completo o tórax da vítima.","D":"Vítima sobre uma poça d?água não há problema, porém se essa poça d?água também envolver\no socorrista, remova a vítima para outro local, o\nmais rápido possível."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161185","number":"161185","sourceNumber":"161185","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Senhora de 63 anos de idade apresentou súbito mal-estar nesta manhã, sendo\nimediatamente trazida por familiares ao\nHospital. Apresentava intensa dispneia e palpitações, sua\nausculta cardíaca demonstrava ritmo irregular. Seu ECG demonstrava taquiarritmia, sendo então\ndecidido uso de cardioversão elétrica. Dentre as etapas a seguir referentes a esse procedimento,\nindique a opção INCORRETA.","options":{"A":"Durante a cardioversão, deve-se acionar o botão de sincronização antes da administração de\ncada choque, nesta situação, geralmente,\naparece um sinal gráfico no monitor confirmando a\nsincronização. Selecione o nível adequado de energia de acordo com a arritmia, conforme\nmencionado.","B":"Aplique gel nas pás e posicioná-las sobre a superfície do tórax do paciente na posição\nadequada. Aplique uma pressão sobre as pás. Carregue o desfibrilador/cardioversor.","C":"Verifique se o operador e os demais socorristas não estão mantendo contato com o paciente ou\ncom a maca ou cama, pois existe o risco de\ncondução da corrente elétrica para estes indivíduos,\npodendo causar graves complicações. Também, verifique a ausência de administração de oxigênio\nem alto fluxo próximo ao desfibrilador devido ao risco de formação de faíscas.","D":"Aplique o choque elétrico, mantendo as pás sobre o tórax do paciente por alguns minutos,\nprincipalmente, durante a cardioversão, pois pode haver um pequeno atraso na administração do\nchoque devido à necessidade de adequada sincronização."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161290","number":"161290","sourceNumber":"161290","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando após criteriosa avaliação clínica de uma bradicardia sinusal é constatada a\nausência de causas reversíveis, o implante de marca-passo definitivo é tratamento efetivo para a\ndisfunção sinusal sintomática. Sobre isso, assinale a alternativa INCORRETA.","options":{"A":"Apesar de não modificar a taxa de sobrevida, o marca-passo permite a melhora tanto dos\nsintomas como da qualidade de vida dessa população.","B":"Portadores de doença do nó sinusal na ausência de estimulação cardíaca (ou seja, sem\n\nmarca-passo) raramente evoluem com eventos sintomáticos que podem exigir tratamento imediato,\ntais como síncope, insuficiência cardíaca\ndescompensada e fibrilação atrial permanente, além de\ntaquiarritmias paroxísticas com resposta ventricular elevada.","C":"O implante de marca-passo melhora significativamente a qualidade de vida dos portadores de\ndoença do nó sinusal a partir do terceiro\nmês do procedimento, sem modificar a mortalidade por\nqualquer causa.","D":"Em pelo menos metade dos pacientes com doença do nó sinusal, observam-se bradiarritmias\nalternando-se com taquiarritmias atriais."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161337","number":"161337","sourceNumber":"161337","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idoso é trazido por neto ao hospital, após sentir fortes dores torácicas nesta manhã. Foi\nadmitido na sala de emergência devido ao seu histórico de hipertenso e cardiopata. Foi\nmonitorizado e, durante o período em que aguardava novos exames laboratoriais, perdeu os\nsentidos, sendo que não existia, neste momento, complexos QRS organizados no monitor. Iniciado\nprotocolo de reanimação, que entre outros inclui terapêutica elétrica, podemos admitir que:","options":{"A":"na desfibrilação deve-se utilizar a máxima energia do aparelho. Se esta orientação é\ndesconhecida deve ser administrado choque de 200 J no caso do monofásico.","B":"na desfibrilação deve-se utilizar a máxima energia do aparelho; sendo aplicada 360 J no\ndesfibrilador monofásico e de 120 a 200 J no desfibrilador bifásico, conforme orientação do\nfabricante.","C":"pode ser utilizado cardioversão com efetividade, caso esteja utilizando 360 J.","D":"não deve ser tomada como prioritária em sua sequência de reanimação."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161221","number":"161221","sourceNumber":"161221","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A frequência cardíaca normalmente varia de 60 bpm a 100 bpm. Ritmos com\nFrequência Cardíaca < 60 bpm são definidos como\nbradicardia, podendo ser assintomática ou\nsintomática. As bradicardias sintomáticas têm características clínicas comuns, marcadas,\nsobretudo, pela síndrome do baixo fluxo, comumente ocasionadas por doença do nó sinusal. Na\ndoença do nó sinusal, o implante de marca-passo é indicado nos casos a seguir, com EXCEÇÃO\nde","options":{"A":"incompetência cronotrópica sintomática.","B":"bradicardia sinusal sintomática, secundária ao uso de fármacos indispensáveis.","C":"síncope de origem indeterminada, com evidências eletrocardiográficas de disfunção do nó\nsinusal documentada ou provocada no estudo eletrofisiológico.","D":"disfunção do nó sinusal com frequência cardíaca < 60 bpm em vigília, sem correlação clara entre\nos sintomas e a bradicardia documentada."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161231","number":"161231","sourceNumber":"161231","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A doença do nó sinusal, condição em que existe disfunção do nó sinusal sintomática, é\ncaracterizada por anormalidades da geração e da condução do estímulo sinusal, levando a ritmos\ncom frequência cardíaca < 60 bpm, que são definidos como bradicardia. Assim, aponte a alternativa\nINCORRETA.","options":{"A":"As bradicardias sintomáticas têm características clínicas comuns, marcadas, sobretudo, pela\nsíndrome do baixo fluxo cerebral e/ou sistêmico, cujos sintomas mais comuns são tontura,\n\npré-síncope, síncope, fadiga, dispneia de esforço e bradipsiquismo,\n\nsendo comumente ocasionadas por doença do nó sinusal e bloqueio atrioventricular.","B":"As sintomáticas, geralmente, são de causas fisiológicas, representadas por bradicardia sinusal e\nritmos de escape da junção atrioventricular.","C":"Fatores extrínsecos também podem causar bradicardia, como uso de fármacos que deprimem o\nsistema de condução ou distúrbios metabólicos ou endócrinos, como hipotireoidismo,\nhiperpotassemia e hipotermia.","D":"Considerando que não há fármacos adequados para o tratamento das bradicardias sintomáticas\nirreversíveis, o implante de marca-passo definitivo é o tratamento mais indicado para essas\nafecções."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161355","number":"161355","sourceNumber":"161355","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A terapia elétrica apresenta diversas utilidades no tratamento de patologia crônica e\naguda, tanto ambulatorial como em emergências. Sobre isso, aponte a alternativa que NÃO se\nmostra adequada.","options":{"A":"No caso de flutter atrial ou taquicardia supraventricular, considera-se iniciar o procedimento\ncom\n50 J; e se o ritmo for fibrilação atrial,\nconsidera-se o uso de energia inicial de 200 J.","B":"Instabilidade de Fibrilação Atrial indica somente terapêutica elétrica.","C":"Somente situações de parada cardíaca indicam terapêutica com choque.","D":"Em arritmias ventriculares os aparelhos não são capazes de analisar o melhor momento dentro\ndo ciclo cardíaco para descarregar a corrente\nelétrica."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161205","number":"161205","sourceNumber":"161205","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante procedimento eletivo com anestesia local na sala de pequenas cirurgias,\nocorreu a emergência de um paciente eletivo\nda clínica cirúrgica. Você então foi chamado a ajudar\nno socorro do paciente apenas com a informação de que ele já era cardiopata em uso de digoxina\ne amiodarona. Na sua avaliação inicial, detectou bradicardia com grande repercussão clínica, assim\nindicou o uso de marca-passo transcutâneo. Referente aos passos desse procedimento, marque a\nopção INCORRETA:","options":{"A":"Observe qual é o ponto de corte para que haja captura de algumas das espículas do MP. A partir\ndesse ponto, deixe o valor da corrente elétrica com margem de segurança de 30% acima desse\nlimiar.","B":"Fixe as pás autoadesivas no tórax despido da vítima. Coloque o eletrodo anterior à esquerda do\nesterno, centralizado e o mais próximo possível do ponto de máximo do impulso cardíaco. Coloque\no eletrodo posterior nas costas, diretamente atrás do\n\neletrodo anterior e à esquerda da coluna torácica. A alternativa a essa posição dos eletrodos é a\ncolocação semelhante à do DEA: uma das pás deve ser posicionada na região sobre o ápice do\ncoração e a outra sobre a região paraesternal direita.","C":"Selecione inicialmente a frequência cardíaca desejada (geralmente em torno de 80 bpm, em\ncasos de bradicardias). Em seguida, ajuste a\ncorrente elétrica a ser administrada, aumentando\ngradualmente o valor de corrente elétrica a partir do valor mínimo, até que se obtenha captura\nelétrica. Geralmente, a captura se caracteriza pelo alargamento do complexo QRS com uma onda T\nlarga e oposta à polaridade do QRS.","D":"Avalie a resposta hemodinâmica do MP pelo pulso e pela pressão arterial. Forneça analgesia e\nsedação, conforme necessário."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161250","number":"161250","sourceNumber":"161250","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A indicação mais comum para o implante de marca-passo definitivo é a doença do nó\nsinusal, condição em que existe disfunção do nó sinusal sintomática, caracterizada por\nanormalidades da geração e da condução do estímulo sinusal. A respeito das afirmações a seguir,\nindique aquela que é considerada INADEQUADA.","options":{"A":"Existe a facilitação na passagem do estímulo do nó sinusal para o tecido atrial.","B":"Ocorrem anormalidades da transmissão do impulso dentro dos átrios e para o sistema de\ncondução cardíaco.","C":"Disfunção na atividade de marca-passos subsidiários, e taquiarritmias crônicas e paroxísticas,\nprincipalmente a fibrilação atrial.","D":"A etiologia da doença do nó sinusal pode ser intrínseca, que inclui processos inflamatórios,\ninfecciosos e imunológicos, fibrose\ndegenerativa, disfunção de canais iônicos e remodelamento do\nnó sinusal."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161258","number":"161258","sourceNumber":"161258","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dados epidemiológicos a respeito da doença do nó sinusal demonstram que as\nseguintes afirmativas estão adequadas, com EXCEÇÃO de uma. Assinale-a.","options":{"A":"A doença do nó sinusal afeta 1 a cada 600 pessoas com idade > 65 anos (média de 74 anos),\nsomente ocorrendo em idosos.","B":"Os distúrbios eletrolíticos mais comumente envolvidos são a hiperpotassemia, a hipopotassemia\ne a hipocalcemia.","C":"Os sintomas mais comuns dos portadores de doença do nó sinusal são tonturas, vertigens,\npré-síncope, síncope, palpitações, intolerância ao exercício e fadiga, geralmente intermitentes.","D":"As principais manifestações eletrocardiográficas da doença do nó sinusal são bradicardia\nsinusal, pausas ou paradas sinusais, bloqueio\nsinoatrial, taquicardia atrial, fibrilação atrial e\nincompetência cronotrópica."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161368","number":"161368","sourceNumber":"161368","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina, 70 anos de idade, deu entrada desacordada no hospital trazida por\ncorpo de bombeiros, tendo ocorrido perda de consciência após episódio de intensa dispneia, nesta\ntarde. Histórico de ser cardiopata com tratamento irregular. Exame físico demonstra estertores\npulmonares, ritmo cardíaco irregular e taquicardíaco. Monitor cardíaco com frequência acima de\n140 bpm, QRS fino, mas com distâncias variáveis. Podemos assim propor que o tratamento\nINDICADO deve considerar que:","options":{"A":"na cardioversão elétrica, pode-se realizar o choque sequencial com um nível decrescente de\nenergia se o primeiro choque não reverteu à arritmia, lembrando sempre de sincronizar o\ncardioversor antes de cada procedimento.","B":"se o ritmo for fibrilação atrial, considera-se o uso de energia inicial de 200 J.","C":"a corrente é sempre sincronizada com os complexos QRS do eletrocardiograma para que não\nseja administrada durante o período vulnerável da onda P.","D":"está indicado desfibrilação."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161175","number":"161175","sourceNumber":"161175","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Bradiarritmias são graves emergências médicas potencialmente fatais. Ocorrendo a\nindicação do procedimento de marca-passo, assinale a alternativa ADEQUADA frente à\ndesvantagem desta técnica.","options":{"A":"O Marca-Passo Transcutâneo (MPTC) é um dispositivo que, em geral, causa desconforto e dor\nao paciente, visto que correntes elétricas de\n50 a 100 miliampères (mA) são necessárias.\nConsidere analgesia e sedação do paciente.","B":"A desvantagem do Marca-Passo Transcutâneo (MPTC) é a necessidade de alta energia em\nrazão da necessidade de fazer a energia\naplicada vencer a impedância transtorácica e chegar ao\nmiocárdio. A impedância transtorácica consiste na resistência\n\nda parede torácica ao fluxo da corrente elétrica e pode também ser influenciada pelo tamanho dos\neletrodos.","C":"Por ser eficaz, rápido, seguro e não invasivo é bastante útil em serviços de emergência. Porém,\no Marca-Passo Transcutâneo (MPTC) é um procedimento\ntemporário e deve ser utilizado como\nponte até a colocação de um marca-passo transvenoso ou permanente, se indicados.","D":"Verifique se há a opção de MPTC em seu monitor/desfibrilador/cardioversor. Lembrete: nem\ntodos os aparelhos dispõem dessa função."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161374","number":"161374","sourceNumber":"161374","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idoso, 80 anos, referia intenso mal-estar de início nesta manhã com palpitação,\nsudorese de dispneia. Foi trazido ao pronto\natendimento onde ocorreu diagnóstico\neletrocardiográfico de fibrilação atrial aguda. Foi proposto tratamento elétrico com desfibrilação\nde\nvez que era emergência, porém logo após o choque inicial o paciente evoluiu em parada cardíaca.\nTeoricamente, podemos AFIRMAR que:","options":{"A":"Isso pode ter ocorrido devido ao fato de que, na desfibrilação, a corrente elétrica é aplicada em\nqualquer momento do ciclo cardíaco.","B":"Nessa situação a corrente foi sincronizada com os complexos QRS do eletrocardiograma para\nque não seja administrada durante o período\nvulnerável da despolarização ventricular.","C":"Cardioversão pode potencialmente desencadear uma fibrilação ventricular caso associada à\nonda P.","D":"Nessa situação a corrente foi sincronizada com os complexos QRS do eletrocardiograma para\nque não seja administrada durante o período\nrefratário da despolarização ventricular."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161326","number":"161326","sourceNumber":"161326","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Adulto de 34 anos apresentou súbita dor torácica seguida de síncope nesta manhã. Foi\nsocorrido e iniciado manobras de reanimação com sucesso, no sentido de retorno à circulação\nespontânea. Frente a essa situação, podemos AFIRMAR que:","options":{"A":"somente após 24 horas podemos concluir clinicamente desfecho ruim neurológico.","B":"a Pressão Arterial Sistólica inferior a 90 mmHg no pós PCR está associada a pior desfecho.","C":"o período para avaliação neurológica não deve ser maior nos casos de suspeita de efeito\nresidual de sedação.","D":"existe uma meta geral para perfusão orgânica de todos os vitimados de parada cardíaca."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161190","number":"161190","sourceNumber":"161190","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Podemos considerar dentro da abordagem do paciente infartado uma grande\nimportância da FV como mecanismo de óbito\nprecoce. Estima-se que a desfibrilação salve cerca de\nseis vezes mais vidas que o tratamento trombolítico, mas depende de sua rápida aplicação ao\npaciente. Referente ao impacto potencial, em termos de benefício, ao se intervir na fase\n\npré-hospitalar no IAM, assinale a alternativa INCORRETA.","options":{"A":"Identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma\nnova estratégia de grande difusão na população.","B":"Fornecer maior informação somente a profissionais de saúde quanto aos sintomas de IAM e à\nimportância de uma busca rápida por auxílio médico, evitando erros de conduta.","C":"Realizar treinamento difuso da população para atendimento de urgência nos moldes do BLS.","D":"Disponibilizar desfibriladores externos automáticos em locais públicos de grande circulação."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161341","number":"161341","sourceNumber":"161341","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"De acordo com a maioria das diretrizes nacionais e internacionais atuais, ocorre a\nnecessidade de grande conhecimento médico a respeito das terapias elétricas utilizadas em\nsituações de emergência. Sobre isso, podemos considerar ADEQUADA a seguinte afirmativa ou\nnegativa. Aponte-a.","options":{"A":"Na cardioversão elétrica, pode-se realizar o choque sequencial com um nível crescente de\nenergia se o primeiro choque não reverteu a arritmia.","B":"Desfibrilação sempre utilizará uma corrente monofásica.","C":"A posição de qual pá está em seu local; será determinante do sucesso, mesmo estando ambas\nnos locais adequados no tórax.","D":"Desfibrilação é adequada em todos os ritmos sem pulso."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161149","number":"161149","sourceNumber":"161149","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante o período noturno, ocorreu algo inusitado no seu plantão, isto é, você foi\nchamado a avaliar um paciente que estava na\nobservação e, ao ir até o seu leito, descobriu que ele\nestava em Parada Cardíaca. Você realizou os procedimentos que não foram bem sucedidos. Sobre\nesse caso, indique a opção INCORRETA.","options":{"A":"A Parada Cardiorrespiratória (PCR) é uma das situações clínicas de maior emergência na\nmedicina. A rapidez e a eficácia das intervenções adotadas são fundamentais e interferem\ndiretamente no prognóstico da vítima.","B":"Dos adultos vítimas de parada cardíaca em ambiente intra-hospitalar, grande parte apresenta\nritmo de atividade elétrica sem pulso e\nAssistolia como ritmo inicial de PCR.","C":"Os ritmos de fibrilação ventricular e taquicardia ventricular sem pulso (FV/TVSP) são\nresponsáveis por parte dos eventos de PCR em ambiente intra-hospitalar, apresentando as\nmenores taxas de sobrevida.","D":"Diversos fatores têm sido relacionados com maior sobrevida hospitalar, como o local onde\nacontece o evento, dias da semana quando\ncomparados com finais de semana, eventos que\nacontecem no período diurno quando comparados com o período noturno, eventos presenciados,\nidade menor de 65 anos, presença de função normal do ventrículo esquerdo antes do evento,\nduração do evento, entre outros."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161159","number":"161159","sourceNumber":"161159","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante esta manhã você recebeu, transferido de outro serviço de atendimento\nprimário, um paciente grave em insuficiência\nrespiratória por DPOC, no qual o colega\nadequadamente utilizou manejo de via aérea com máscara laríngea, o que levou você a elogiá-lo\nmuito, AFIRMANDO que:","options":{"A":"Embora a máscara laríngea ofereça proteção absoluta das vias aéreas contra aspiração, a\nfrequência desta complicação é maior do que quando a ventilação é realizada com dispositivo\nbolsa-válvula-máscara.","B":"Quando comparada com a intubação orotraqueal, a máscara laríngea oferece ventilação\nsuperior.","C":"Ventilação com sucesso, entre a minoria dos casos, tem sido reportada durante a realização das\nmanobras de RCP.","D":"Para profissionais da área da saúde treinados no seu uso, a máscara laríngea é uma alternativa\nao dispositivo bolsa-válvula-máscara ou à\nintubação orotraqueal."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161401","number":"161401","sourceNumber":"161401","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idosa de 68 anos de idade procurou serviço hospitalar com queixa de mal-estar e\nfadigas progressivas nas últimas semanas. Dentre os\nexames solicitados inicialmente, foi realizado\num Eletrocardiograma demonstrando padrão de baixa voltagem, o que NÃO pode ser decorrente\nde:","options":{"A":"embolia pulmonar.","B":"pericardite.","C":"obesidade.","D":"mamas volumosas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161172","number":"161172","sourceNumber":"161172","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quanto à análise do dióxido de carbono exalado no final da expiração expressado em\nmmHg ? PETCO ?, detectado pela capnografia\nquantitativa em pacientes intubados, indique a\nalternativa considerada INADEQUADA.","options":{"A":"Evidências sugerem que, se o paciente mantiver valores baixos de PETCO por longos períodos,\na despeito de condições ideais de RCP,\nfacilmente o Retorno Circulação Espontânea (RCE) será\natingido.","B":"O valor baixo pode ser levado em consideração por ocasião da definição de cessação de\nesforços.","C":"No entanto, se durante as manobras de RCP existe aumento abrupto do PETCO, é razoável\nconsiderar que houve RCE.","D":"Para os pacientes que não estão intubados, ainda não existem evidências da utilidade da\ncapnografia quantitativa."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161406","number":"161406","sourceNumber":"161406","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Diversas situações podem levar a graves arritmias cardíacas, podendo essas inclusive\nser geradores de Fibrilação Ventricular como\nconsequência. A doença descrita na síndrome de\nWolfParkinson White, contudo NÃO se relaciona com o seguinte dado. Assinale-o.","options":{"A":"Falha no Isolamento Elétrico Ventricular.","B":"Canais de Sódio defeituosos.","C":"Aumento do potencial arritmogênico.","D":"Feixe anômalo."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161415","number":"161415","sourceNumber":"161415","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentro da epidemiologia e algoritmos de avaliação do risco de fenômenos\ntromboembólicos da fibrilação atrial, podemos\nconsiderar INADEQUADA uma das alternativas.\nAponte-a.","options":{"A":"É a principal fonte emboligênica de origem cardíaca de que se tem conhecimento,\nrepresentando cerca de 45% dos casos quando\ncomparada com outras cardiopatias, como infarto\ndo miocárdio, aneurismas ventriculares e doenças valvares.","B":"As causas da formação de trombos são multifatoriais e estão relacionadas com a tríade de\nVirchow que inclui: (1) estase sanguínea atrial; (2) lesão endotelial; (3) aumento da\ntrombogenicidade sanguínea, própria dessa arritmia.","C":"No primeiro caso, a lenhificação do fluxo na região do Apêndice Atrial Esquerdo (AAE) favorece\na estase sanguínea e a formação de coágulos de\nfibrina, que se acumulam e geram o trombo.","D":"O cérebro, muito mais que membros e vísceras, é a região mais afetada, em cerca de 10% dos\ncasos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161416","number":"161416","sourceNumber":"161416","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentro da afirmativa de que as três condições estabelecidas por Virchow estão\npresentes em paciente com Fibrilação Atrial, indique a opção considerada INCORRETA.","options":{"A":"Lesões do endocárdio atrial apresentavam microtrombos e que estes eram os precursores de\ntrombos maiores. Pacientes que não apresentavam tais lesões tinham muito menor propensão à\ntrombose atrial.","B":"O atrito do sangue com o endocárdio, lesões miocitárias causadas por agressões teciduais\nsecundárias a citocinas inflamatórias (fator\nde necrose tumoral, interleucina 6, proteína C-reativa e\noutras) prejudicam ainda mais os miócitos atriais e expõem o tecido colágeno na superfície, o que\ndiminui a aderência de plaquetas e a deposição de fibrina, gerando o trombo. Dessa forma, a FA\ncria um estado pró-trombótico, hipercoagulável próprio.","C":"O aumento da agregação plaquetária, mais intensa no Átrio Esquerdo (AE), e a elevação dos\nníveis plasmáticos do fator de Von Wilebrand.","D":"Os fragmentos de protrombina e do fibrinogênio plasmático, dentre outros, confirmam essa\nmaior trombogenicidade sanguínea, independentemente de qualquer outro fator."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161417","number":"161417","sourceNumber":"161417","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Devido à maior propensão de pacientes com fibrilação atrial apresentarem risco,\ninerente à própria arritmia, de formar\ncoágulos, independentemente de outros fatores, ocorre a\nnecessidade de se identificar exatamente aquele de menor risco e excluí-lo da necessidade de\nanticoagular, por meio da inclusão de outros critérios de risco que possam caracterizá-los, ficando\nfora da necessidade de terapia com anticoagulante oral os pacientes com real risco baixo. Por essa\nrazão, outras variáveis, que foram identificadas, passaram a ser valorizadas como fatores de risco,\nEXCETO:","options":{"A":"Sexo masculino.","B":"Doença vascular periférica.","C":"Idade entre 64 e 75 anos.","D":"Idade acima de 75 anos."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161327","number":"161327","sourceNumber":"161327","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Pacientes com Fibrilação Atrial apresentam um risco maior de hemorragia quando\ntratados com Anticoagulante Oral, tornando-se\nnecessário não apenas avaliar o risco de\ntromboembolismo sistêmico, mas também de hemorragia quando o ACO for prescrito. Nas\nalternativas a seguir estão contidos os fatores associados a sangramento, com EXCEÇÃO de um.\nIndique-o.","options":{"A":"Hipertensão arterial não controlada (níveis pressóricos acima de 160 mmHg).","B":"Estabilidade da taxa de Razão Normalizada Internacional (RNI).","C":"Uso de fármacos anti-inflamatórios.","D":"Consumo de álcool."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161340","number":"161340","sourceNumber":"161340","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para adequadamente indicar o uso de drogas Antiarrítmicas, o que representa um\npapel relevante em ambas as estratégias no\nmanejo clínico da Fibrilação Atrial, devemos entender\nque as drogas antiarrítmicas mais utilizadas variam de acordo com suas características clínicas,\necocardiográficas e evolução de tratamentos anteriores. Após a avaliação de um caso de FA, o\npaciente pode ser alocado na estratégia de controle do ritmo ou controle da frequência. A respeito\ndisso, aponte a alternativa INCORRETA.","options":{"A":"A avaliação inicial deve definir a presença de cardiopatia estrutural, assim como avaliar se a\ncausa é reversível.","B":"Episódios causados por ingestão excessiva de álcool ou crise tireotóxica, que reverteram ao\nritmo sinusal espontaneamente ou após\ncardioversão, necessitam de tratamento com antiarrítmico\npor longo prazo.","C":"Deve-se lembrar que as medidas não farmacológicas, como atividade física regular, dieta\nbalanceada, controle de peso, otimização da qualidade do sono, devem ser instituídas.","D":"Além disso, alguns medicamentos não antiarrítmicos apresentam importante papel na prevenção\nde FA como as estatinas, os\n\ninibidores da enzima conversora da angiotensina e bloqueadores dos receptores da angiotensina I,\nespecialmente nos pacientes que também apresentam hipertensão arterial ou IC."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161347","number":"161347","sourceNumber":"161347","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Acerca da abordagem da arritmia, o controle da frequência na Fibrilação Atrial é uma\nestratégia importante para a prevenção de diversas complicações cardiovasculares, com\nEXCEÇÃO de","options":{"A":"lesão endotelial.","B":"cansaço e redução da capacidade de exercício.","C":"redução da morbidade.","D":"taquicardiomiopatia."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-161247","number":"161247","sourceNumber":"161247","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Leia as seguintes afirmativas sobre o atendimento intra-hospitalar do paciente vítima de\nafogamento. I. O controle da glicemia no paciente que sofreu afogamento deve focar na prevenção\nda hipoglicemia ou hiperglicemia e nas rápidas flutuações no estado glicêmico. II. Crianças que\nsofreram afogamento e que estão comatosas e apresentam tomografia computadorizada alterada\ngeralmente têm pior prognóstico. III. A pressão arterial deve ser continuamente monitorada. As\nafirmativas CORRETAS estão contidas em:","options":{"A":"I, II e III.","B":"I e II, apenas.","C":"II e III, apenas.","D":"I e III, apenas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134046","number":"134046","sourceNumber":"134046","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente deu entrada no hospital sem sinais vitais, familiares referem que ele vinha\nfalando no carro, apesar de não conseguir deambular. Histórico de insuficiência renal em\nhemodiálise, mas rebelde ao tratamento. Durante as diversas manobras de reanimação cardíaca\nfoi aventada a possibilidade do uso de bicarbonato de sódio EV no paciente. Para esse caso,\nindique a alternativa considerada INADEQUADA:","options":{"A":"O melhor tratamento para acidose na PCR são as compressões torácicas.","B":"Durante PCR a gasometria não se correlaciona com o estado tecidual.","C":"Não é benéfica na hipercalemia.","D":"Pode levar a aumento da geração de CO2."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134793","number":"134793","sourceNumber":"134793","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando iniciamos o tratamento de taquiarritmias de QRS estreito, devemos considerar\nque","options":{"A":"A Adenosina deve ser feita em bolus, de vez que sua metabolização é endotelial.","B":"A Lidocaína apresenta bom efeito atrial.","C":"A Amiodarona em bolus apresenta-se como opção segura.","D":"Sempre está indicada cardioversão química."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134053","number":"134053","sourceNumber":"134053","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando da abordagem das taquiarritmias de QRS estreito, a medicação\nAdenosina assume importante papel, tanto\ndiagnóstico quanto terapêutico. Porém, apresenta\nas seguintes contraindicações, com EXCEÇÃO do que consta em uma das alternativas.\n\nAponte-a.","options":{"A":"BAV de 2º.","B":"Disfunção do nó sinusal.","C":"Fibrilação atrial pré-excitada.","D":"Início do quadro há mais de 12 horas."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134076","number":"134076","sourceNumber":"134076","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual dos antiarrítmicos listados abaixo, NÃO apresenta precisa indicação para reversão\nde taquiarritmias de QRS estreito?","options":{"A":"Lidocaína.","B":"Amiodarona.","C":"Propafenona.","D":"Metoprolol."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134079","number":"134079","sourceNumber":"134079","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Podemos considerar como capazes de produzir uma morfologia de taquiarritmia de\nQRS largo, as seguintes condições clínicas, com\nEXCEÇÃO de uma alternativa. Assinale-a.","options":{"A":"TSV com BRE.","B":"TV.","C":"Taquicardia atrial multifocal.","D":"TSV com hipercalêmia."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134083","number":"134083","sourceNumber":"134083","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente masculino, 54 anos de idade, deu entrada em hospital queixando-se de\npalpitação e algumas tonturas. Durante realização de ECG foi visto o seguinte: sequência de 3 ou\nmais batimentos acima de 100 bpm, que se origina abaixo do feixe de His, aspecto de TV mono\nmórfica. Clinicamente está estável. Diante de tal caso, indique a alternativa que NÃO pode ser\nconsiderada como adequada.","options":{"A":"Amiodarona em 10 min EV.","B":"Coração pode estruturalmente ser normal.","C":"A estabilidade hemodinâmica não permite um tempo adicional para o diagnóstico.","D":"Lidocaína atualmente tem seu uso limitado."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134116","number":"134116","sourceNumber":"134116","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Adulto de 45 anos de idade deu entrada no hospital com queixa de dor torácica intensa\nde início há 30 minutos. Logo a seguir,\niniciou respiração em \"Gasping\", desaparecendo seus\nsinais vitais. Nas atuais condutas frente a essa emergência, qual das alternativas abaixo,\nmostra-se ADEQUADA?","options":{"A":"Vasopressina.","B":"Massagem cardíaca com no máximo 6 cm de compressão.","C":"Massagem cardíaca com no mínimo 100 por minuto, sendo realizadas o máximo possível.","D":"Iniciar com duas ventilações de resgate."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134860","number":"134860","sourceNumber":"134860","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina de 58 anos deu entrada no Hospital se queixando de mal-estar e\ndiscreto desconforto torácico de início nessa tarde, após discussão familiar. Logo após realização\nde ECG apresentou síncope e dispneia, logo a seguir, seu pulso central desapareceu. Qual das\nafirmativas abaixo pode ser considerada INADEQUADA?","options":{"A":"Primeira atitude é entubar a paciente devido à dispneia.","B":"Dentro da cadeia de sobrevivência, devemos solicitar por socorro.","C":"Iniciadas manobras de reanimação a sequência se dá utilizando ciclo de C-A-B.","D":"Iniciadas manobras de reanimação a sequência se dá utilizando ciclos de 30 massagens e duas\nventilações."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134122","number":"134122","sourceNumber":"134122","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante as emergências de parada cardíaca, frequentemente lidamos com a\nproblemática da dificuldade de via de acesso para infusão de medicação. Diante desse caso,\naponte a alternativa em que a afirmação a seguir seja considerada INADEQUADA.","options":{"A":"As doses recomendadas para via traqueal são de 2 a 2,5 vezes maiores que as doses\nadministradas por via IV.","B":"A via traqueal pode ser utilizada para infusão de adrenalina e lidocaína.","C":"Baixas concentrações plasmáticas de adrenalina, após administração endotraqueal, podem\nproduzir efeitos beta-adrenérgicos,\n\nresultando em vasodilatação.","D":"Via traqueal é opção de escolha."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134128","number":"134128","sourceNumber":"134128","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Desequilíbrios hidroeletrolíticos e emergências, tanto renais quanto cardíacas,\napresentam grande correlação, o que muitas das\nvezes torna difícil a condução do tratamento.\nApesar de sua frequente utilização, o Glucanato de Cálcio possui indicações específicas, das quais\nNÃO pode ser incluído","options":{"A":"intoxicação por agentes bloqueadores dos canais de cálcio.","B":"hiperpotassemia.","C":"hipocalcemia.","D":"rotineiramente, nas Paradas Cardíacas."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134032","number":"134032","sourceNumber":"134032","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando da ocorrência de graves arritmias de origem ventricular, apresenta grande\nimportância a escolha adequada da medicação a ser utilizada para o tratamento. No caso do uso\ndo Magnésio, podemos considerar que","options":{"A":"apresenta efetiva para taquicardia ventricular polimórfica em pacientes com intervalo QT normal.","B":"pode finalizar taquicardia ventricular polimórfica do tipo torção das pontas.","C":"pode ser recomendado rotineiramente na RCP.","D":"não apresenta atualmente uso recomendado."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134340","number":"134340","sourceNumber":"134340","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante manobras de reanimação cardiorrespiratória, existe a necessidade de\nventilação do paciente com AMBU. Caso ocorra uma frequência respiratória elevada, ocasiona","options":{"A":"Piora do retorno venoso.","B":"Melhora da oxigenação.","C":"Maior risco de lesão cardíaca.","D":"Piora da troca gasosa."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-110058","number":"110058","sourceNumber":"110058","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com relação ao Tromboembolismo secundário à reversão da fibrilação atrial aguda,\nassinale a alternativa CORRETA.","options":{"A":"Ocorre independente do tempo de início, porém o risco é maior após 48 horas de duração.","B":"Ocorre somente após 48 horas do início do episódio.","C":"Ocorre somente quando a fibrilação atrial se torna permanente, com duração maior que dois\nmeses.","D":"Ocorre em proporção semelhante, independente do tempo de duração."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-109980","number":"109980","sourceNumber":"109980","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A condição em que há MAIOR taxa de sobrevivência na parada cardiorrespiratória, fora\nde ambiente hospitalar, é em paciente com\nritmo inicial de:","options":{"A":"Assistolia com menos de dez minutos de duração.","B":"Fibrilação ventricular presenciada por outras pessoas.","C":"Taquicardia ventricular que evoluiu para assistolia.","D":"Atividade elétrica sem pulso que evoluiu com assistolia."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-286702","number":"286702","sourceNumber":"286702","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa que NÃO faz parte da doença do nó sinusal:","options":{"A":"Síndrome bradicardia-taquicardia.","B":"Pausa sinusal.","C":"Taquicardia por reentrada nodal.","D":"Bradicardia sinusal."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-286704","number":"286704","sourceNumber":"286704","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação a Hipertensão arterial em situações especiais, é CORRETO afirmar:","options":{"A":"A pressão arterial na criança deve ser aferida em todas as consultas nas crianças acima de 3\nanos.","B":"A pressão arterial na criança deve ser aferida em todas as consultas nas crianças acima de 5\nanos.","C":"No obeso e com mais de 50cm de circunferência do braço deve-se aferir a pressão arterial com\naparelho automático de punho.","D":"No idoso sempre nas aferições não devo me preocupar com o hiato auscultatório."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-286705","number":"286705","sourceNumber":"286705","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A indicação de marcapasso definitivo nos bloqueios atrioventriculares são todos abaixo,\nEXCETO:","options":{"A":"BAV do 2° grau do tipo 2 ou mobitz 2","B":"BAV do 2° grau do tipo 2:1","C":"BAV do 3° grau","D":"BAV do 2° grau do Tipo 1 ou mobitz 1"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-107648","number":"107648","sourceNumber":"107648","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"De acordo com as últimas diretrizes da American Heart Association (AHA - 2010),\nendossadas pela Sociedade Brasileira de\nCardiologia na I Diretriz de Ressuscitação\nCardiopulmonar e Cuidados Cardiovasculares de Emergência, marque a alternativa CORRETA:","options":{"A":"O soco precordial é recurso possivelmente útil em PCR não presenciada, na ausência de um\ndesfibrilador.","B":"A utilização do pistão mecânico durante o atendimento mostrou ser superior em termos de\nsobrevida quando comparado com a RCP padrão.","C":"A escolha de melhor método de ventilação deve basear-se na experiência do socorrista, sendo\naceitável a utilização do dispositivo de bolsa-válvula-máscara isoladamente ou em combinação com\na cânula orotraqueal.","D":"O dióxido de carbono exalado ao final da expiração (PETCO2) em níveis inferiores a 10 mmHg\ntem boa correlação com a qualidade de reanimação e com o retorno da circulação espontânea."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-81006","number":"81006","sourceNumber":"81006","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Correlacione os quadros clínicos dos pacientes abaixo com as doenças do quadro\nseguinte, assinalando a resposta certa da\ncorrespondência: 1. M.S.F., homem, 57 anos, etilista\npesado, hipertenso e diabético, com queixa de dispneia aos esforços, dispneia paroxística noturna,\nortopneia e edema de membros inferiores. Ao exame encontra-se ictérico (+/4), com ritmo cardíaco\nregular, em 3T (B3) e fígado palpável há 3 cm do RCD, edema MMI 2+/4 IECG com sobrecarga\nventricular esquerda. Radiografia de tórax com cardiomegalia.; II. A.M.S., Homem, 71 anos,\ntabagista pesado, etilista e hipertenso, com queixa de dispneia aos esforços e edema de membros\ninferiores. Ao exame encontra-se com pletora facial, com ritmo cardíaco regular, em 2T. B2\nhiperfonética. MV diminuído difusamente, edema MMII 2+/4 ECG com sobrecarga atrial direta; III.\nF.C.A., mulher, 54 anos, tabagista, e não etilista, com queixas de dispneia aos esforços, ortopneia\ne edema de membros inferiores. Ao exame encontra-se ictérica (++/4), com turgência jugular a 45º,\ncom ritmo cardíaco regular em 3T (B3) e fígado palpável há 4 cm do RCD, edema MMII 3+/4 ECG\ncom bloqueio de ramo direito. Radiografia de tórax com cardiomegalia; IV. R.G.L., mulher, 70 anos,\ndiabética, hipertensa, obesa, tabagista e etilista social, com queixas de dispneia aos esforços,\nortopneia e edema de membros inferiores. Ao exame encontra-se com ritmo cardíaco regular em\n2T, crepitantes em bases pulmonares bilateralmente, edema MMII e+/4 ECG com onda Q em\nparede anterior. 1. Miocardiopatia dilatada provavelmente de etiologia chagásica. 2. Miocardiopatia\nisquêmica. 3. Miocardiopatia dilatada provavelmente de etiologia alcoólica. 4. Cor pulmonale.","options":{"A":"I-1, II-3, III-2, IV-4.","B":"I-3, II-2, III-4, IV-1.","C":"I-3, II-2, III-1, IV-4.","D":"I-3, II-4, III-1, IV-2.","E":"I-1, II-4, III-3, IV-2."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61525","number":"61525","sourceNumber":"61525","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Residente da clínica médica, de plantão na enfermaria do hospital, é avisado pela\nenfermagem que um paciente está passando\nmal no leito. Ao chegar no quarto, o paciente não\nrespira e está sem pulso. É solicitado o carro de parada com desfibrilador e imediatamente dá\ninício\n\n, às compressões torácicas. Três minutos depois da chegada do médico, chega o desfibrilador\n(bifásico), e é conectado ao paciente. No\nmonitor mostra fibrilação ventricular. As condutas\nseguintes a serem executadas são:","options":{"A":"Interromper as compressões torácicas, carregar o desfibrilador até 350 J e intubar o paciente.","B":"Manter as compressões torácicas, administrar epinefrina e desfibrilar usando 200 Joules.","C":"Interromper as compressões torácicas, carregar o desfibrilador e desfibrilar usando 200 Joules.","D":"Interromper as compressões torácicas, intubar, administrar epinefrina e desfibrilar com 360\nJoules.","E":"Interromper as compressões torácicas, administrar amiodarona, carregar o desfibrilador e\ndesfibrilar três vezes usando 200 J, 200 J e 200 Joules."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-49803","number":"49803","sourceNumber":"49803","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em paciente com Estenose Mitral, o aparecimento de fibrilação atrial aguda com alta\nresposta ventricular pode precipitar o aparecimento de:","options":{"A":"Embolia Pulmonar;","B":"BAV de 1º grau;","C":"Infarto Agudo do Miocárdio;","D":"Edema pulmonar;","E":"Angina pectoris."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-26689","number":"26689","sourceNumber":"26689","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual a causa mais rara de embolia arterial de origem cardíaca?","options":{"A":"doença valvar reumática","B":"Mixoma atrial","C":"Cardiomiopatia dilatada","D":"Aneurisma de ventrículo esquerdo","E":"Fibrilação atrial"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-49365","number":"49365","sourceNumber":"49365","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem, 52 anos de idade, internado para tratamento de infarto agudo do miocárdio,\napresentou fibrilação ventricular na UTI, sendo prontamente assistido. Após três minutos de\nmassagens torácicas externas, foi submetido à desfibrilação elétrica, com retorno à circulação\nespontânea, após o primeiro choque. A próxima medida é fazer:","options":{"A":"atropina 1 mg, EV.","B":"amiodarona 150 mg, EV.","C":"bicarbonato de sódio a 8,4%, EV ? 1 ml/kg de peso.","D":"sulfato de magnésio 2 g, EV.","E":"vasopressina 40 U, EV."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35000","number":"35000","sourceNumber":"35000","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O eletrocardiograma (VER IMAGEM) é de um paciente, 70 anos de idade, sexo\nmasculino, que apresenta dor torácica típica\nhá cinco horas. O médico que o atendia obteve outras\ninformações adicionais, como paciente diabético há 10 anos, hipertenso há 5 anos, tabagista de 20\ncigarros/dia por 30 anos. Tem peso estimado em torno de 60 kg. Dados vitais na admissão\nmostravam PA: 90 x 50 mmHg, pulso: 110 bpm, FR: 24 inc/min; mucosas coradas. Cabeça e\npescoço: percebe-se estase jugular a 45°. Tórax: pulmões com MV rude bem distribuído, estertores\ncrepitantes em terço inferior de ambos os hemitóraces. ACV: B1 e B2 normais. B3+ em FM, SS\ngrau II/VI em FM, irradia para axila. Abdome: sem alterações. O ECG (VER IMAGEM) mostra a\nevolução do paciente após seis horas da admissão, durante episódio de instabilidade\nhemodinâmica. Nessa situação, é CORRETO afirmar:","options":{"A":"Trata-se de arritmia de reperfusão (taquicardia ventricular sustentada) após trombólise, não\nexigindo drogas antiarrítmicas ou\n\ndesfibrilação, será muito frequente a reversão espontânea.","B":"Trata-se de taquicardia ventricular não sustentada (D2 longo), devendo ser tratada com\namiodarona ataque de 5 mg/kg a 10 mg/kg e\n\nsolução venosa de manutenção 900 mg/dia.","C":"O paciente evoluiu com taquicardia ventricular e deve ser tratado com desfibrilação elétrica\nimediata, seguido de amiodarona venosa\n\ncontínua (ataque e manutenção).","D":"Trata-se de ritmo idioventricular acelerado, frequentemente atribuído à reperfusão química ou\nmecânica da artéria coronária, e o\n\ntratamento deve ser conservador inicialmente.","E":"Trata-se de ritmo de flutter ventricular e deve ser tratado da mesma forma que a taquicardia\nventricular, sem categorizar maior risco de morte."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/35000.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-11133","number":"11133","sourceNumber":"11133","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O uso de desfibrilador externo automático, DEA, tem sido preconizado como elemento\nfundamental dos cuidados referentes ao suporte básico de vida, na parada cardiorrespiratória,\nPCR. Esse uso encontra respaldo na seguinte assertiva:","options":{"A":"o DEA aplica choques que revertem precocemente a assistolia.","B":"o uso de DEA pode ser feito mesmo por pessoal não treinado.","C":"o acesso ao DEA, até o quinto minuto, modifica o prognóstico da PCR.","D":"após uso eficaz do DEA, as manobras de compressão torácica/ventilação são dispensáveis.","E":"o DEA é mais barato que as outras medidas de reanimação."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-13296","number":"13296","sourceNumber":"13296","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher, 73 anos de idade, com hipercolesterolemia, apresentou síncope de duração de\n5 minutos em domicílio. Filha nega o uso de\nmedicações, exceto sinvastatina e colírio para\nglaucoma. Esteve no cardiologista há 3 meses, que não recomendou novas medidas. Foi trazida ao\nPA onde se apresenta confusa, com pulso radial de 36 bpm, com pausas à inspiração. TA: 120 x 60\nmmHg, FR: 20 ipm. Mucosas coradas, sem sinais neurológicos de localização ou de irritação\nmeníngea. Pulmões limpos. Ausculta cardíaca mostra bulhas arrítmicas à custa de pausas, que\nduram até 30 segundos, além de sopro sistólico suave em foco aórtico. A melhor conduta imediata\né:","options":{"A":"fazer atropina EV","B":"fazer manitol EV","C":"instalar marca-passo transitório","D":"instalar noradrenalina EV","E":"fazer adrenalina EV"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-13297","number":"13297","sourceNumber":"13297","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher, 73 anos de idade, com hipercolesterolemia, apresentou síncope de duração de\n5 minutos em domicílio. Filha nega o uso de\nmedicações, exceto sinvastatina e colírio para\nglaucoma. Esteve no cardiologista há 3 meses, que não recomendou novas medidas. Foi trazida ao\nPA onde se apresenta confusa, com pulso radial de 36 bpm, com pausas à inspiração. TA: 120 x 60\nmmHg, FR: 20 ipm. Mucosas coradas, sem sinais neurológicos de localização ou de irritação\nmeníngea. Pulmões limpos. Ausculta cardíaca mostra bulhas arrítmicas à custa de pausas, que\nduram até 30 segundos, além de sopro sistólico suave em foco aórtico. O ECG dessa paciente\nrevela presença de onda P em D2, com intervalo PR de 0,13 segundos, períodos de pausa não\nprecedidos de onda P, não múltiplos do intervalo RR, com duração de até 50 segundos e QRS com\nmorfologia normal e eixo de 30 graus. Esses achados são compatíveis com:","options":{"A":"bloqueio AV de segundo grau, mobitz tipo II","B":"bloqueio AV de primeiro grau","C":"bloqueio AV total","D":"marca-passo migratório","E":"bradicardia sinusal com parada sinusal"},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-18050","number":"18050","sourceNumber":"18050","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente com suspeita de síndrome coronariana aguda, em observação monitorizada\nno pronto atendimento, apresenta síncope, sem\nresponsividade, presenciada pela enfermeira , há\ncerca de 2 minutos. O monitor de ECG mostra linha isoelétrica. Após as vias aéreas serem abertas\ncom reposicionamento da cabeça, o médico verifica que o paciente não respira. Há um dispositivo\nbolsa-máscara disponível e um desfibrilador não automático. A sequência de condutas a ser\nadotada, de acordo com os protocolos padrões de reanimação, é:","options":{"A":"insuflar vias aéreas 2 vezes com dispositivo bolsa-máscara, checar pulso. Se ausente, iniciar\ncompressões torácicas e ventilação no ritmo 30/2, checando pulso e ritmo cardíaco após 2 minutos.","B":"insuflar vias aéreas 2 vezes com dispositivo bolsa-máscara, checar pulso. Se ausente, pedir\ndesfibrilador, aplicar um choque com 360 joules e checar pulso e ritmo.","C":"pedir desfibrilador, imediatamente aplicar um choque com 360 joules e checar pulso e ritmo.","D":"insuflar vias aéreas 2 vezes com dispositivo bolsa-máscara, checar pulso. Se ausente, iniciar\ncompressões torácicas e ventilação no ritmo 30/2, até que o desfibrilador esteja pronto. Aplicar,\nassim que disponível, um choque com 360 joules e checar pulso e ritmo.","E":"insuflar vias aéreas 2 vezes com dispositivo bolsa-máscara, checar pulso. Se ausente, iniciar\ncompressões torácicas e ventilação no ritmo 15/1, com a enfermeira, até que o desfibrilador esteja\npronto. Aplicar, assim que disponível, um choque com 360 joules e checar pulso e ritmo."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343338","number":"343338","sourceNumber":"343338","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"HMN, masculino de 57 anos, grande tabagista e obeso, analisando se ECG foi\nencontrado Sobrecarga Atrial Esquerda (SAE) com onda\nP com componente negativo aumentado\n(final lento e profundo) na derivação V1. Podemos indicar como correto que:","options":{"A":"A área da fase negativa de pelo menos 0,09 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor\nsensibilidade que o critério isolado de duração aumentada.","B":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 11 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada.","C":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta pior sensibilidade que o critério isolado de duração aumentada.","D":"A área da fase negativa de pelo menos 0,04 mm/s, ou igual ou superior a 1 mm2, constitui o\nÍndice de Morris, que apresenta melhor sensibilidade que o critério isolado de duração aumentada."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343343","number":"343343","sourceNumber":"343343","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobrecarga Atrial Direita (SAD), está de acordo com o seguinte item correto:","options":{"A":"A onda P apresenta-se não apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","B":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 2,5 mm.","C":"A onda P apresenta-se apiculada com amplitude abaixo de 0,25 mV ou 2,5 mm.","D":"A onda P apresenta-se apiculada com amplitude acima de 0,25 mV ou 3,5 mm."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249970","number":"249970","sourceNumber":"249970","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Infelizmente os dados na literatura quanto à incidência de PCR no Brasil são escassos.\nPodemos entretendo indicar que ocorre erro no\nitem:","options":{"A":"O principal ritmo de PCR em ambiente extra-hospitalar não é a Fibrilação Ventricular (FV) e sim\na Taquicardia Ventricular (TV).","B":"A Fibrilação Ventricular (FV) e a Taquicardia Ventricular (TV), juntas chegando a quase 80% dos\neventos.","C":"A Fibrilação Ventricular (FV) e a Taquicardia Ventricular (TV) apresentam um bom índice de\nsucesso na reversão, se prontamente tratados.","D":"Quando a desfibrilação é realizada precocemente, em até 3 a 5 minutos do início da PCR, a taxa\nde sobrevida é em torno de 50% a 70%."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-215593","number":"215593","sourceNumber":"215593","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As crianças que recebem assistência ventilatória domiciliar devem ter sempre\ndisponíveis os seguintes materiais, EXCETO:","options":{"A":"Oxigênio suplementar.","B":"Monitor de eletrocardiograma.","C":"Bolsa autoinflável e máscara.","D":"Oxímetro de pulso."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-215568","number":"215568","sourceNumber":"215568","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao suporte ventilatório em portadores de\ninsuficiência respiratória crônica.","options":{"A":"As necessidades do indivíduo, além da estrutura domiciliar e do seguimento pela equipe de\nsaúde, devem ser levadas em conta no momento\nda decisão sobre a modalidade ventilatória a ser\nutilizada.","B":"As falhas repetidas de extubação traqueal ou da retirada de suporte não invasivo precedem à\ndecisão pela desospitalização ainda em uso desse suporte.","C":"O processo de suporte ventilatório domiciliar tem início no momento da alta do paciente.","D":"Antes da hospitalização é realizada a transição para o ventilador de uso domiciliar, com\ndeterminação das demandas específicas de cada indivíduo."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-181186","number":"181186","sourceNumber":"181186","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dos exames relacionados abaixo, qual não deve ser realizado de rotina no paciente\nafogado?","options":{"A":"Medida da pressão arterial.","B":"Eletroencefalograma.","C":"Controle do sensório.","D":"Gasometria."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-181192","number":"181192","sourceNumber":"181192","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA:","options":{"A":"A lesão cerebral primária no paciente vítima de afogamento ocorre durante a submersão,\nenquanto a secundária resulta de fatores como\nhipotensão, febre ou crises convulsivas.","B":"O diagnóstico de pneumonia é feito, muitas vezes, de forma equivocada por exames de\nradiografia, solicitados no início do quadro, em decorrência da presença de opacificações que\ncorrespondem à água nos pulmões.","C":"Afogamentos em piscina têm alto potencial de desenvolver infecção pulmonar precoce.","D":"Antes de tomar a decisão de iniciar antibióticoterapia no paciente afogado, recomenda-se\nobservar o paciente clinicamente por meio da\npresença de febre, leucocitose, novos infiltrados\npulmonares na radiografia e exames de culturas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-181195","number":"181195","sourceNumber":"181195","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"São medidas de prevenção de afogamento todas as abaixo, EXCETO:","options":{"A":"Sempre valorizar a sua capacidade de nadar, evitando o uso de coletes que possam dificultar o\nseu deslocamento durante a prática de esportes\nnáuticos.","B":"Sempre supervisionar crianças pequenas.","C":"Investir em equipamentos de proteção ? redes, grades, alarmes.","D":"Ensinar lições de natação a partir de um ano."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-181147","number":"181147","sourceNumber":"181147","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação ao afogamento, assinale a alternativa correta:","options":{"A":"Em áreas com salva-vidas os afogamentos são mais graves pela confiança que as pessoas tem\nde avançar em áreas mais profundas.","B":"Pessoas sem treinamento devem tentar atendimento ao afogado dentro da água.","C":"Compressões torácicas devem ser realizadas apenas em terra.","D":"Imobilizações cervicais devem ser feitas de rotina em pacientes afogados."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157591","number":"157591","sourceNumber":"157591","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Foi atendido, nesta tarde, um paciente com arritmia cardíaca. Sendo diagnosticado\nFibrilação Atrial, foi indicado anticoagulação\noral para profilaxia. Dentre as condutas a seguir,\naponte aquela que é considerada INADEQUADA frente a esse caso.","options":{"A":"Devido à maior propensão de pacientes com FA de apresentarem risco inerente à própria\narritmia de formar coágulos, independentemente de outros fatores.","B":"O sucesso do tratamento anticoagulante está muito mais influenciado pela educação do paciente\ne familiares e cuidadores, do que pela escolha\ndo ACO em si.","C":"Os pacientes que estão em uso de antagonistas da vitamina K necessitam de controles\nlaboratoriais periódicos, devendo ser feito o\nreajuste da dose de acordo com o valor estabelecido\ndo RNI padrão, que é oscilar entre 2,0 e 3,0 a cada aferição, pelo menos diário ambulatoriamente.","D":"Em pacientes em uso dos novos anticoagulantes orais, antes de prescrever um NACO ao\npaciente com FA, a função renal deve ser avaliada."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157745","number":"157745","sourceNumber":"157745","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Entre as complicações da hipotermia terapêutica, pode ser citada a","options":{"A":"hiperglicemia.","B":"hipercalcemia.","C":"taquicardia.","D":"plaquetose."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157704","number":"157704","sourceNumber":"157704","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A epidemiologia possui dificuldade em avaliar a verdadeira incidência de arritmias em\ncrianças. É possível que muitas alterações permaneçam sem identificação, pois vários sintomas\nsão vagos e inespecíficos. Por esse motivo, é importante conhecer a epidemiologia, o que pode\nfacilitar seu reconhecimento em cada faixa etária. Sobre esse caso, assinale a alternativa\nconsiderada INCORRETA.","options":{"A":"Em crianças com corações normais, a incidência e o mecanismo das arritmias variam de acordo\ncom idade, sexo e etnia.","B":"As vias acessórias e os focos atriais ectópicos são mecanismos mais frequentes em crianças\npequenas.","C":"A reentrada Atrioventricular (AV) ganha importância nos adolescentes, especialmente do sexo\nMasculino.","D":"As vias acessórias, os focos atriais ectópicos e a reentrada Atrioventricular (AV) representam os\nmecanismos da maioria das taquiarritmias."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157732","number":"157732","sourceNumber":"157732","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"É difícil avaliar arritmias em crianças, sendo necessários muitos conhecimentos de\nepidemiologia para avaliar corretamente uma situação. Acerca desse assunto, aponte a alternativa\nINCORRETA.","options":{"A":"As arritmias ventriculares são raras em crianças.","B":"As bradiarritmias são comuns em crianças.","C":"As bradiarritmias têm como mecanismos mais comuns a depressão da função de marca-passo\ndo nó sinusal e os bloqueios do sistema de\ncondução.","D":"Causas de bradicardia em crianças incluem estimulação vagal, hipoxemia, acidose e elevação\nda pressão intracraniana."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157743","number":"157743","sourceNumber":"157743","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual dos fármacos listados abaixo apresenta atividade de reversão para arritmias\nsupraventriculares e ventriculares complexas?","options":{"A":"Adenosina.","B":"Digital.","C":"Amiodarona.","D":"Lidocaína."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157714","number":"157714","sourceNumber":"157714","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente deu entrada com palpitações no Hospital e, logo a seguir, evoluiu com perda\nda consciência. Foi levado à sala de emergência e\nrealizado monitorização cardíaca, que\ndemonstrou uma arritmia. Sobre o caso, aponte a alternativa CORRETA.","options":{"A":"Na situação de desfibrilação, utilizada em situações de parada cardiorrespiratória, os choques\nsucessivos devem ser intercalados por 2 minutos de ressuscitação cardiopulmonar.","B":"Na cardioversão elétrica, pode-se realizar o choque sequencial com um nível crescente de\nenergia se o primeiro choque não reverteu a arritmia, não tendo preocupação quanto à\nsincronização dos choques.","C":"Na desfibrilação, deve-se utilizar a máxima energia do aparelho; sendo aplicado 360 J,\nindepende da formatação onda do aparelho.","D":"Caso o ritmo for fibrilação atrial, considera-se o uso de energia inicial de 200 J."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157729","number":"157729","sourceNumber":"157729","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A desfibrilação e a cardioversão elétrica consistem na aplicação de corrente elétrica de\nalta energia para reversão de arritmias cardíacas geradas pelo mecanismo de reentrada,\napresentando diversas indicações nas mais diversas arritmias cardíacas. Frente ao caso, assinale a\nalternativa considerada INADEQUADA.","options":{"A":"Na cardioversão elétrica, esta corrente é sempre sincronizada com os complexos QRS do\neletrocardiograma para que não seja\n\nadministrada durante o período vulnerável da repolarização ventricular.","B":"Nos monofásicos, toda a energia elétrica selecionada é aplicada em um único sentido vetorial.","C":"No formato de onda bifásica, parte da corrente é administrada em um sentido, e a outra parte no\nsentido inverso por inversão de polaridade.","D":"O operador posiciona sobre o tórax, exercendo pressão de aproximadamente 23 kg."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157659","number":"157659","sourceNumber":"157659","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente procura hospital com queixa de intensa palpitação e mal-estar. Seu ECG\ndemonstra arritmia. Qual das alternativas abaixo se refere a antiarrítmico de ação apenas\nsupraventricular?","options":{"A":"Amiodarona.","B":"Lidocaína.","C":"Deslanodio.","D":"Adenosina."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157688","number":"157688","sourceNumber":"157688","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente referindo, inicialmente, mal-estar. Ao dar entrada no Pronto-socorro, perde a\nconsciência, sendo então trazido à sala de emergência. No monitor cardíaco é demonstrado um\npadrão de arritmia cardíaca que permite escalonamento progressivo do tratamento elétrico. Qual\ndas situações abaixo listadas corresponde a essa possibilidade?","options":{"A":"Fibrilação Atrial.","B":"Taquicardia Ventricular sustentada sem pulso.","C":"Fibrilação Ventricular.","D":"Torsade de Pointes sem pulso."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157723","number":"157723","sourceNumber":"157723","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente procurou serviço médico com quadro de tonturas que foram piorando nos\núltimos dias. Como em sua ausculta cardíaca\nfoi constatado ritmo cardíaco irregular, foi feito o ECG\nque demonstrou bradiarritmia. Acerca desse caso, marque a opção CORRETA:","options":{"A":"Bloqueio atrioventricular de segundo grau tipo I eletrocardiograficamente caracteriza-se pelo\naumento progressivo do intervalo PR, acarretando em uma onda P ?bloqueada?, ou isolada,\ngerando uma pausa no traçado do ECG e se relaciona com situações em que há aumento\nimportante do tônus vagal.","B":"Bloqueio atrioventricular de segundo grau tipo II é considerado de menor gravidade que o do tipo\n\nI. Pode localizar-se dentro do feixe de His, sendo o QRS estreito nestes casos. Quando está\nlocalizado abaixo do feixe de His, o QRS é largo.","C":"A presença do BAV de segundo grau tipo II indica doença do sistema His-Purkinje, sendo o\npaciente assintomático. Não indica intervenção.","D":"Quando o BAV é acompanhado por bloqueio de ramo, como bloqueio de ramo direito ou\nesquerdo, a possibilidade de ser uma lesão no sistema His-Purkinje é menor."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157734","number":"157734","sourceNumber":"157734","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A atropina apresentou diminuição de suas indicações nos últimos protocolos de\nreanimação, porém ainda apresenta diversas indicações em outras situações de emergências\ncardiovasculares. Sobre o caso, indique a alternativa considerada ADEQUADA.","options":{"A":"Atropina é a droga de escolha para bradicardia sintomática aguda na ausência de causas\nreversíveis.","B":"Podemos utilizar atropina na presença de síndrome coronariana aguda sem maiores riscos.","C":"A atropina será eficaz em pacientes que se submeteram a transplante cardíaco.","D":"A administração de atropina pode ser utilizada para retardar a aplicação de um marca-passo\ntranscutâneo nos pacientes com baixa perfusão."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157739","number":"157739","sourceNumber":"157739","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente deu entrada no hospital com mal-estar, palpitação e alguma tontura, sua\npressão era de 110 x 60 mmHg e seu ritmo\ncardíaco acelerado e irregular. Seu ECG demonstrou\narritmia sem critério para cardioversão elétrica, sendo indicado tratamento químico. Para essa\nsituação, indique a alternativa considerada INADEQUADA.","options":{"A":"Verapamil e diltiazem mostraram-se efetivos em reversão para ritmo sinusal em taquicardias\nsupraventriculares.","B":"Adenosina é uma droga que diminui a condução pelo NAV e que promove vasodilatação\ncoronária. Possui meia-vida longa de de 5 a 10\nminutos.","C":"Adenosina poderá causar, no paciente, pressão torácica importante com sensação de ?morte\niminente?, porém tais efeitos são transitórios.","D":"Para pacientes com disfunção ventricular sistólica, a amiodarona e a digoxina são as drogas\nmais utilizadas."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134686","number":"134686","sourceNumber":"134686","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A recomendação atual, referente ao protocolo de reanimação cardiorrespiratória, dá\nênfase à qualidade das massagens cardíacas. Dentre as recomendações atuais, não se deve\napoiar por sobre o tórax no retorno do tórax após a compressão torácica. Não sendo essa\nrecomendação decorrente:","options":{"A":"da piora do desfecho da massagem cardíaca.","B":"da piora do retorno venoso.","C":"de dificultar a ventilação.","D":"da piora da pressão de perfusão coronariana."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134684","number":"134684","sourceNumber":"134684","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentro do uso de medicações antiarrítmicas, qual das listadas abaixo possui a\ncapacidade de atuação tanto em arritmias supraventriculares, quanto ventriculares, sendo\nclinicamente indicadas para tal?","options":{"A":"Propafenona.","B":"Lidocaína.","C":"Amiodarona.","D":"Adenosina."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134700","number":"134700","sourceNumber":"134700","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Amiodarona apresenta potencialmente diversos efeitos colaterais, isso tanto em\nnível cardíaco, quanto fora do sistema cardiovascular. Podemos apontar como potenciais\nefeitos colaterais da Amiodarona, a:","options":{"A":"Fibrose pulmonar.","B":"Taquicardia.","C":"Descompensação da glicemia.","D":"Perversão visual tipo xantocromia."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-139785","number":"139785","sourceNumber":"139785","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idosa, 87 anos de idade, apresentou dificuldade respiratória súbita, que se iniciou em\nseu domicílio, sendo, então, trazida de casa\npor familiares ao hospital, já sem sinais vitais. Por isso,\nfoi iniciado manobras de massagem cardíaca, ventilação e adrenalina. Massagem iniciou as\nmanobras, com uma frequência mínima de 120 por minutos, aprofundando o tórax o máximo\npossível, mas permitindo seu retorno completo sem se apoiar sobre ele. Ao avaliar a qualidade das\nmanobras, é sugerido que se modifique a conduta utilizada, segundo as recentes diretrizes de\nemergência, e, aomodificá-la, alega-se que:","options":{"A":"foi perdido o adequado tempo de massagem.","B":"foi perdida a eficácia da massagem cardíaca.","C":"foi muito lenta a massagem cardíaca.","D":"podemos nos apoiar no tórax."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-111837","number":"111837","sourceNumber":"111837","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idoso de 60 anos de idade apresenta dor torácica e por isso procura atendimento\nmédico. Enquanto realizava Eletrocardiograma,\nperdeu os sentidos e você iniciou as manobras de\nreanimação. Porém, um membro de sua equipe se mostrava muito ansioso e não conseguia manter\na ventilação de maneira adequada, mantendo uma frequência de 20 por minuto (após manejo de\nvia aérea definitivo). Você, então, explica que:","options":{"A":"já ocorreu hiperoxia e não precisa mais ventilar.","B":"isso está adequado.","C":"piora a pressão torácica.","D":"não faz diferença porque está entubado."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-350882","number":"350882","sourceNumber":"350882","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Especialistas recomendam que várias ?camadas de proteção? sejam usadas para\nprevenção de afogamentos, pois raramente são causados por um único fator. Das ações de\nprevenção elencadas abaixo qual tem o potencial isoladamente de prevenir mais de 50% dos\nafogamentos em crianças?","options":{"A":"Dispositivos de flutuação pessoal tipo boias de braços.","B":"Cercas de proteção com pelo menos de 1,5 m de altura.","C":"Aulas de natação para crianças menores de 4 anos.","D":"Supervisão, principalmente, aos maiores de 5 anos."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-321298","number":"321298","sourceNumber":"321298","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem, 67 anos, tabagista, hipertenso e dislipidêmico, procurou pronto-atendimento\npor mal-estar, palpitações e dispneia. Refere\nepisódios prévios autolimitados, com duração de 5\nminutos. Paciente acordado, porém letárgico. PA 90x50 mmhg, SpO? 95%. Realizou o seguinte\nECG, na triagem: Assinale a conduta adequada no momento.","options":{"A":"Manobra vagal e diltiazem endovenoso; evitar betabloqueadores pelo risco de DPOC.","B":"Desfibrilação elétrica sem necessidade de anticoagulação devido risco iminente de morte.","C":"Cardioversão elétrica imediata e anticoagulação para prevenção de fenômenos\ntromboembólicos.","D":"Solução cristaloide endovenosa para estabilização hemodinâmica e investigação de\nhipertireoidismo."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-321313","number":"321313","sourceNumber":"321313","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 26 anos, sexo masculino, acompanhado por esquizofrenia é atendido na\nemergência por importante agitação. Foi realizada contenção física e administrado 10mg de\nhaloperidol. Após 30 minutos, paciente está torporoso, pouco responsivo, com pressão arterial de\n60x30mmHg, taquicárdico com pulso filiforme, saturação periférica de O2 de 95%. Ainda não há\nexames laboratoriais disponíveis. Eletrocardiograma realizado foi o seguinte: Qual a melhor\nconduta a ser adotada?","options":{"A":"Infusão de sulfato de magnésio.","B":"Infusão de cloreto de potássio.","C":"Imediata cardioversão elétrica.","D":"Imediata desfibrilação."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-292822","number":"292822","sourceNumber":"292822","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem, 70 anos, procura atendimento médico em Unidade Básica de Saúde devido a\nepisódio de fraqueza em hemicorpo à direita e dificuldade na fala, durante 1 hora, que aconteceram\nhá duas semanas. Paciente procurou, naquela ocasião, emergência médica onde fez tomografia de\ncrânio e doppler de carótidas e vertebrais com laudos normais, exames de sangue que não\nmostraram alterações, e eletrocardiograma que mostrou fibrilação atrial. Paciente optou por não\npermanecer internado, saiu do hospital sem nenhuma prescrição médica e veio à consulta hoje,\ndevido ao \"medo de sentir novamente os sintomas\" e querendo saber qual o melhor tratamento que\ndeve fazer para evitar essa recorrência. Tem antecedente de febre reumática com necessidade de\ntroca valvar (válvula metálica) há 5 anos, mas vinha em uso irregular de suas medicações. No\nmomento está sem utilizar nenhuma. Pulso: 80bpm, PA:120x80mmHg. Exame neurológico sem\nalterações. Qual medicação está indicada para a profilaxia secundária, nesse paciente?","options":{"A":"Ácido acetil salicílico.","B":"Clopidogrel.","C":"Apixabana.","D":"Varfarina."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-292823","number":"292823","sourceNumber":"292823","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher, 56 anos, hipertensa e diabética chegou na emergência referindo palpitação e\ntaquicardia há 3 dias. Refere episódios semelhantes, esporadicamente, que costumam melhorar\nespontaneamente, porém o episódio atual não melhorou, procurando então a emergência. Chegou\ncom pressão arterial = 120 x 80 mmHg, frequência cardíaca = 140 batimentos por minuto e o\neletrocardiograma está apresentado abaixo. Qual é a melhor conduta para essa paciente?","options":{"A":"Cloridrato de amiodarona endovenoso e ablação posterior.","B":"Cloridrato de amiodarona endovenoso e anticoagulação.","C":"Tartarato de metoprolol endovenoso e anticoagulação.","D":"Cardioversão elétrica com 100 J e anticoagulação."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/292823.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-234032","number":"234032","sourceNumber":"234032","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente, 52 anos, sexo masculino, previamente hígido, assintomático, comparece à\nconsulta de rotina no ambulatório. Ao exame físico, chamam atenção sopro em ruflar diastólico\n3+/6+ no foco mitral e ritmo cardíaco irregular com frequência cardíaca em torno de 84 batimentos\npor minuto. Realizado eletrocardiograma (figura abaixo) e ecocardiograma transtorácico que\nevidenciou estenose mitral moderada. Qual conduta deve ser tomada nesse momento?","options":{"A":"Iniciar uso de rivaroxaban sem necessidade de monitoração do INR.","B":"Iniciar warfarin e realizar a monitorização do INR ambulatorialmente.","C":"Internar o paciente para administrar enoxaparina e iniciar uso de warfarin.","D":"Manter conduta expectante, pois o paciente apresenta baixo risco de complicações."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/234032.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-199664","number":"199664","sourceNumber":"199664","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Criança de 5 anos foi encontrada inconsciente na piscina por vigilante de um\ncondomínio e foi removida rapidamente para a unidade de pronto atendimento. Não se sabe o\ntempo de duração do afogamento. Qual é a causa mais comum de morbimortalidade em\nhospitalizados afogados?","options":{"A":"Distúrbio hidroeletrolítico por aspiração de água.","B":"Insuficiência cardíaca com edema agudo de pulmão.","C":"Laringoespasmo seguido de relaxamento da laringe com aspiração de água.","D":"Desenvolvimento de encefalopatia por hipóxia, com ou sem edema cerebral."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-150870","number":"150870","sourceNumber":"150870","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente masculino, 63 anos, é trazido à Unidade Básica de Saúde pela filha que\ninforma que o pai é \"um paciente\ncomplicado\" e que raramente procura o serviço de saúde.\nMorador de zona rural, de difícil acesso e transporte, é hipertenso, dislipidêmico, obeso,\nsedentário,\ntabagista de 2 maços/dia, e apresenta-se com queixa de palpitações associadas à \"falta de ar\" há 4\nmeses. Refere que esses eventos ocorrem 2 a 3 vezes por semana, sendo mais frequentes nas\nsegundas-feiras. Durante um desses episódios, foi levado ao serviço de emergência do município e\nrealizou um ECG (VER IMAGEM). No momento, não tem queixas de palpitações. Faz uso de\nenalapril, hidroclorotiazida e atorvastatina. Ingere cerca 8 a 10 unidades de álcool nos finais de\nsemana. Ao exame físico, encontra-se com PA sentado 126 x 94 mmHg. Peso 80 kg. Altura 165\ncm. Apresenta ausculta cardíaca com ritmo cardíaco regular e frequência de 82 bpm. Sopro\nsistólico 3+/6+ em foco aórtico com irradiação para pescoço. Os pulsos são palpáveis, têm\nascensão lenta e são regulares, congruentes com ausculta. Índice Tornozelo Braquial foi 0,8 e 0,94\npara membro inferior direito e esquerdo, respectivamente. Os exames laboratoriais trazidos não\nevidenciam alterações nas provas de coagulação ou função hepática. Creatinina 1,6 mg/dL. Qual\ndeve ser a prescrição farmacológica com ênfase na prevenção de eventos\nvasculares/tromboembólicos?","options":{"A":"Aspirina 325 mg/dia.","B":"Cilostazol 200 mg/dia.","C":"Aspirina 100 mg/dia e Clopidogrel 75 mg/dia.","D":"Varfarina 5 mg/dia (manter INR entre 2,0 e 3,0)."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/150870.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-102088","number":"102088","sourceNumber":"102088","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina, 72 anos, hipertensa, há cerca de 6h com palpitações intensas, dá\nentrada na emergência, sonolenta e pouco responsiva, após síncope. No exame físico, chamava\natenção uma PA de 80 x 40 mmHg e um pulso rápido, irregular, sem pausas ou falhas, com\nfrequência de 150 bpm, confirmado pela ausculta cardíaca com as mesmas características e sem\noutras alterações. Considerando o diagnóstico mais provável, a conduta mais adequada, após o\nECG de 12 derivações, seria:","options":{"A":"Heparina subcutânea.","B":"Digitálico endovenoso.","C":"Antiarrítmico endovenoso.","D":"Cardioversão transtorácica."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-81319","number":"81319","sourceNumber":"81319","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 82 anos, restrito ao leito, recebe visita domiciliar de seu médico da atenção\nprimária. Paciente é hipertenso, portador de insuficiência cardíaca congestiva, fibrilação atrial\ncrônica e apresenta sequela motora de acidente vascular cerebral. Estava em uso de enalapril: 20\nmg/dia; carvedilol: 50 mg/dia; ácido acetilsalicílico: 100 mg/dia; hidroclorotiazida: 25 mg/dia;\nmetildopa: 500 mg/dia e digoxina: 0,25 mg/dia. Como o médico deverá fazer o ajuste na\nmedicação, considerando o melhor benefício para esse paciente e diminuição do risco de\niatrogenias?","options":{"A":"Reduzir os intervalos entre as doses dos medicamentos para diminuir a probabilidade de efeitos\nadversos.","B":"Solicitar avaliação da função hepática desse paciente semestralmente, devido ao risco de\nintoxicação digitálica.","C":"Reduzir a dose da digoxina para 0,125 mg e substituir diurético tiazídico, ante risco elevado de\nintoxicação digitálica.","D":"Suspender a metildopa, visto que aumenta o número de receptores locais para medicações\nadrenérgicas, podendo causar hipotensão importante na associação dessas drogas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-65699","number":"65699","sourceNumber":"65699","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Médico de família e comunidade realiza visita domiciliar a um homem de 70 anos, que\nvive com a esposa de 72 anos e uma filha. A filha referiu preocupação, pois o pai caiu quatro vezes\nno último mês e na última queda cortou a região dos supercílios. Neste episódio, o paciente caiu da\nprópria altura à noite quando ia ao banheiro. O mesmo é independente para as atividades de vida\ndiária e dependente para as atividades de vida instrumentais. É hipertenso e possui insuficiência\nrenal crônica. Faz uso de furosemida 40 mg às 16h e enalapril 20 mg às 7h. Pratica atividade física\nduas vezes por semana. Em relação às orientações para prevenção de quedas deste senhor,\nassinale a alternativa CORRETA:","options":{"A":"A furosemida deve ser suspensa, pois aumenta o risco de quedas.","B":"O uso de protetores pélvicos não tem indicação, pois não diminuem o risco de fraturas de colo\nfemoral.","C":"A atividade física aumenta o risco de quedas em idosos dependentes para as atividades de vida\ninstrumentais.","D":"O fato do indivíduo não ter sido indagado sobre a perda de consciência mantém a hipótese\ndiagnóstica de síncope.","E":"Deve-se recomendar restrição das atividades para reduzir o risco de quedas, pois o risco de\nfraturas é superior à necessidade e ao desejo de independência."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-51234","number":"51234","sourceNumber":"51234","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher de 60 anos, em primeiro dia pós-operatório de tiroidectomia total, apresenta\nagitação na enfermaria. Ao ser abordada, a\npaciente encontra-se alerta, porém com desorientação\nespacial e alucinações visuais (descrevia animais e monstros circulando seu leito). A cicatriz\ncirúrgica estava limpa. Ao aferir a pressão arterial da paciente, observa-se intenso espasmo carpal.\nNão havia outros achados no exame físico. Qual alteração deve estar presente no\neletrocardiograma desta paciente?","options":{"A":"Alargamento do QRS.","B":"Aumento do intervalo PR.","C":"Elevação do segmento ST.","D":"Prolongamento do intervalo QT."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-51259","number":"51259","sourceNumber":"51259","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 68 anos é admitido em uma emergência trazido por familiares. Apresentava\ndispneia intensa e tontura há 30 minutos, de\ninício súbito. O paciente é hipertenso, em uso de\nlosartana. Exame físico: orientado, dispneico 3+/4+, PA 130 x 90 mmHg, crepitações na metade\ninferior de ambos os pulmões, sem edema de extremidades. Administrado O2 e diurético, sem\nmelhora, evoluindo com dor torácica anginosa. ECG da admissão a seguir (VER IMAGEM). Qual a\nconduta recomendada nesse contexto?","options":{"A":"Cardioversão elétrica.","B":"Amiodarona endovenosa.","C":"Parecer de um especialista.","D":"Massagem dos seios carotídeos."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/51259.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-32514","number":"32514","sourceNumber":"32514","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente, 56 anos, portador de doença pulmonar obstrutiva crônica, internado para\nquimioterapia por câncer de pulmão, apresenta palpitações e coração acelerado. Sua pressão\narterial está 100 x 60 mmHg e o pulso é de 160 bpm. Ele está alerta e cooperativo. Seu\neletrocardiograma prévio mostra síndrome de Wolff-Parkinson-White e agora há fibrilação atrial.\nQual das drogas abaixo é a melhor para tentar reversão do ritmo no paciente em questão?","options":{"A":"Ibutilida.","B":"Amiodarona.","C":"Metoprolol.","D":"Verapamil.","E":"Digoxina."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-32528","number":"32528","sourceNumber":"32528","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Num paciente com intoxicação aguda e grave por propranolol, qual das medicações\nabaixo é a mais adequada ao tratamento?","options":{"A":"Atropina.","B":"Glucagon.","C":"Clonazepam.","D":"Cloreto de cálcio.","E":"Sulfato de Magnésio."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-37640","number":"37640","sourceNumber":"37640","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sr. Francisco das Chagas procurou seu médico de família apresentando ECG\ncompatível com fibrilação atrial crônica. Dr.\nFrancélio decidiu, baseado em evidências científicas,\niniciar o uso de varfarina. Assinale a alternativa incorreta.","options":{"A":"A varfarina é um anticoagulante oral que\nproduz seu efeito inibindo o ciclo de\nconversão da vitamina K;","B":"O objetivo deve ser manter o RNI entre 2, 0 - 3, 0;","C":"Deve-se iniciar o tratamento com doses de 5\nou 10 mg de varfarina, sem que haja\ndiferenças em risco de sangramento ou\n\nefeitos tromboembólicos;","D":"A administração de heparina concomitantemente a varfarina é contraindicada."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-30871","number":"30871","sourceNumber":"30871","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente se apresenta no consultório com queixa de palpitações. No exame físico, você\npercebe um sopro diastólico mais intenso no ápice e uma primeira bulha hiperfonética. Ele traz um\nECG que revela onda P entalhada com duração de 120ms em D2 e com inflexão negativa de 02\nmm em V1. O eixo do QRS está em 120°. Qual das patologias abaixo é o diagnóstico mais\nprovável?","options":{"A":"Hipertireoidismo com taquicardiomiopatia.","B":"Forame oval patente.","C":"Insuficiência aórtica.","D":"Defeito do septo ventricular.","E":"Estenose mitral."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-24299","number":"24299","sourceNumber":"24299","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Hipercalemia de início rápido causa arritmias cardíacas que podem ser fatais. A\nprincipal causa desse distúrbio é:","options":{"A":"Pós-operatório de grandes procedimentos com rabdomiólise","B":"Cetoacidose diabética","C":"Disfunção ou falência renal","D":"Grandes queimados"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-24358","number":"24358","sourceNumber":"24358","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual dos seguintes é a causa mais frequente de morte cardíaca súbita em\nadolescentes e adultos jovens?","options":{"A":"Aterosclerose coronariana","B":"Miocardiopatia dilatada","C":"Miocardite viral","D":"Síndromes arrítmicas hereditárias"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-24323","number":"24323","sourceNumber":"24323","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Karla, 12 anos, com quadro de insuficiência renal aguda, realizou um eletrocardiograma\nque evidenciou uma diminuição do intervalo QT,\nassociada a uma onda T alta e apiculada, sinal de\nrepolarização ventricular precoce. Posteriormente, ocorreu achatamento da onda P, alargamento de\nQRS, até o desaparecimento da onda P. Com essa patologia, o provável distúrbio que gerou as\nalterações eletrocardiográficas foi:","options":{"A":"Hipercalemia","B":"Hipocalemia","C":"Hipomagnesemia","D":"Hiperglicemia"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-25326","number":"25326","sourceNumber":"25326","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Essas manobras são úteis em que situação? (VER IMAGEM)","options":{"A":"Afogamento","B":"Engasgo","C":"Insuficiência Respiratória","D":"Apneia","E":"Intoxicação Exógena"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/25326.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-13407","number":"13407","sourceNumber":"13407","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente com eletrocardiograma mostrando ritmo sinusal com intervalo RR de 15 mm e\ncom QRS positivo em D1 e negativo em aVF. Em aVR o QRS está isodifásico. Marque a resposta\ncorreta:","options":{"A":"Apresenta hemibloqueio anterior esquerdo com eixo elétrico do QRS de +30 graus.","B":"Apresenta eixo elétrico do QRS indeterminado.","C":"Apresenta frequência cardíaca de 100/min com sinais de sobrecarga ventricular direita.","D":"Apresenta eixo elétrico do QRS em --60 graus.","E":"Apresenta ECG compatível com doença do nó sinusal."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-17794","number":"17794","sourceNumber":"17794","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com referência às formas de intervenção do modelo ?sanitarista?, pode-se afirmar que:","options":{"A":"usualmente contemplam a totalidade da situação de saúde","B":"concentram sua atenção no controle de certos agravos","C":"preocupam-se com os determinantes mais gerais da situação sanitária","D":"enfatizam a integralidade da atenção","E":"estimulam a descentralização na organização dos serviços"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-17804","number":"17804","sourceNumber":"17804","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante o exame físico de um paciente cardiológico, qual dos seguintes achados\ndefinitivamente descarta o diagnóstico de Fibrilação Atrial?","options":{"A":"Ritmo cardíaco aparentemente regular","B":"Ausência das ondas a no pulso jugular","C":"Presença de B3","D":"Frequência cardíaca > 200 batimentos por minuto","E":"Presença de B4"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-17868","number":"17868","sourceNumber":"17868","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"No estudo da hipertensão arterial na gravidez, Page (1972) considera a seguinte\nequação para aferir a pressão arterial média:","options":{"A":"PAM = PAS ? PAD / 2","B":"PAM = PAS + PAD / 3","C":"PAM = PAS + 2xPAD / 3","D":"PAM = 2xPAS + PAD / 3","E":"PAM = PAS ? PAD / 3"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-349742","number":"349742","sourceNumber":"349742","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma mulher de 58 anos apresentou-se à sala de emergência com palpitações intensas,\ndor torácica e dispneia. Ela relatou que as\npalpitações começaram repentinamente enquanto\nestava em repouso em casa. Não havia histórico prévio de arritmias. A seguir está o\neletrocardiograma realizado: Sinais vitais: frequência cardíaca estimada em cerca de 150 bpm;\npressão arterial: 80/50 mmHg. Assinale a alternativa que apresenta o diagnóstico e a conduta\nadequada para esse caso.","options":{"A":"Taquicardia supraventricular / Sedação leve e cardioversão química.","B":"Fibrilação atrial / Sedação leve e cardioversão elétrica.","C":"Flutter atrial / Desfibrilação.","D":"Taquicardia sinusal / Conduta expectante.","E":"Fibrilação atrial / Sedação leve e cardioversão química."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/349742.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-349739","number":"349739","sourceNumber":"349739","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Diante de um atendimento a um paciente em parada cardiorrespiratória, o líder precisa\nconduzir a equipe que está realizando a Reanimação Cardiopulmonar (RCP). Qual é a maneira de\ncomunicação mais apropriada entre o líder e a equipe nessa situação?","options":{"A":"Apenas o líder da equipe possui a competência necessária para verbalizar informações,\ndevendo o restante da equipe permanecer em\nsilêncio durante todo o atendimento.","B":"O líder deve transmitir mensagens simultâneas a cada membro da equipe para que sejam\nevitados atos de procrastinação e a situação possa ser revertida o mais rápido possível.","C":"O líder deve transmitir uma mensagem, ordem ou atribuição a um membro da equipe; solicitar\numa resposta clara e contato visual do membro da\nequipe para garantir que tenha entendido a\nmensagem; confirmar que o membro da equipe concluiu a tarefa, antes de lhe atribuir outra tarefa.","D":"O líder deve elevar o tom de voz ao perceber que um dos membros da equipe não compreendeu\na ordem dada, a fim de que tal atitude não se\nrepita.","E":"É necessário que o líder reconheça sua equipe com elogios, como forma de incentivá-la quando\no atendimento é bem sucedido, bem como repreender\nem alto tom de voz ao perceber quaisquer\nfalhas durante o atendimento."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-365613","number":"365613","sourceNumber":"365613","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante a assistência a um paciente em parada cardiorrespiratória no ambiente\nhospitalar, foi realizada a checagem de\nritmo, com o traçado apresentado. O ritmo representado no\ntraçado é.","options":{"A":"chocável e passível de pulso.","B":"não chocável e passível de pulso.","C":"não chocável e não passível de pulso.","D":"chocável e não passível de pulso."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/365613.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-365612","number":"365612","sourceNumber":"365612","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante a assistência a um paciente em parada cardiorrespiratória no ambiente\nhospitalar, foi realizada a checagem de ritmo,\ncom o traçado apresentado. No decorrer do manejo\nda parada cardiorrespiratória nesse ritmo, são indicados o uso de","options":{"A":"adrenalina e noradrenalina.","B":"adrenalina e amiodarona.","C":"atropina.","D":"adrenalina."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/365612.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-365635","number":"365635","sourceNumber":"365635","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma paciente de 43 anos de idade, com história de cardiopatia estrutural, procurou o\npronto-socorro queixando-se de desconforto torácico inespecífico e três pré-síncopes nas últimas\n12 horas. Na admissão, foi realizado eletrocardiograma (ECG) com o traçado apresentado.\n\nConsiderando esse caso e com base nesse traçado, é correto afirmar que se trata de","options":{"A":"ritmo sinusal normal.","B":"bloqueio atrioventricular de primeiro grau.","C":"bloqueio atrioventricular de segundo grau.","D":"bloqueio atrioventricular total."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/365635.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-322152","number":"322152","sourceNumber":"322152","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 63 anos, recebendo medicação para dor epigástrica na sala de\nobservação do pronto atendimento, apresenta\num colapso ao levantar-se da poltrona. Qual é a\nconduta imediata mais adequada nesse caso?","options":{"A":"Realizar um eletrocardiograma de 12 derivações.","B":"Checar a responsividade.","C":"Aplicar 1 mg de epinefrina EV.","D":"Iniciar compressões torácicas.","E":"Solicitar avaliação da cardiologia."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-337519","number":"337519","sourceNumber":"337519","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 80 anos foi encontrado em rua pública, e testemunhas disseram que ele\nestava caminhando quando subitamente caiu no chão, perdendo a consciência. No hospital, foi\nrealizado eletrocardiograma mostrado a seguir. Ao exame físico, sua pressão arterial era de\n80x40mmHg, havia estertores pulmonares em todos os segmentos pulmonares com turgência\njugular; sua glicemia estava normal. Durante seu atendimento, o paciente demonstrou ritmo\ncardíaco no monitor. Com base nos conhecimentos clínicos e nos eletrocardiogramas\napresentados, julgue o item a seguir: No eletrocardiograma número 2, o paciente apresenta\ntaquicardia ventricular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/337519.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-322164","number":"322164","sourceNumber":"322164","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 46 anos procura atendimento médico de urgência com queixa de\npalpitações e dor torácica do tipo aperto,\nde início há aproximadamente 1 hora. Seus sinais vitais\nsão aferidos: ? PA: 70x40mmHg (pressão arterial); ? FC: 190bpm (Frequência cardíaca); ? SatO2:\n86% (saturação de oxigênio). E o seu eletrocardiograma (ECG) é o seguinte: Nesse caso, conforme\nas informações apresentadas, é correto afirmar que","options":{"A":"se trata de uma taquicardia supraventricular, e o uso da manobra vagal modificada está\nindicado.","B":"a avaliação de um especialista deve ser prioritária.","C":"o uso de atropina 1mg endovenosa (EV) está indicado.","D":"a cardioversão elétrica sincronizada está indicada.","E":"um estudo eletrofisiológico deve ser realizado antes de qualquer intervenção terapêutica."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/322164.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-305287","number":"305287","sourceNumber":"305287","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual das seguintes taquiarritmias apresenta complexo QRS estreito e regular?","options":{"A":"Fibrilação atrial.","B":"Torsades de pointes.","C":"Taquicardia atrial.","D":"Taquicardia de movimento circular antidrômica.","E":"Flutter atrial com bloqueio AV variado."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-298858","number":"298858","sourceNumber":"298858","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Provavelmente,\nno período do eletro de repouso, o intervalo PR seja normal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/298858.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-298859","number":"298859","sourceNumber":"298859","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Tratamento\ncom sotalol é o padrão-ouro, no caso desse paciente, para tratamento em longo prazo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/298859.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-305291","number":"305291","sourceNumber":"305291","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 57 anos procura atendimento médico com queixa de palpitações e dor\ntorácica tipo aperto, de início há 30 minutos. Apresenta hipotensão (PA = 60 x 40 mmHg). Após\navaliar o ritmo mostrado a seguir, qual é a conduta mais adequada?","options":{"A":"Manobra vagal.","B":"Adenosina 6 mg EV em bólus.","C":"Amiodarona 150 mg EV em 30 minutos.","D":"Deslanosídeo 0,8 mg EV em blus.","E":"Cardioversão elétrica sincronizada."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/305291.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-298860","number":"298860","sourceNumber":"298860","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O risco de\nmorte súbita para esse paciente é elevado em relação à população normal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/298860.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-298861","number":"298861","sourceNumber":"298861","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente de 45 anos de idade vem apresentando sintomas de palpitação, mal-estar\ne sudorese profusa no decorrer da hemodiálise.\nEm cada sessão, são ultrafiltrados 4 litros em duas\nhoras e meia. Na última diálise, o paciente ficou com hipotensão = 85 mmHg x 40 mmHg, SatO2 =\n94% em ar ambiente e frequência cardíaca conforme o eletrocardiograma a seguir. Com base\nnesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Cardioversão é\no melhor tratamento para manejo agudo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/298861.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-305305","number":"305305","sourceNumber":"305305","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de aproximadamente 50 anos apresenta um colapso na recepção do\npronto-socorro e é levado diretamente para\na sala de emergência. Após verificar a responsividade,\nqual é a conduta mais adequada?","options":{"A":"Iniciar compressões torácicas.","B":"Aplicar duas ventilações de resgate.","C":"Acesso venoso calibroso e expansão volêmica.","D":"Eletrocardiograma de 12 derivações.","E":"Checar o pulso carotídeo e a respiração."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-274359","number":"274359","sourceNumber":"274359","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente masculino, 60 anos, foi admitido na urgência com quadro de taquiarritmia de\ninício recente, sintomática. Foi realizado o eletrocardiograma na admissão, que é apresentado em\nseguida. Analisando o eletrocardiograma e as alternativas a seguir, qual é o ritmo predominante\nmais provável que se apresenta?","options":{"A":"Taquicardia supraventricular de reentrada.","B":"Taquicardia ventricular.","C":"Flutter atrial.","D":"Fibrilação atrial.","E":"Ritmo juncional."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/274359.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-255692","number":"255692","sourceNumber":"255692","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 35 anos de idade chega ao pronto-socorro com dor torácica em aperto,\nirradiada para membro superior esquerdo há duas horas. Foi realizado um eletrocardiograma de\nrepouso. Acerca desse caso clínico e tendo em vista os conhecimentos médicos correlatos,\nconsiderando o traçado eletrocardiográfico apresentado, julgue o item a seguir. No traçado\neletrocardiográfico, o paciente apresenta bloqueio atrioventricular de segundo grau.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/255692.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-255740","number":"255740","sourceNumber":"255740","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma gestante de 25 semanas vem apresentando taquicardia supraventricular\nparoxística durante a gestação. O cardiologista\ndela avaliou, junto ao obstetra, situações\nterapêuticas para minimizar a taxa de recorrência. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. Segundo as diretrizes de taquicardia\nsupraventricular da ESC 2019, não se deve utilizar sotalol na recorrência das crises de taquicardia\nsupraventricular.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-255741","number":"255741","sourceNumber":"255741","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma gestante de 25 semanas vem apresentando taquicardia supraventricular\nparoxística durante a gestação. O cardiologista\ndela avaliou, junto ao obstetra, situações\nterapêuticas para minimizar a taxa de recorrência. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. De acordo com as diretrizes da ESC\n2019, ablação com cateter, com mapeamento e sem uso de radiação pode ser uma opção\nterapêutica para pacientes gestantes.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-255742","number":"255742","sourceNumber":"255742","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma gestante de 25 semanas vem apresentando taquicardia supraventricular\nparoxística durante a gestação. O cardiologista\ndela avaliou, junto ao obstetra, situações\nterapêuticas para minimizar a taxa de recorrência. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. É incapaz de causar síncope e queda ao\nsolo, não causando risco de quedas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-211982","number":"211982","sourceNumber":"211982","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente comparece ao consultório do cardiologista para exames de rotina.\nSegundo o médico, nos exames não se\nobservou qualquer alteração, mas o paciente foi ao\nambulatório de clínica médica, pois desejava saber o significado do número 1 no exame de imagem\necocardiográfica que foi realizado. Considerando que a imagem apresentada é obtida na incidência\nlongitudinal paraesternal durante a sístole, nesse caso clínico, o médico informou corretamente ao\npaciente que, na imagem, o número 1 corresponde ao (à):","options":{"A":"Ventrículo direito.","B":"Ventrículo esquerdo.","C":"Aorta.","D":"Átrio esquerdo.","E":"Átrio direito."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/211982.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-211957","number":"211957","sourceNumber":"211957","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Determinado paciente, atleta de alto rendimento não profissional, compareceu ao\nconsultório médico para fazer avaliação clínica, pois está sentindo tonteira e mal-estar e relata\nfadiga durante exercícios ergométricos. Realizou teste ergométrico com o seguinte resultado:\ntaquicardia ventricular polimórfica catecolaminérgica, conforme a figura apresentada. Nesse caso\nclínico, ao ser questionado acerca de quando o paciente poderá voltar a fazer atividade física em\ncompetição, o médico deve responder que o paciente:","options":{"A":"Poderá praticar todos os exercícios físicos competitivos.","B":"Poderá realizar esportes competitivos de baixa intensidade.","C":"Poderá fazer todos os esportes, com restrição somente aos praticados em ambientes perigosos.","D":"Não poderá praticar qualquer esporte competitivo.","E":"Deve fazer apenas esportes competitivos de baixa intensidade."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/211957.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-212003","number":"212003","sourceNumber":"212003","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante reanimação de um paciente previamente hígido, internado para avaliação\npressórica, o quadro evoluiu com parada cardiorrespiratória e ressuscitação por 17 minutos,\n\nbem-sucedida. O paciente evolui com estabilidade pressórica, pressão arterial invasiva (PAI) = 84\nmmHg, FC = 102 bpm e SatO? = 96% sob ventilação mecânica em via aérea definitiva. Intensivista\ndecidiu então fazer hipotermia, com temperatura entre 32°C e 34°C, pois o ritmo inicial era\nfibrilação ventricular. No que tange a esse caso clínico, assinale a alternativa que equivale a\npossíveis complicações dessa terapêutica.","options":{"A":"Nova parada cardíaca pelo resfriamento do sistema nervoso central.","B":"Crises hipertensivas e convulsivas.","C":"Coagulopatia e risco do aumento de infecção.","D":"Quadros álgicos intensos com fratura de ossos instáveis.","E":"Melhora clínica rápida com menos de oito horas de evolução e extubação acidental."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-196614","number":"196614","sourceNumber":"196614","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz Eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da Diretriz de\nInterpretação de Eletrocardiograma de Repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 bpm; intervalo PR = 195ms; intervalo QRS = 130ms; intervalo QT\n\n= 440ms. Verifica-se um bloqueio atrioventricular de primeiro grau.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/196614.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-196623","number":"196623","sourceNumber":"196623","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Certa paciente de 62 anos de idade, com histórico de hipertensão arterial sistêmica e\ndiabetes mellitus tipo 2, assintomática no momento, traz Eletrocardiograma (ECG) de 12\nderivações, solicitado por médico em consulta anterior. Com base nesse caso clínico, e\nconsiderando-se a reprodução do ECG apresentado, mediante a utilização da diretriz de\ninterpretação de eletrocardiograma de repouso, da Sociedade Brasileira de Cardiologia, julgue o\nitem a seguir. Considere: FC = 51 spm; intervalo PR = 195ms; intervalo QRS = 130ms; intervalo QT\n\n= 440ms. As alterações de onda T em V5?V6 podem ser justificadas pela presença de bloqueio de\nramo esquerdo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/196623.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-214458","number":"214458","sourceNumber":"214458","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma paciente de 8anos de idade, sem histórico de sintomas cardiovasculares e com\nexame físico normal, leva a consulta o\neletrocardiograma (ECG) de repouso apresentado (1 cm = 1\nmv), como parte da avaliação anual de respectivo clube de natação, onde treina competitivamente.\nRealiza treinos cinco vezes por semana, com uma hora de duração. Ao exame físico, verificam-se\nFC de 70 bpm, FR d 16 irpm e saturação de oxigênio de 99%. Após uma análise do ECG da\npaciente desse caso clínico, considerando as Diretrizes Brasileiras de Interpretação de ECG e as\nDiretizes de Cardiologia do Esporte da SBC/SBME, julgue o item a seguir: As alterações\nencontradas em V1/V2 devem-se ao alto volume de treinamento aeróbico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/214458.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-177607","number":"177607","sourceNumber":"177607","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"M.C.L., sexo feminino, de 76 anos de idade, é paciente com diagnóstico de insuficiência\ncardíaca com fração de ejeção reduzida\n(40%), atualmente com classe funcional NYHA II. Como\ncomorbidades, apresenta HAS, DM e fibrilação atrial fixa. Considerando o quadro dessa paciente e\nsua patologia, julgue o item a seguir. Há indicação de terapia anticoagulante para essa paciente?","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-134985","number":"134985","sourceNumber":"134985","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A respeito da parada cardiorrespiratória (PCR) em crianças, julgue o item a seguir.\nQuando administrada na PCR, a ação farmacológica da adrenalina promove a vasoconstrição\n(efeito alfa), o que eleva a pressão de perfusão durante a compressão torácica e aumenta a\nliberação de oxigênio para o coração.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-105533","number":"105533","sourceNumber":"105533","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O achado ocasional ao eletrocardiograma de amplitude e forma na onda \"p\", em\npaciente jovem, chama atenção para eventuais problemas:","options":{"A":"Ventriculares.","B":"No ventrículo direito.","C":"Na despolarização ventricular.","D":"Atriais.","E":"De bloqueio de ramos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-79655","number":"79655","sourceNumber":"79655","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem, 76 anos, apresenta, após exames conclusivos, disfunção do nó sinusal com\nmanifestação eletrocardiográfica de uma bradicardia sinusal inapropriada e persistente. Episódios\nde bloqueio sinoatrial, parada sinusal, fibrilação atrial de frequência baixa. Entre as patologias\nabaixo, assinale a alternativa que apresenta a que mais condiz com o caso descrito.","options":{"A":"Doença de Chagas.","B":"Cardiomiopatia difusa.","C":"Cardiomiopatia hipotrófica.","D":"Angina pectoris.","E":"Angina instável."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-82099","number":"82099","sourceNumber":"82099","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Acerca de traumas, urgências ortopédicas e doenças infecciosas, julgue o próximo\nitem: A fibrilação ventricular é a causa\nmais frequente de morte súbita. Nos casos em que quase se\niniciam a desfibrilação por choque elétrico e o suporte básico local de oxigenação tecidual nos três\nprimeiros minutos após a parada cardíaca, a taxa de vida é aumentada.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-88690","number":"88690","sourceNumber":"88690","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com relação à parada cardiorrespiratória e ao trauma, julgue o item que segue.\nFibrilação ventricular, taquicardia ventricular sem\npulso, assistolia e atividade elétrica sem pulso\nconstituem modalidades de parada cardíaca.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-64272","number":"64272","sourceNumber":"64272","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"No Brasil, estima-se que ocorreram cerca de 300.000 mortes por ano devido à causas\ncardiovasculares. O êxito no atendimento de situações de parada cardiorrespiratória depende do\nconhecimento sólido dos procedimentos recomendados, internacionalmente, pelas diretrizes da\nAssociação Americana do Coração (AHA). Com base nas recomendações da AHA para o suporte\nbásico de vida, julgue o item que se segue. Nesse sentido, considere que a sigla RCP, sempre que\nutilizada, refere-se à Reanimação Cardiopulmonar. Deve-se manter as compressões torácicas\nrealizadas durante as manobras de RCP em uma frequência de, pelo menos, cem compressões por\nminuto, produzindo, a cada compressão, uma depressão torácica de, pelo menos, cinco\ncentímetros. Esse procedimento tem por fim a geração de fluxo sanguíneo pelo aumento tanto na\npressão intratorácica quanto pela compressão direta do coração, o que promove fluxo sanguíneo e\noferta de oxigênio para o miocárdio e o cérebro.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-19249","number":"19249","sourceNumber":"19249","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 65 anos de idade, tabagista, diabético, dislipidêmico, chega ao\n\npronto-socorro com história de dor torácica progressiva em hemitórax esquerdo há duas horas,\nacompanhada de surdorese fria e náuseas. Durante o exame clínico, na sala de emergência, o\npaciente perde a consciência e não responde ao chamado. Identifica-se a ausência de pulso\ncarotídeo e o ritmo visualizado no monitor cardíaco, através das pás do desfibrilador, revela\nassistolia. A sequência correta de condutas a serem adotadas é:","options":{"A":"confirmar o ritmo de assistolia em outra derivação; realizar a intubação orotraqueal, solicitar a\nmonitoração cardíaca com eletrodos e um acesso venoso periférico. A adrenalina não poderá ser\nadministrada enquanto o acesso venoso não for estabelecido.","B":"confirmar o ritmo de assistolia em outra derivação, realizar a intubação orotraqueal, solicitar a\nmonitoração cardíaca com eletrodos e um acesso venoso periférico. Assim que possível, realizar a\ndesfibrilação com 200J, pois a assistolia pode mascarar uma fibrilação ventricular em até 10% dos\ncasos.","C":"confirmar a assistolia em outra derivação; após a confirmação, realizar massagem cardíaca\nexterna e ventilações sincronizadas com a\nmassagem cardíaca, enquanto se prepara o material\npara intubação, a monitoração cardíaca com eletrodos e o acesso venoso.","D":"caso seja encontrado o ritmo de fibrilação ventricular fina na confirmação do ritmo em outra\nderivação, não se deve realizar a\ndesfibrilação até que a mesma seja administrada a adrenalina\npara que haja aumento da amplitude de fibrilação, pois a fibrilação ventricular fina pode evoluir\npara\na assistolia após o choque.","E":"o marcapasso transcutâneo deve ser colocado imediatamente, pois essa atitude muda o\nprognóstico da parada cardíaca em assistolia."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-19337","number":"19337","sourceNumber":"19337","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Lactente de 16 meses de idade é levado ao pronto-socorro pálido e sudoreico. A mãe\nrefere que sente o coração do filho muito acelerado. Ao exame a criança está hipoativa com\nfrequência cardíaca (FC) = 220 bpm e pressão arterial = 78 x 65 mmHg. Realizado\neletrocardiograma de repouso que confirma a FC e mostra um traçado com complexos estreitos e\nregulares (reproduzido a seguir). A conduta mostra neste momento é a administração de:(VER\nIMAGEM)","options":{"A":"Expansão com soro fiosiológico 20mL/Kg","B":"Beta-bloqueador via retal","C":"Digoxina por via intravenosa","D":"Furosemide intravenosa","E":"Adenosina intravenosa"},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/19337.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-343407","number":"343407","sourceNumber":"343407","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O nome da arritmia que é um ritmo que o impulso elétrico se origina logo acima do\nventrículo, com reentrada por uma via de\ncondução acessória, e o ECG não mostra a onda P, mas\nela pode estar presente e com morfologia anormal, nem sempre sendo possível determinar o\nintervalo PR e o intervalo RR é constante e o QRS estreito, com frequência cardíaca superior a 220\nbpm em lactentes e a 180 bpm em crianças maiores é:","options":{"A":"Bloqueio Atrioventricular.","B":"Bradicardia sinusal.","C":"Flutter Ventricular.","D":"Taquicardia Supraventricular."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-273313","number":"273313","sourceNumber":"273313","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Criança de 2 anos de idade, inicia quadro súbito de taquipnéia, palidez e sudorese.\nApresenta-se afebril, com FR = 40 mrpm, FC =\n230 bpm, pulsos periféricos finos e rápidos,\nperfusão periférica preservada. A criança está consciente, contactando normalmente com os pais.\nFeito ECG: O diagnóstico e conduta mais adequados são:","options":{"A":"Taquicardia sinusal; expansão com solução cristalóide.","B":"Taquicardia ventricular; cardioversão sincronizada.","C":"Taquicardia supraventricular; adenosina IV.","D":"Taquicardia juncional; amiodarona IV."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/273313.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-230558","number":"230558","sourceNumber":"230558","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A varfarina é altamente eficaz na prevenção de fenômenos tromboembólicos na FA,\ncom redução de 64% do risco nos pacientes\nadequadamente tratados. NÃO podemos aceitar que:","options":{"A":"Menos metade dos pacientes não são adequadamente tratados, por motivos que variam desde a\ndificuldade de controle frequente de RNI até alto risco de sangramento.","B":"Pacientes em uso de varfarina nem sempre se encontram na faixa terapêutica adequada (em\ngeral RNI entre 5 e 6).","C":"Ocorre interação medicamentosa, principalmente antibióticos e anti-inflamatórios.","D":"Ocorre interação com alimentos, uso irregular da medicação, intercorrências clínicas agudas,\nentre outros."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-230579","number":"230579","sourceNumber":"230579","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quais os parâmetros do ECG devem se conhecidos ao se avaliar uma criança com\nalteração do ritmo?","options":{"A":"Conhecimento da FC normal de acordo coma idade, o débito cardíaco e o ritmo de base.","B":"Conhecimento da FC normal de acordo com a idade, o débito cardíaco e a duração do complexo\nQRS.","C":"Conhecimento do débito cardíaco, ritmo de base e duração do complexo QRS.","D":"Conhecimento da FC normal de acordo com a idade, o ritmo de base e a duração do complexo\nQRS."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-203130","number":"203130","sourceNumber":"203130","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma paciente de 45 anos de idade sente tontura, pressão no peito e fadiga há três\nhoras. Durante o exame, verifica-se que ela\napresenta níveis pressóricos de 80 mmHg x 50 mmHg\ne FC = 140 bpm, associada a má perfusão periférica. Ao ECG, nota-se que ela tem fibrilação atrial,\nsendo que um ECG basal prévio mostrou ondas delta. A respeito desse caso clínico, assinale\nalternativa correta.","options":{"A":"Essa paciente não possui risco de taquicardia ventricular, pois a respectiva fibrilação atrial\npossui complexo QRS estreito, assim o risco maior seria evolução para taquicardia\nsupraventricular.","B":"A onda delta indica a presença de extrassístoles ventriculares (provável disfunção do nó\nsinusal); assim, o diagnóstico para esse caso é\nfibrilação atrial com complexo de QRS alargado.","C":"A terapia de escolha para essa paciente seria administração de betabloqueadores, com objetivo\nde redução da frequência cardíaca.","D":"A terapia com verapamil é uma opção aceitável para ser realizada nessa paciente em caráter de\nemergência, em razão da rápida absorção e objetivando a redução da frequência cardíaca e do\ninotropismo cardíaco.","E":"O diagnóstico clínico dessa paciente é fibrilação atrial em uma paciente portadora de síndrome\nde Wolff-Parkinson-White, indicado pelas ondas delta no\nECG anterior, que mostram uma via\nacessória ao nó atrioventricular para a comunicação elétrica."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-206170","number":"206170","sourceNumber":"206170","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Responda qual a alternativa CORRETA sobre o ritmo apresentado:","options":{"A":"Trata-se de taquicardia supraventricular.","B":"Deve-se iniciar massagem cardíaca e oferecer adenosina rapidamente.","C":"Trata-se do tipo mais comum de PCR em crianças, é a assistolia.","D":"Devemos realizar desfibrilação."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/206170.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-212110","number":"212110","sourceNumber":"212110","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Caso clínico - paciente sem doenças prévias; Idade: 19 anos: sexo: feminino; Sinais e\nsintomas: tremores nas extremidades, nervosismo e palpitações taquicárdicas (FC = 15 bpm, PA\n135 mmHg x 65 mmHg, pulsos radiais palpáveis e arrítmicos); Avaliação cardiovascular evidenciou\nictus cordis in situ, ritmo cardíaco irregular em 2 tempos, taquicárdico, bulhas normofonéticas, sem\nsopros ou ruídos adventícios. Na palpação, percebeu-se glândula tireoide indolor, levemente\naumentada e não nodular. Resultado de dosagem séricas: TSH (tirotrofina) = 0,05 mU/L (valores de\nreferência = 0,4 - 4,2 mU/L); T4 livre (tiroxina livre) = 4,0 nanogramas/dL (valores de referência =\n0,8 - 2,7 nanograma/dL); anticorpos antirreceptor de TSH (ou Trab) = 2 U/L (valor de referência <\n10 U/L); anticorpos antitireoglobulinas = positivo 1/6.400 (valores de referência não reagente <\n1/100); determinação de anticorpos antiperoxidase tireoidiana (anti-TPO) = 70 U/mL (valores de\nreferência < 35 U/mL). Ecodopplercardiograma = normal. Tira de ritmo eletrocardiográfico (ECG)\nmostrada na figura a seguir (derivação D2, velocidade do papel: 25 mm/s, calibração: 1 cm = 1\nmV). A respeito das informações do caso clínico descrito anteriormente, julgue o item subsequente.\nA arritmia cardíaca mostrada na tira de ECG é a fibrilação atrial.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/212110.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175085","number":"175085","sourceNumber":"175085","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentro do estudo da genética, relacionada com o eletrocardiograma ocorre descrição\nde entidades clínicas potencialmente fatais, que\napresentam padrão eletrocardiográfico\ncaracterístico. Dentro desse grupo de doenças, destacam-se aquelas com coração estruturalmente\nnormal, como as canalopatias. Não sendo ADEQUADA a seguinte alternativa a seu respeito:","options":{"A":"As canalopatias cardíacas são o resultado de mutações genéticas ou de um mau funcionamento\nadquirido dos canais iônicos.","B":"Os canais iônicos são responsáveis por desencadear alterações na despolarização.","C":"Os canais iônicos são responsáveis por desencadear alterações na repolarização das fases do\npotencial de ação celular.","D":"Achados eletrocardiográficos específicos, com associação de síncopes espontâneas, mas não\nas desencadeadas pelo exercício."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175106","number":"175106","sourceNumber":"175106","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Síndrome do QT longo pode causar inúmeros sintomas. Sobre ela, podemos afirmar\nque:","options":{"A":"A claritromicina pode aumentar o intervalo QT.","B":"Calcula-se o QT corrigido apenas se a frequência cardíaca for maior que 80 bpm.","C":"Calcula-se o QT corrigido apenas se a frequência cardíaca for menor que 90 bpm.","D":"Apenas calcula-se QT corrigido para crianças maiores de 10 anos."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175110","number":"175110","sourceNumber":"175110","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre a morfologia da Onda P, é correto afirmar:","options":{"A":"A onda P sinusal é positiva em AVR, D1 e D2.","B":"No ritmo atrial ectópico a onda P é negativa em D2, sendo comum em adolescentes.","C":"Quando há situs atrial inversus, a onda P é negativa em D1 e em AVR.","D":"A amplitude normal da onda P é de 4mm."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175111","number":"175111","sourceNumber":"175111","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Nas arritmias é CORRETO afirmar que:","options":{"A":"Quando há QT longo, há proteção contra a morte súbita.","B":"No torsades de pointes devemos oferecer cálcio ao paciente para tratá-lo e seu ECG apresenta\nQT curto.","C":"No torsades de pointes há espaço QT curto e tratamos com magnésio.","D":"No Wolff-Parkinson-White há espaço PR curto."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175163","number":"175163","sourceNumber":"175163","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A classificação mais utilizada na prática clínica refere-se à forma de apresentação da\nFA. Definem-se assim diversas classificações, sendo que somente uma das abaixo se mostra\ncompletamente correta, assinale-a:","options":{"A":"?Fibrilação atrial paroxística? aquela que é revertida espontaneamente ou com intervenção\nmédica em até 24 horas de seu início.","B":"Episódios com duração superior a 7 dias têm o nome de ?Fibrilação atrial persistente?.","C":"Alguns estudos utilizam a terminologia de ?Fibrilação atrial persistente de longa duração? para\ndesignar os casos com duração superior a mês.","D":"Finalmente, o termo ?Fibrilação atrial permanente? é utilizado nos casos em que as tentativas\nde reversão ao ritmo sinusal não foram feitas."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175174","number":"175174","sourceNumber":"175174","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentro do estudo das complicações relacionadas à trombogênese e embolia na\nFibrilação Atrial, podemos considerar que as três condições estabelecidas por Virshow estão\npresentes em paciente com FA. Não sendo, contudo, completamente adequada a afirmativa:","options":{"A":"Lesões do endocárdio atrial apresentavam microtrombos, e estes eram os precursores de\ntrombos maiores.","B":"O atrito do sangue com o endocárdio, lesões miocitárias causadas por agressões teciduais\nsecundárias a citocinas inflamatórias (fator de\nnecrose tumoral, interleucina 6, proteína C-reativa e\noutras) prejudicam ainda mais os miócitos atriais e expõem tecido colágeno na superfície, o que\naumenta a aderência de plaquetas e a deposição de fibrina, gerando o trombo.","C":"Dessa forma, a FA cria um estado pró-trombótico e hipercoagulável próprio.","D":"O aumento da agregação plaquetária, menos intensa no Átrio Esquerdo (AE), e a redução dos\nníveis plasmáticos do fator de Von Wilebrand, os fragmentos de protrombina e do fibrinogênio\nplasmático, dentre outros, confirmam essa maior trombogenicidade sanguínea, independentemente\nde qualquer outro fator."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-168486","number":"168486","sourceNumber":"168486","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma lactante com 15 meses de idade é levada pela mãe ao Pronto-Socorro. A mãe\nrelata que o coração do bebê está muito\nacelerado. A mãe nega outras queixas e informa que\nrealiza acompanhamento na Unidade Básica de Saúde, não tendo ocorrido até então,\nintercorrências. Ao exame físico, a lactante apresenta-se em bom estado geral, corada, hidratada,\nafebril, consciente, com boa perfusão periférica, saturação de oxigênio de 98% em ar ambiente,\nBNF 2T sem sopro audivél, frequência cardíaca = 230 bpm, ausência de edema e pulsos de boa\namplitude. O eletrocardiograma apresenta onda P não visível; intervalo RR fixo QRS estreito\n(menor que 0,09 segundos). Diante desse quadro, além da manobra vagal, a conduta inicial\nadequada é","options":{"A":"administrar lidocaina","B":"administrar adenosina","C":"administrar amiodaroma","D":"realizar cardioversão elétrica sincronizada"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-159580","number":"159580","sourceNumber":"159580","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O item a seguir apresenta uma situação hipotética seguida de uma assertiva a ser\njulgada a propósito da fisiopatologia, do diagnóstico precoce e do tratamento de doenças em\ncrianças e adolescentes. Uma gestante com trinta e quatro semanas gestacionais foi a uma\nconsulta de rotina, e o médico obstetra observou que a frequência cardíaca fetal era de 70 bpm.\nNeste caso, um diagnóstico que pode ser excluído na gestante é lúpus eritematoso sistêmico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-168519","number":"168519","sourceNumber":"168519","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem com 60 anos de idade foi internado em um hospital municipal com quadro\nde confusão mental. O paciente reside em outro\nmunicípio, há 300 km do hospital. Na admissão, o\npaciente se disse assintomático, relatou que não costuma procurar atendimento médico e que\npreferia morar sozinho no sítio onde nasceu e cuida de uma pequena lavoura. Os familiares que o\nacompanhavam confirmaram que ele não apresenta comorbidades diagnosticadas, mas relataram\nque, há 5 dias, o paciente apresentou um episódio de confusão mental, tendo sido levado para\ninternação hospitalar. Acrescentaram que, na ocasião, foi diagnosticada e tratada uma infecção do\ntrato urinário e que, durante o exame físico, detectou-se uma arritmia cardíaca, confirmada por\neletrocardiograma, cujo resultado é reproduzido a seguir. (Conforme imagem no caderno de\nquestões) O resultado do eletrocardiograma realizado na internação atual apresenta o mesmo\npadrão. Agora, consciente e orientado, sem queixas, o paciente manifesta desejo de ter alta e de\nretornar ao seu sítio, afirmando que não pretende realizar outras consultas médicas. Nesse\ncontexto, qual é a conduta médica indicada?","options":{"A":"Dar alta hospitalar ao paciente após introdução de digoxina.","B":"Dar alta hospitalar ao paciente após a introdução e o ajuste da dose da varfarina.","C":"Dar alta hospitalar ao paciente após introdução e ajuste de dose do betabloqueador.","D":"Orientar os familiares para que busquem, por meios jurídicos, a guarda do idoso e o mantenham\nna sede do município para iniciar tratamento\ncom varfarina."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/168519.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-111304","number":"111304","sourceNumber":"111304","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O bloqueio cardíaco é uma condição na qual a propagação da despolarização pelo\nnodo AV ou pelo feixe de Hiss é anormalmente\nlenta. Os pacientes têm consciência disso relatando\nque ?meu coração perdeu um batimento?. A principal alteração observada no registro\neletrocardiográfico, independentemente da derivação escolhida, é o:","options":{"A":"Desaparecimento da onda T.","B":"Desaparecimento da onda P.","C":"Aparecimento de duas ondas P sucessivas.","D":"Desaparecimento do complexo QRS, sem afetar a onda T.","E":"Aparecimento de duas ondas T sucessivas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-97794","number":"97794","sourceNumber":"97794","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem com 53 anos de idade, tabagista e com história prévia de cardiopatia, tem\nparada cardiorrespiratória na unidade básica de saúde, enquanto aguardava atendimento. A\nsequência CORRETA de medidas a serem adotadas nessa situação é:","options":{"A":"Verificar o nível de consciência; acionar o serviço de emergência; verificar o pulso; iniciar\ncompressões torácicas.","B":"Iniciar compressões torácicas; verificar o pulso; acionar o serviço de emergência; verificar o\nnível\nde consciência.","C":"Acionar o serviço de emergência; verificar o pulso; verificar o nível de consciência; iniciar\ncompressões torácicas.","D":"Acionar o serviço de emergência; avaliar o nível de consciência; iniciar compressões torácicas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-64449","number":"64449","sourceNumber":"64449","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminino, 75 anos, dá entrada no setor de emergência com quadro de tontura,\nfalta de ar, sonolenta e hipotensa. O ECG\nevidencia fibrilação atrial com frequência cardíaca de 130\nBPM. Sua conduta é:","options":{"A":"desfibrilação cardíaca imediata","B":"cardioversão elétrica imediata","C":"amiodarona 300 mg EV em bolus","D":"adenosina 1 amp EV","E":"N.D.A."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-75557","number":"75557","sourceNumber":"75557","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher com 60 anos de idade, hipertensa, vai à consulta em Unidade Básica de Saúde\nporque apresentou quadro de parestesias e\nhemiparesia no membro superior esquerdo há uma\nsemana, com reversão espontânea completa em 12 horas. Pressão arterial = 180 x 110 mmHg,\nausculta cardíaca com ritmo irregular, em 2 tempos, exame neurológico sem alterações\nsignificativas. Traz tomografia computadorizada de crânio sem contraste, realizada no dia dos\nsintomas, que é normal. Realizou eletrocardiograma conforme mostrado abaixo - DII (traz exame\nsemelhante feito há 60 dias). (VER IMAGEM). Qual outro fármaco, além do tratamento\n\nanti-hipertensivo, é o mais indicado para essa paciente como medida de maior impacto na\nprevenção de novos episódios do quadro neurológico?","options":{"A":"Warfarina.","B":"Clopidogrel.","C":"Ticlopidina.","D":"Atorvastatina.","E":"Ácido acetilsalicílico."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/75557.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-137579","number":"137579","sourceNumber":"137579","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 55 anos de idade, portador de infecção pelo HIV, diabético do tipo II,\nhipertenso, em terapia antiretroviral, estável há 6 anos, com contagem de linfócitos CD4 de 980\ncélulas/mm (valor de referência < 1 000 células/mm ) e carga viral indetectável (< 25 cópias/mL),\napresentou quadro de perda súbita e transitória da consciência, com queda da própria altura e\nrecuperação espontânea. Na semana seguinte ao episódio, procurou o médico clínico que o\nacompanha; a\n\nhipertensão arterial e o diabetes mellitus mantinham-se controlados. O paciente relatou que, desde\no episódio mencionado, sente ?palpitações? e\n?pulso acelerado?. O médico observou no exame\ncardiovascular: frequência cardíaca = 105 bpm; pressão arterial = 140 x 90 mmHg, ritmo\n\ncardíaco irregular, achados que não haviam sido até então documentados em 10 anos de\nseguimento ambulatorial do paciente. O eletrocardiograma realizado naquela ocasião mostra\nausência de ondas P e intervalos RR muito irregulares. A conduta imediata mais adequada é","options":{"A":"monitorizar o paciente por 48 horas, para observar a\npossibilidade de reversão espontânea da arritmia.","B":"encaminhar o paciente para a emergência cardiológica, para ser submetido à cardioversão\nelétrica.","C":"solicitar ecocardiograma transesofágico, para avaliar a presença de trombos em átrio esquerdo.","D":"iniciar heparinização plena e warfarina, para minimizar o\nrisco existente de doença tromboembólica.","E":"administrar antiarrítmicos intravenosos, para induzir reversão farmacológica da arritmia."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-138414","number":"138414","sourceNumber":"138414","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Adolescente, após tentativa de suicídio com ingestão de antidepressivo tricíclico,\nmanifestou parada cardiorrespiratória. Durante a\nreanimação cardiopulmonar, observou-se o\nseguinte ritmo no monitor cardíaco (VER IMAGEM). A análise do monitor cardíaco permite afirmar\nque o traçado eletrocardiográfico demonstra ritmo de","options":{"A":"taquicardia ventricular, que pode ser responsiva a\nchoque e a uso de atropina.","B":"fibrilação ventricular, que pode ser responsiva a\ncardioversão (choque no modo sincronizado).","C":"fibrilação ventricular, que pode ser responsiva a\ndesfibrilação (choque no modo sincronizado).","D":"taquicardia ventricular, que pode ser responsiva a\ncardioversão (choque no modo sincronizado).","E":"taquicardia ventricular, que pode ser responsiva a\ndesfibrilação (choque no modo não sincronizado)."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/138414.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-19226","number":"19226","sourceNumber":"19226","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Considere que uma paciente, com 60 anos de idade, tenha apresentado quadro de\nperda súbita da consciência precedida por\nacesso de tosse, tendo recobrado a consciência cerca\nde 1 minuto após a adoção de medidas de urgência. Considere ainda que, no exame físico, não\ntenha sido verificada nenhuma alteração, mas a revisão de seu histórico clínico revelou que era\nportadora de asma persistente grave. Nessa situação, a etiologia mais provável é distúrbio\nmetabólico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-19227","number":"19227","sourceNumber":"19227","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Considere que uma paciente, com 60 anos de idade, tenha apresentado quadro de\nperda súbita da consciência precedida por\nacesso de tosse, tendo recobrado a consciência cerca\nde 1 minuto após a adoção de medidas de urgência. Considere ainda que, no exame físico, não\ntenha sido verificada nenhuma alteração, mas a revisão de seu histórico clínico revelou que era\nportadora de asma persistente grave. Nessa situação, a etiologia mais provável é síncope de tosse.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-352188","number":"352188","sourceNumber":"352188","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre a fibrilação atrial, selecione a alternativa incorreta:","options":{"A":"Fibrilação atrial paroxística é aquela que é revertida espontaneamente ou com intervenção\nmédica em até 7 dias de seu início.","B":"Fibrilação atrial persistente é aquela com episódios com duração superior a 7 dias.","C":"O termo fibrilação atrial permanente é utilizado nos casos em que as tentativas de reversão ao\nritmo sinusal não serão mais instituídas.","D":"Considera-se fibrilação atrial aguda quando iniciada há menos de 7 dias."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-345697","number":"345697","sourceNumber":"345697","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O eletrocardiograma nas mulheres difere:","options":{"A":"Em relação à magnitude dos sinais elétricos, com maior amplitude do QRS, do ponto J e da\nonda T e maior intervalo QT corrigido.","B":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e da\nonda T e menor intervalo QT corrigido.","C":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e não da\nonda T e maior intervalo QT corrigido.","D":"Em relação à magnitude dos sinais elétricos, com menor amplitude do QRS, do ponto J e da\nonda T e maior intervalo QT corrigido."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-346839","number":"346839","sourceNumber":"346839","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 68 anos se queixa de tontura ao se levantar. É portador de DM-2 e HAS, e\nfaz uso de metformina, clortalidona e enalapril. Ao exame físico, PA/FC: (deitado)\n190x96mmHg/62bpm; PA/FC: (em pé) 90x46mmHg/61bpm; PA/FC: (após 3 minutos de\nortostatismo) 82x40mmHg/64bpm. Hemoglobina glicada 8,9%. Assinale a alternativa que apresenta\numa conduta INCORRETA para esse paciente:","options":{"A":"Prescrever dapagliflozina.","B":"Orientar o aumento da ingestão de água e sal.","C":"Orientar dormir com a cabeceira elevada (30 a 45 graus).","D":"Substituir clortalidona e enalapril por captopril uma vez ao dia antes de dormir."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-345701","number":"345701","sourceNumber":"345701","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"MJD, feminina de 40 anos, procurou seu atendimento por ter realizado ECG com\nachados no exame periódico. A inversão da\nonda T anterior, isso é, além de V1, ocorre em cerca\nde 2,3% da população e é mais comum em mulheres, independentemente do status de atividade\nfísica. Sendo correto que:","options":{"A":"É um padrão maligno desde que ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","B":"É um padrão benigno desde que não ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","C":"É um padrão benigno desde que ocorra em assintomáticas e de baixo risco, pois estudos\nsugerem que possa refletir um deslocamento lateral do ventrículo direito.","D":"É um padrão benigno desde que ocorra em assintomáticas e de alto risco, pois estudos sugerem\nque possa refletir um deslocamento lateral\ndo ventrículo direito."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-345705","number":"345705","sourceNumber":"345705","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"VLD, feminina de 34 anos, apresentou dor torácica relacionada a cirurgia plástica,\nporém informou que seu ECG estava com achados, por\nisso solicitou sua avaliação. Sua posição\nfoi de que alterações eletrocardiográficas são observadas em 45% das portadoras de implantes\nmamários sendo correto que:","options":{"A":"Inversão de ondas T, depressão do segmento ST inferolateral, alta progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","B":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipotrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","C":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, podendo assim levar a interpretações\nenganosas.","D":"Inversão de ondas T, depressão do segmento ST inferolateral, baixa progressão de R de V1-V4,\nintervalo QT prolongado e hipertrofia ventricular esquerda, nunca podendo assim levar a\ninterpretações enganosas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-345706","number":"345706","sourceNumber":"345706","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As mulheres têm mais taquicardia:","options":{"A":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez reduz o risco de taquicardias\nsupraventriculares","B":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez aumenta o risco de taquicardias\nsupraventriculares.","C":"Sinusal e não de taquicardia por reentrada nodal, sendo que a gravidez aumenta o risco de\ntaquicardias supraventriculares.","D":"Sinusal e taquicardia por reentrada nodal, sendo que a gravidez não aumenta o risco de\ntaquicardias supraventriculares."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-346856","number":"346856","sourceNumber":"346856","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Isadora, 10 anos, sem história prévia de doenças, apresentou subitamente episódio de\ntaquicardia, dificuldade de respirar, acompanhada de palidez e sensação de desmaio. Relata a\n\n?sensação do coração estar saindo pela boca?. Nega desmaios ou síncopes. Ao chegar no\npronto-atendimento, a pediatra notou olhar ansioso, FC: 220bpm, PA: 120x70mmHg, enchimento\ncapilar adequado. Aparelho Respiratório - FR: 48irpm, sem ruídos adventícios. Abdômen: fígado e\n\nbaço não palpados. Foi inicialmente tratado com manobras vagais, sem resposta. Um ECG é obtido\ne mostrou taquicardia, QRS estreito e ausência\nde onda P. Considerando o caso apresentado, o\ndiagnóstico MAIS provável é de:","options":{"A":"Taquicardia sinusal.","B":"Bloqueio Mobitz tipo I.","C":"Taquicardia ventricular monomórfica.","D":"Taquicardia supraventricular."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-335100","number":"335100","sourceNumber":"335100","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 58 anos de idade, hipertenso e diabético, sem histórico de eventos\nisquêmicos, tem FA persistente\nrecém-diagnosticada. Faz uso de enalapril, anlodipina, metformina\ne AAS. Nega uso de álcool ou drogas. Hemograma, função hepática e coagulograma normais. Não\nfaz uso de AINE e não tem histórico de úlcera nem de quedas. Seu ecocardiograma mostra\nmiocardiopatia dilatada com leve regurgitação mitral funcional. É proposta adequada para o\npaciente:","options":{"A":"Iniciar anticoagulação com varfarina, mantendo o AAS.","B":"Iniciar anticoagulação com varfarina, suspendendo o AAS.","C":"Manter apenas oAAS, sem iniciar anticoagulante.","D":"Manter o AAS e associar clopidogrel."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-336303","number":"336303","sourceNumber":"336303","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem, 74 anos, hipertenso e diabético internado na UTI em pós operatório de\ndebridamento cirúrgico de ?pé-diabético? infectado em membro inferior direito. Inicia quadro de\nsudorese, precordialgia e taquicardia seguida de perda do nível de consciência. Monitor\neletrocardiográfico apresenta o traçado abaixo. Qual a conduta imediata?","options":{"A":"Cardioversão elétrica","B":"Amiodarona","C":"Desfibrilação","D":"Adenosina"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-304854","number":"304854","sourceNumber":"304854","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante o atendimento à parada cardiorrespiratória, o acesso venoso profundo está\ncontraindicado. A explicação que fundamenta tal recomendação é:","options":{"A":"Piora do prognóstico neurológico por interrupção das compressões torácicas.","B":"Maior risco de ocorrência de pneumotórax.","C":"Dificuldade técnica no acesso venoso central.","D":"Maior incidência de punção de vasos arteriais."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-227077","number":"227077","sourceNumber":"227077","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 77 anos se queixa de palpitação em repouso. Sem outras queixas. Nega\ndoenças conhecidas ou uso de medicamentos. Ao\nexame físico, PA: 140 X 90mmHg, FC 116bpm,\nFR 15ipm, SpO? 98%. O ritmo cardíaco é irregular, a primeira bulha é hiperfonética e há sopro\nmesodiastólico em ruflar no apex do coração. Sem outras alterações ao exame físico.\n\nEcocardiograma: ventrículo esquerdo de dimensões levemente aumentadas, sem déficits\nsegmentares da contratilidade e fração de ejeção\nde 40%. Átrio esquerdo de volume muito\naumentado. Estenose mitral moderada e insuficiência mitral moderada de morfologia reumática.\nNão se visualizam trombos. Eletrocardiograma; Considerando o caso descrito, assinale a\nalternativa que apresenta a prescrição CORRETA para esse paciente.","options":{"A":"Bisoprolol e varfarina.","B":"Digoxina e enoxaparina.","C":"Diltiazem e rivaroxabana.","D":"Metoprolol e apixabana."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/227077.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-234408","number":"234408","sourceNumber":"234408","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma mulher de 78 anos vai ao consultório de Clínica Médica para uma consulta de\nacompanhamento clínico. Está assintomática. É portadora de insuficiência cardíaca e faz uso de\nfurosemida, enalapril, metoprolol, espironolactona e digoxina. Ao exame físico, apresenta-se alerta\ne orientada. Os dados vitais são PA: 120 X 70mmHg, FC: 30bpm, FR: 17ipm, SpO? em ar ambiente\n97%. O exame cardiovascular revela bradicardia e variação da fonese da primeira bulha. Sem\noutras anormalidades ao exame físico. Solicitou-se um eletrocardiograma apresentado a seguir:\nConsiderando o caso descrito, assinale a conduta imediata MAIS ADEQUADA para essa paciente.","options":{"A":"Administrar atropina, dopamina ou dobutamina em infusão contínua pela via intravenosa.","B":"Posicionar um marcapasso transvenoso até a colocação do marca-passo definitivo.","C":"Suspender o metoprolol e realizar o estudo eletrofisiológico após 48h.","D":"Suspender o metoprolol e a digoxina e manter a monitoração clínica e eletrocardiográfica."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/234408.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-232140","number":"232140","sourceNumber":"232140","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 23 anos, com palpitações, apresenta o eletrocardiograma a seguir. Qual o\ndiagnóstico?","options":{"A":"Fibrilação atrial.","B":"Taquicardia sinusal.","C":"Taquicardia atrial unifocal.","D":"Taquicardia atrial multifocal.","E":"Taquicardia atrial incessante."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/232140.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-232141","number":"232141","sourceNumber":"232141","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 84 anos, evoluindo com quadros de síndromes convulsivas tônico-clônicas\nde repetição, que se iniciam ao repouso, não\nacompanhadas de liberação esfincteriana. Procurou\nconsultório do cardiologista, onde chegou deambulando normalmente e, no meio da consulta,\napresentou uma síncope, seguida de crise convulsiva. Nesse momento, foi realizado\neletrocardiograma abaixo, que confirmou o diagnóstico:","options":{"A":"Bloqueio átrio-ventricular avançado alternante.","B":"Bloqueio átrio-ventricular do segundo grau.","C":"Bloqueio átrio-ventricular do tipo 2:1.","D":"Bloqueio átrio-ventricular do primeiro grau.","E":"Bloqueio átrio-ventricular total."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/232141.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-227322","number":"227322","sourceNumber":"227322","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina, 6 anos, será submetida à cirurgia eletiva e ao ser examinada\nnotou-se ritmo cardíaco irregular, sem outros\nsinais ou sintomas. Feito ECG que demonstrou:\nBaseado na história e ECG, o diagnóstico provável é:","options":{"A":"Arritmia sinusal.","B":"Bloqueio AV de segundo grau.","C":"Bloqueio AV de primeiro grau.","D":"Escape juncional por provável distúrbio eletrolítico."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/227322.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-199493","number":"199493","sourceNumber":"199493","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma mulher de 76 anos apresentou perda súbita da consciência e caiu da cadeira onde\nestava sentada conversando com o filho. Recobrou totalmente o sensório após 2 minutos. Negou\nquaisquer sintomas ou sinais antes e após esse episódio. É portadora de diabetes Mellitus, doença\nrenal crônica e angina do peito. Sofreu de infarto agudo do miocárdio há 10 anos. O exame clínico\nrevelou PA 90 x 50mmHg, FC 104bpm, FR 25ipm, SpO2 91%. Os exames respiratório,\ncardiovascular, abdominal e neurológico resultaram normais. Sobre o caso descrito, assinale a\nalternativa CORRETA:","options":{"A":"A ausência de pródromo afasta a possibilidade de causa cardíaca.","B":"A síncope dessa paciente é postural e pode ser devida à disautonomia da neuropatia periférica\ndo diabetes.","C":"A principal hipótese diagnóstica é hipoglicemia.","D":"O tromboembolismo pulmonar deve ser considerado no diagnóstico diferencial."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-220298","number":"220298","sourceNumber":"220298","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher de 45 anos apresentou perda da consciência após se levantar e sair do ônibus\nem frente a um Pronto-Socorro. Recuperou\ncompletamente a consciência em 2 minutos e estava\nassintomática. Relatou uma sensação de escurecimento visual e tontura logo antes da queda. Era\ndiabética e hipertensa há 20 anos, com tratamento irregular. Possuía doença renal crônica (estádio\n3) e gastroparesia diabética. Fazia uso de hidroclorotiazida, atenolol e metformina. Ao exame\nfísico,\nestava alerta, orientada, corada, hidratada. PA (deitada): 130 x 80mmHg, FC: 103bpm, FR: 17ipm,\nSpO2 98%, Glicemia Capilar: 168mg/dL. Os exames respiratório, cardiovascular e abdominal\nresultaram normais. O exame neurológico revelou hipoestesia em botas nos pés. Observe o\neletrocardiograma a seguir: Sobre o caso descrito, assinale a alternativa CORRETA:","options":{"A":"Trata-se de um caso de crise convulsiva atônica e a paciente deve ser tratada com fenitoína IV.","B":"Trata-se de um caso de síncope cardiogênica por arritmia e a paciente deve ser submetida à\navaliação cardiológica.","C":"Trata-se de um caso de síncope vasovagal e a paciente deve realizar um tilt test.","D":"Trata-se de um caso de síncope postural e deve ser considerado o uso de meias elásticas\ncompressivas e fludrocortisona."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/220298.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-199633","number":"199633","sourceNumber":"199633","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Pré-escolar, masculino, 5 anos de idade, está internado para a correção cirúrgica de\nhérnia inguinal. Ao ser examinado, notou-se que a frequência cardíaca era irregular, sem outras\nanormalidades no exame físico. O Eletrocardiograma (ECG) demonstra o seguinte traçado. Após\nanálise do eletrocardiograma, o diagnóstico é:","options":{"A":"Arritmia sinusal.","B":"Bloqueio AV de 1º grau.","C":"Bloqueio AV de 2º grau.","D":"Bloqueio de ramo direito."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/199633.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-196806","number":"196806","sourceNumber":"196806","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um dos muitos acrósticos usados em medicina é o CHADS 2, (evoluiu para CHA2\nDS2-VASC), usado para avaliar risco de\nacidente vascular cerebral em pessoas com fibrilação\natrial, medida importante para médicos que atuam em Atenção Primária à Saúde (APS). Entre as\nopções abaixo qual a condição clínica é pontuada nesta avaliação de risco? Marque a CORRETA:","options":{"A":"Crise hipertensiva.","B":"Hipertensão intracraniana.","C":"Alteração de ritmo cardíaco.","D":"Diabetes mellitus."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-172544","number":"172544","sourceNumber":"172544","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na reanimação cardiopulmonar:","options":{"A":"A vasopressina mostrou-se claramente superior à adrenalina, mas seu custo bastante superior\ninviabiliza seu emprego na maior parte dos hospitais públicos e ou filantrópicos do Brasil","B":"A amiodarona pode ser usada em determinado momento do protocolo de atendimento da\nfibrilação ventricular (FV), apesar de não haver\nnenhum estudo que mostre sua real capacidade de\nprevenção de morte súbita, por exemplo, em pacientes portadores de miocardiopatia isquêmica\ngrave.","C":"A amiodarona foi abolida na revisão mais recente do protocolo de FV feita pela American Heart\nAssociation, visto a falta de evidências claras que dêem suporte ao seu uso.","D":"A atropina deve ser usada imediatamente após a assistolia ter sido detectada na\nmonitorização cardíaca, uma vez que a demora tornará inútil o emprego nesses casos.","E":"A intubação orotraqueal não poderá ser realizada em hipótese alguma antes do segundo ciclo\nde reanimação, independentemente do diagnóstico inicial e causa da parada cardiorrespiratória."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155343","number":"155343","sourceNumber":"155343","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A fibrilação atrial ocorre com certa frequência em pacientes com insuficiência cardíaca,\npodendo ser uma das causas de\ndescompensação clínica do paciente. Quando necessário, a\nreversão dessa arritmia deve ser feita com um antiarrítmico com pouco ou nenhum efeito inotrópico\nnegativo. Qual opção abaixo indica o fármaco preferido para restaurar e manter o ritmo sinusal\nnesses casos?","options":{"A":"Digoxina.","B":"Quinidina.","C":"Disopiramida.","D":"Amiodarona.","E":"Flecainida."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155370","number":"155370","sourceNumber":"155370","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em paciente com fibrilação atrial aguda e sem cardiopatia estrutural, caso o médico\nopte por reversão da arritmia com droga, qual das abaixo seria a de primeira escolha?","options":{"A":"Amiodarona.","B":"Propafenona.","C":"Adenosina.","D":"Quinidina.","E":"Sotalol."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155467","number":"155467","sourceNumber":"155467","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentre as opções abaixo, é causa de parada cardiorrespiratória:","options":{"A":"Hipercalcemia.","B":"Hiperglicemia.","C":"Trombose venosa profunda.","D":"Hipertermia.","E":"Intoxicação por Organofosforado."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155419","number":"155419","sourceNumber":"155419","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"No idoso, a diminuição das respostas cronotrópicas e inotrópicas aos beta-agonistas\ndeve-se à(ao):","options":{"A":"Redução da responsividade dos receptores beta-adrenérgicos.","B":"Aumento do número de receptores adrenérgicos.","C":"Aumento da responsividade dos receptores beta-adrenérgicos.","D":"Redução do número de receptores alfa-adrenérgicos.","E":"Aumento da responsividade dos receptores alfa e beta-adrenérgicos > plasmática."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127150","number":"127150","sourceNumber":"127150","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 52 anos chega ao pronto socorro com dor precordial e durante o\natendimento médico apresenta parada\ncardiorespiratória. Nesta situação, a primeira conduta a ser\ntomada deve ser:","options":{"A":"Abertura de vias aéreas.","B":"Intubação orotraqueal.","C":"Compressões torácicas ritmadas.","D":"Cardiodesfibrilação.","E":"Ventilação com dispositivo bolsa-máscara."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127178","number":"127178","sourceNumber":"127178","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente admitido na emergência trazido pelos familiares 10 minutos após ser\nencontrado inconsciente em casa. Constata-se\narresponsividade, ausência de pulso e de\nrespiração. Ritmo apresentado ao monitor: (VER IMAGEM) Assinale a conduta mais apropriada:","options":{"A":"Iniciar compressões torácicas e ventilação adequada na relação 30:2.","B":"Desfibrilar imediatamente.","C":"Ventilar e iniciar imediatamente as compressões torácicas.","D":"Administrar 1 mg de adrenalina por via endovenosa.","E":"Administrar imediatamente amiodarona iniciando as compressões torácicas."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/127178.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-126896","number":"126896","sourceNumber":"126896","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma pessoa de aproximadamente 50 anos perde a consciência em um shopping, cai e\nvocê vai ajudá-la. No seu exame inicial o paciente está imóvel, sem movimentos respiratórios, sem\npulso central. Não há desfibrilador no local e a ambulância do SAMU só chegará em 12 minutos.\n\nConsiderando a situação descrita, assinale a alternativa que apresenta a conduta CORRETA a ser\nadotada até a chegada da Unidade Móvel.","options":{"A":"Realizar suporte básico de vida (30 compressões torácicas intercaladas com 2 ventilações) até a\nchegada de um desfibrilador.","B":"Realizar um soco precordial para simular a desfibrilação, pois este paciente provavelmente teve\numa PCR por fibrilação ventricular.","C":"Realizar imediatamente 2 ventilações de resgate e se o paciente não recuperar a consciência\niniciar as compressões torácicas.","D":"Realizar suporte básico de vida (15 compressões torácicas intercaladas com 2 ventilações) até a\nchegada de um desfibrilador."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-131651","number":"131651","sourceNumber":"131651","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"No tratamento da parada cardíaca, em pacientes que continuam a ter fibrilação\nventricular, apesar da desfibrilação com corrente\ndireta após epinefrina, pode ser administrado o\nseguinte agente intravenoso:","options":{"A":"Metoprolol;","B":"Verapamil;","C":"Flecainide;","D":"Digoxina;","E":"Amiodarona."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-102765","number":"102765","sourceNumber":"102765","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 41 anos, sexo feminino, evoluindo com dispneia (NYHA II) nos últimos 3\nmeses, procura Pronto Atendimento devido à piora aguda do quadro e palpitações. Relata ter feito\nuso de antibiótico injetável até os 17 anos (não sabe o motivo), mas interrompeu por conta própria.\nNão faz acompanhamento médico desde então e desconhece outras comorbidades. Não está em\nuso de nenhum medicamento. Ao exame físico, apresentava FC: 168 bpm, PA: 130 x 70 mmHg,\nFR: 26 irpm. Jugulares planas, sem edema periférico. Pulsos arrítmicos, cheios e de amplitude\nvariável. Ritmo cardíaco irregular em 3 tempos, B1 hipofonética e presença de 3ª bulha, com sopro\nholossistólico grau III/VI irradiando para axila. MVF com discretas crepitações em bases. Demais\nsistemas sem alterações. Com relação ao manejo da Fibrilação Atrial - FA - dessa paciente,\nassinale a alternativa INCORRETA.","options":{"A":"Trata-se de uma FA aguda, devendo-se, portanto, realizar cardioversão elétrica imediata.","B":"Caso a cardioversão não seja bem sucedida, deve-se optar por anticoagulação com varfarina,\ndabigatrana ou rivaroxabana.","C":"Não se pode determinar o tempo de início da FA, por isso, a cardioversão só é segura após\nrealização de ecocardiograma transesofágico.","D":"Caso o controle do ritmo cardíaco não seja possível, além da anticoagulação, deve ser realizado\ncontrole da frequência cardíaca."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-102756","number":"102756","sourceNumber":"102756","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente admitido no pronto-socorro após tentativa de autoextermínio, apresentando\nsonolência, bradicardia, pupilas puntiformes\nbilateralmente, hipersalivação, tosse com secreção\nhialina e diarreia aquosa profusa, sem controle esfincteriano. Considerando o caso descrito, além\ndas medidas básicas iniciais de suporte à vida, assinale a alternativa que apresenta a MELHOR\nconduta para tentar reverter esse quadro.","options":{"A":"Administrar atropina EV 1 mg, de 10 em 10min, até a recuperação dos valores normais e dos\nníveis séricos de acetilcolinesterase.","B":"Administrar epinefrina EV 1 mg, de 10 em 10min, até correção completa da bradicardia, miose e\nsonolência.","C":"Administrar atropina EV 1 mg, de 10 em 10min, até melhorar a hipersalivação, broncorreia e\ndiarreia.","D":"Administrar neostigmina EV 1 mg, de 10 em 10min, até a recuperação dos valores normais e\ndos níveis séricos de acetilcolinesterase."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-102759","number":"102759","sourceNumber":"102759","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa que NÃO representa um efeito colateral típico da amiodarona.","options":{"A":"Hipotireoidismo.","B":"Bloqueio atrioventricular.","C":"Necrose tubular aguda.","D":"Pneumonite intersticial."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-100977","number":"100977","sourceNumber":"100977","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação ao manejo da Parada Cardiorrespiratória (PCR), assinale a alternativa\nINCORRETA:","options":{"A":"Quando a monitorização com desfibrilador manual revela ritmo de Fibrilação Ventricular/\nTaquicardia Ventricular Sem Pulso (FV/TVSP), a\nprioridade deve ser a desfibrilação o mais precoce\npossível.","B":"Em qualquer ritmo de PCR, a primeira droga a ser utilizada deve ser um vasopressor.","C":"O atraso no início da administração de vasopressores para além dos primeiros dois minutos de\nPCR, bem como a demora em instalar via aérea avançada, podem estar associados a pior\nprognóstico.","D":"Monitorização do dióxido de carbono exalado (> 10 mmHg) é um bom indicador da qualidade da\nreanimação.","E":"Atropina não é recomendada em caso de parada cardíaca em assistolia ou atividade elétrica\nsem pulso."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-77323","number":"77323","sourceNumber":"77323","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Conforme o último <i>guideline</i> de atendimento da parada cardiorrespiratória da\n\n<i>American Heart Association</i>, em que momento do protocolo de atendimento da assistolia a\natropina deve ser usada?","options":{"A":"Assim que identificada no monitor.","B":"Após o primeiro ciclo de ressuscitação cardiopulmonar.","C":"Após a passagem do marca-passo transvenoso.","D":"Não deve ser usada rotineiramente neste protocolo.","E":"Após a passagem do marca-passo transcutâneo."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-77343","number":"77343","sourceNumber":"77343","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual das afirmações sobre os efeitos da epinefrina durante a tentativa de ressuscitação\né verdadeira?","options":{"A":"A epinefrina reduz a resistência vascular periférica e diminui a pós-carga miocárdica, de modo\nque as contrações ventriculares são mais\neficazes.","B":"A epinefrina melhora a pressão de perfusão da artéria coronária e estimula as contrações\nespontâneas quando há assistolia.","C":"A epinefrina é contraindicada na fibrilação ventricular, pois aumenta a irritabilidade\nmiocárdica.","D":"A epinefrina reduz o consumo de oxigênio miocárdico.","E":"Nenhuma das respostas acima."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-88890","number":"88890","sourceNumber":"88890","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Amiodarona é um antiarrítmico muito usado na prática clínica, porém pode causar\nefeitos colaterais importantes. Qual evento\nadverso abaixo não pode ser atribuído à Amiodarona?","options":{"A":"Fibrose pulmonar.","B":"Hipotireoidismo.","C":"Síndrome do QT longo.","D":"Convulsões.","E":"Hipertireoidismo."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-88888","number":"88888","sourceNumber":"88888","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 21 anos com episódios de pré-síncopes e síncopes, associados à\nsudorese fria e náuseas. ECG normal. Qual\nexame deve ser solicitado para elucidar o diagnóstico?","options":{"A":"Holter.","B":"Tilt-Test.","C":"Ecocardiograma com Doppler.","D":"Estudo eletrofisiológico.","E":"RM cardíaca."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-88886","number":"88886","sourceNumber":"88886","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 30 anos, admitido com mal-estar, dispneia e síncope. ECG mostra\nsupradesnivelamento de segmento ST em V1 e V2, e padrão de BRD em V1. Cateterismo\nrealizado, imediatamente, foi normal. Qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome de Dressler.","B":"Síndrome do QT longo.","C":"Síndrome de Brugada.","D":"Displasia arritmogênica do VD.","E":"Síndrome do QT curto."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-59336","number":"59336","sourceNumber":"59336","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação aos novos anticoagulantes orais marque a alternativa CORRETA:","options":{"A":"Apesar de apresentarem a comodidade posológica de não ser necessário o controle de RNI,\nainda não conseguiram comprovar em estudos\nrandomizados uma eficácia semelhante à warfarina\nna prevenção de fenômenos tromboembólicos em portadores de fibrilação atrial.","B":"Apresentam taxas de sangramento maior (hemorragia intracraniana, por exemplo) superiores à\nwarfarina, por isso nenhum deles foi liberado ainda para uso em idosos acima de 80 anos.","C":"A dabigratana (Pradaxa) é o único já liberado para uso na prevenção de fenômenos\ncardioembólicos relacionados à fibrilação atrial.","D":"Podem ser usados em pacientes com próteses cardíacas metálicas para prevenção de\ntrombose, com eficácia comprovadamente não inferior à warfarina.","E":"A rivaroxabana (Xarelto) além de poder ser usada na prevenção de fenômenos tromboembólicos\nrelacionados à fibrilação atrial, apresenta estudos bem conduzidos no tratamento de pacientes com\nembolia pulmonar."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-44005","number":"44005","sourceNumber":"44005","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente masculino, 04 anos, internado na enfermaria de pediatria com diagnóstico de\npneumonia e derrame pleural à esquerda, de pequeno volume sem indicação de drenagem. Ao ser\nexaminado, foi auscultado ritmo cardíaco irregular. O restante do exame não demonstrou\nanormalidades, além da taquidispneia leve e crepitações em base esquerda. No traçado\neletrocardiográfico observa-se: (VER IMAGEM). Qual o diagnóstico?","options":{"A":"Se esse achado for associado com crossa da aorta posicionada à direita da traqueia visto ao\nraio X de tórax, o diagnóstico provável é de tetralogia de Fallot.","B":"Se houver história pregressa de prematuridade, o diagnóstico provável é de canal arterial\npersistente.","C":"Esse achado eletrocardiográfico é compatível com situs inversus.","D":"Provavelmente o paciente apresenta alteração no estímulo parassimpático para o coração\nresultando em aumento da frequência cardíaca na inspiração e diminuição na expiração.","E":"Se houver história pregressa de síncope, o diagnóstico provável é de síndrome de\nWolff-Parkinson-White."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/44005.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-23070","number":"23070","sourceNumber":"23070","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher de 25 anos é atendida no pronto-socorro com história de palpitações\ntaquicárdicas, de início súbito, após\ndiscussão familiar, associada a mal-estar geral, sem sinais de\nbaixo débito. PA = 110/70 mmHg. Frequência Cardíaca = 180 bpm e eletrocardiograma\ndemonstrando taquicardia de QRS estreito. Qual a primeira conduta a ser tomada?","options":{"A":"Amiodarona 300 mg endovenosa","B":"Propafenoma 600 mg via oral","C":"Cedilanide meia ampola endovenosa","D":"Manobra vagal","E":"Adenosina 02 ampolas endovenosa"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-23171","number":"23171","sourceNumber":"23171","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na fibrilação atrial crônica, há fatores considerados de fraco, moderado e elevado risco\npara complicações trombo-embólicas. Nas alternativas abaixo, marque aquela em que os 3 fatores\nde risco são classificados como elevados:","options":{"A":"ataque isquêmico transitório prévio, idade avançada, hipertensão arterial.","B":"embolia arterial periférica prévio, prótese valvular mitral, coronariopatia.","C":"idade avançada, cononariopatia, baixa fração de ejeção do ventrículo esquerdo.","D":"AVC isquêmico prévio, baixa fração de ejeção do ventrículo esquerdo, estenose mitral.","E":"embolia arterial prévia, prótese valvular mitral, estenose mitral."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-9392","number":"9392","sourceNumber":"9392","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em um paciente idoso com hipotensão arterial postural sintomática idiopática, qual\nmedicamento poderá ser empregado?","options":{"A":"Amiodarone.","B":"Aminofilina.","C":"Codeína.","D":"Midodrine.","E":"Cloridrato dietilefedrina."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-363960","number":"363960","sourceNumber":"363960","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para qual destas situações há indicação CLASSE I de implante de marcapasso\ndefinitivo?","options":{"A":"Doença do nó sinusal em pacientes em uso de amiodarona.","B":"Bloqueio atrioventricular de segundo grau Mobitz I (Wenckebach) durante o sono.","C":"Sincope recorrente, > 40 anos de idade e documentação de pausa sintomática espontânea\nmaior que 6 segundos","D":"Pacientes com miocardiopatia hipertrófica forma obstrutiva, mesmo com gradiente de via de\nsaída de ventrículo esquerdo baixo."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-331961","number":"331961","sourceNumber":"331961","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher, 73 anos, tem diagnóstico de fibrilação atrial paroxística. Antecedentes\npessoais: hipertensão controlada com medicação.\nNega diabetes, outras doenças ou internações\nprévias. Radiograma de tórax: área cardíaca normal, sem calcificações vasculares. Em relação à\nabordagem terapêutica da fibrilação atrial nesta paciente, é correto:","options":{"A":"O escore de CHADS-VASC é de 3, sem indicação de terapia antitrombótica, pela ausência de\nevidência de eventos prévios.","B":"O escore de CHADS-VASC é de 2, sendo que um ponto é pelo gênero, sem indicação de terapia\nantitrombótica.","C":"O escore de CHADS-VASC é de 3, com indicação de terapia antitrombótica.","D":"O escore de CHADS-VASC não se aplica nessa situação, por se tratar de arritmia paroxística"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-330063","number":"330063","sourceNumber":"330063","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O eletrocardiograma, também chamado de ECG, é o registro gráfico dos fenômenos\nelétricos do músculo cardíaco ou do coração. Com base no tema, é CORRETO afirmar:","options":{"A":"O complexo QRS representa a despolarização e a condução do impulso nos ventrículos.","B":"O ECG é registrado em papel gráfico, na velocidade (linha vertical) de 20 mm/s, ou 1mm a cada\n0,04 segundos.","C":"As derivações periféricas são obtidas no plano horizontal, pela colocação de eletrodos no tórax\ndo paciente.","D":"O posicionamento do eletrodo para derivação precordial V4 deve ser de 4° espaço intercostal à\ndireita, próximo ao esterno."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-330069","number":"330069","sourceNumber":"330069","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dispneia é um termo que indica uma experiência subjetiva de dificuldade ou\ndesconforto respiratório, que consiste em\nsensações qualitativamente distintas, de intensidade\nvariável, e é traduzida por diferentes sinais semiológicos. Podem acontecer manifestações de\ndispneia quando o paciente assume uma posição reclinada, comum em portadores de Insuficiência\nCardíaca Congestiva (ICC). Esta afirmação refere-se a:","options":{"A":"Ortopneia.","B":"Trepopneia.","C":"Platipneia.","D":"Disparapneia."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-342615","number":"342615","sourceNumber":"342615","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, não podemos afirmar que:","options":{"A":"as células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo","B":"a reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional","C":"as arritmias cardíacas podem ser classificadas, quanto à repercussão clínica, em estável ou\ninstável","D":"cicatrizes (fibroses) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-330088","number":"330088","sourceNumber":"330088","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com relação às arritmias cardíacas em Pediatria, é CORRETO afirmar:","options":{"A":"A taquicardia ventricular tem início geralmente abrupto, exceto em lactentes, que apresentam\nirritabilidade, inapetência e dispneia enquanto evoluem para insuficiência cardíaca congestiva.","B":"O paciente com bloqueio atrioventricular deve ser submetido diretamente à cardioversão elétrica\nsincronizada ou à cardioversão química com adenosina, o que for mais rápido na situação.","C":"A taquicardia sinusal é definida como frequência cardíaca maior do que 220 bpm no lactente e\nmaior do que 180 bpm nas crianças maiores, com complexo QRS estreito e ausência de onda P.","D":"Os sinais clínicos associados à bradiarritmia podem ser choque com hipotensão, perfusão\nineficiente de órgão- alvo, alteração do nível de consciência ou colapso súbito."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300803","number":"300803","sourceNumber":"300803","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O eletrocardiograma realiza a reprodução gráfica da atividade elétrica do coração\ndurante o seu funcionamento, registrada a\npartir da superfície do corpo. Quanto às principais\nalterações eletrocardiográficas, onda P com orientação normal e frequência cardíaca < 50 bpm\ndenotam:","options":{"A":"Parada sinusal.","B":"Bloqueio sinoatrial (BSA).","C":"Bradicardia sinusal.","D":"Bloqueio de ramo esquerdo (BRE)."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300914","number":"300914","sourceNumber":"300914","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O uso de betabloqueadores via oral ou intravenosa após a PCR por FV/TVSP mostrou\nreduzir mortalidade 72 horas após e em 6 meses. Está CORRETO o item:","options":{"A":"Não podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC) e causar\narritmias.","B":"No entanto, podem levar à piora hemodinâmica, e nunca exacerbar sinais de Insuficiência\nCardíaca (IC) e causar arritmias.","C":"No entanto, podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC)\ne causar arritmias.","D":"No entanto, podem levar à piora hemodinâmica, exacerbar sinais de Insuficiência Cardíaca (IC)\ne não causar arritmias."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-313197","number":"313197","sourceNumber":"313197","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com relação à Fibrilação Atrial (FA), assinale a alternativa correta:","options":{"A":"a FA paroxística diminui sua incidência com o aumento da idade","B":"a FA apresenta baixa morbimortalidade em mulheres hipertensas acima de 80 anos","C":"a FA persistente é a forma mais comum de apresentação","D":"a FA paroxística que apresenta reversão espontânea apresenta baixa taxa de recorrência, e o\npaciente pode ser mantido sem anticoagulação, independentemente de outros fatores de risco"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-317939","number":"317939","sourceNumber":"317939","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A melhor conduta diante de uma idosa com doença de Chagas que apresenta\ntaquicardia ventricular sustentada, FC 155bpm e PA 85x55mmHg é:","options":{"A":"amiodarona endovenosa.","B":"lidocaína endovenosa.","C":"cardioversão elétrica.","D":"implante imediato de cardiodesfibrilador."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-295354","number":"295354","sourceNumber":"295354","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentre as arritmias conhecidas, qual é a mais comum durante atendimentos de\nemergência?","options":{"A":"Extrassistolia ventricular.","B":"Taquicardia sinusal.","C":"Fibrilação atrial.","D":"Taquicardia ventricular."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-317940","number":"317940","sourceNumber":"317940","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A melhor conduta diante de um idoso com fibrilação atrial sem data certa de início, FC =\n110 BPM e PA 130x85 mmHg é:","options":{"A":"cardioversão química.","B":"cardioversão elétrica.","C":"controle de frequência cardíaca e anticoagulação.","D":"estudo eletrofisiológico."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-317162","number":"317162","sourceNumber":"317162","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com base no traçado do Eletrocardiograma abaixo, assinale a correta:","options":{"A":"A frequência cardíaca é de 100 bpm.","B":"O ritmo não é sinusal","C":"Observa-se um desvio do eixo elétrico para esquerda","D":"Provável síndrome coronariana aguda"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/317162.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300926","number":"300926","sourceNumber":"300926","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Adenosina é uma droga que diminui a condução pelo nó atrioventricular e promove\nvasodilatação coronária. Sendo CORRETO que:","options":{"A":"Possui meia-vida de menos de 5 a 10 minutos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS estreito.","B":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS estreito.","C":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, e inefetivo no término da\nmaioria das taquicardias de QRS estreito.","D":"Possui meia-vida de menos de 5 a 10 segundos, tendo efeito fugaz, porém efetivo no término da\nmaioria das taquicardias de QRS largo."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300927","number":"300927","sourceNumber":"300927","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As contraindicações absolutas à adenosina são listadas adequadamente na alternativa:","options":{"A":"Bloqueio atrioventricular de primeiro grau, disfunção do nó sinusal e FA pré-excitada.","B":"Bloqueio de ramo direito, disfunção do nó sinusal e FA pré-excitada.","C":"Bloqueio atrioventricular de segundo ou terceiro graus, disfunção do nó sinusal e FA\npré-excitada.","D":"Bloqueio atrioventricular de segundo ou terceiro graus, disfunção do nó átrio ventricular e FA\npré-excitada."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300930","number":"300930","sourceNumber":"300930","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Verapamil e diltiazem mostraram-se efetivos em reversão para ritmo sinusal em\ndiversos ensaios clínicos e nesse contexto, assinale a alternativa correta:","options":{"A":"Permanecem como tratamento de segunda linha para o tratamento das taquicardias\nsupraventriculares.","B":"Permanecem como tratamento de primeira linha para o tratamento das taquicardias\nventriculares.","C":"Permanecem como tratamento de primeira linha para o tratamento das bradicardias\nsupraventriculares.","D":"Permanecem como tratamento de primeira linha para o tratamento das taquicardias\nsupraventriculares."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-311923","number":"311923","sourceNumber":"311923","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Utilizando como base o BLS/ACLS, como deve orientar sua equipe em vigência de uma\nparada cardiorrespiratória, visando a uma reanimação de qualidade?","options":{"A":"Velocidade de compressão até 100 vezes por minuto.","B":"Administrar adrenalina a cada 2 minutos.","C":"Se houver via área avançada, manter massagem cardíaca contínua com ventilações a cada 6\nsegundos.","D":"Profundidade de compressão entre 5-7 cm."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-300933","number":"300933","sourceNumber":"300933","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em pacientes estáveis com Fibrilação Atrial e Flutter Atrial, dados como Fração de\nEjeção de Ventrículo Esquerdo (FEVE), tempo de duração da arritmia (menor ou maior que 48\nhoras) e presença de pré-excitação ventricular (síndrome de Wolf-Parkinson-White) estão de\nacordo com o item:","options":{"A":"São dispensáveis para tomada de decisões acerca de indicação de anticoagulação, reversão do\nritmo ou controle da resposta ventricular e avaliação da segurança para reversão do ritmo.","B":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo ou controle da resposta ventricular e\navaliação da segurança para reversão do ritmo.","C":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo e não do controle da resposta\nventricular e avaliação da segurança para reversão do ritmo.","D":"São imprescindíveis para tomada de decisões acerca de indicação de anticoagulação, reversão\ndo ritmo ou controle da resposta ventricular e\nnunca da avaliação da segurança para reversão do\nritmo."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-308286","number":"308286","sourceNumber":"308286","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente é encontrado não responsivo em leito de enfermaria pela equipe de\nenfermagem que, de imediato, aciona o código\nazul. Você se dirige para avaliação do caso e\npercebe que o paciente não responde e não apresenta pulso. O carrinho de parada já se encontra\nno cenário. Neste contexto, a melhor conduta imediata é:","options":{"A":"Desfibrilação com 200 J.","B":"RCP por 2 minutos seguida de avaliação de ritmo.","C":"Amiodarona EV 300mg em bolus.","D":"Cardioversão com 200 J."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-273122","number":"273122","sourceNumber":"273122","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A anamnese possui elementos estruturais que buscam trazer fatos e dados de grande\nrelevância para a construção do raciocínio diagnóstico que, a partir da história clínica do\npaciente,\nbem como do conhecimento de determinados fatores a ele relacionados, possibilitam a definição da\nestratégia a ser utilizada para exames complementares e procedimentos medicinais adequados\ndiante do diagnóstico do paciente. Faz parte da estrutura da anamnese:","options":{"A":"O reconhecimento.","B":"Histórico de doenças futuras.","C":"Queixa e duração.","D":"Hábitos religiosos."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-285058","number":"285058","sourceNumber":"285058","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma paciente de 26 anos procurou a emergência com queixas de pal pitações e\ndispneia aos esforços, iniciadas há três\ndias. Ao exame, apresenta-se eupneica, conscien te e\norientada, com turgência jugular, estertores fi nos em bases pulmonares, ritmo cardíaco irregu\nlarmente irregular com frequência de 120 bpm e sopro diastólico no ictus cordis. PA 120x70mmHg.\nQual a medida recomendada nesse momento?","options":{"A":"Diltiazem.","B":"Amiodarona.","C":"Ecocardiograma transesofágico.","D":"Cardioversão elétrica.","E":"Warfarin."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-258162","number":"258162","sourceNumber":"258162","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante uma partida de futebol em um clube da cidade, um jogador cai no gramado\nespontaneamente, ou seja, sem contato com outro jogador ou objeto. À avaliação inicial,\nencontrava-se irresponsivo, sem ventilação espontânea e sem pulso. Foram iniciadas manobras de\nreanimação. Em menos de três minutos houve a chegada da caixa de socorro com ambu e\nmáscara facial e dispositivo automático externo (DEA), que estavam bem próximos ao campo de\nfutebol. Nesse caso, qual deverá ser a próxima conduta?","options":{"A":"Manter massagem cardíaca externa e ventilação com máscara e ambu na frequência 30:2, sem\ninterrupções enquanto aguarda-se o socorro médico.","B":"Instalar o DEA, de acordo com as instruções, e aguardar até 15 segundos para leitura do ritmo.","C":"Instalar o DEA e após cinco segundos, se o ritmo não for identificado, reiniciar a massagem\ncardíaca externa.","D":"Realizar ajuste manual para desfibrilação com 200J, caso o ritmo não for identificado pelo DEA\napós cinco segundos e o paciente continuar\nsem pulso."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-257720","number":"257720","sourceNumber":"257720","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 44 anos, obeso, fumante e dislipidêmico, apresenta um episódio de\nfibrilação atrial após ingesta excessiva de bebida alcoólica. De acordo com a classificação de\nCHA2DS2-VASc, qual o tratamento adequado para prevenção de fenômeno tromboembólico?","options":{"A":"Orientação e acompanhamento.","B":"Aspirina 100 mg, ao dia.","C":"Warfarina.","D":"Rivaroxabana 20 mg, ao dia."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-258171","number":"258171","sourceNumber":"258171","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os betabloqueadores pertencem a qual classe de antiarrítmicos?","options":{"A":"V.","B":"IV.","C":"III.","D":"II."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265855","number":"265855","sourceNumber":"265855","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A terapia farmacológica também pode ser recomendada para se restaurar o ritmo\nsinusal de Fibrilação Atrial e Flutter Atrial de início < 48 horas, sendo ADEQUADO o item:","options":{"A":"É a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos\nforam realizados para definir a eficácia de medicações\nna cardioversão química da FA.","B":"Não é a primeira escolha (exceto para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos foram realizados para definir a eficácia de medicações\nna cardioversão química da FA.","C":"Não é a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Não existem estudos realizados para definir a eficácia de medicações na\ncardioversão química da FA.","D":"Não é a primeira escolha (reservar para casos em que a CVE e seu preparo - sedação - impõem\nrisco alto para o paciente). Vários estudos foram realizados para definir a eficácia de medicações\nna cardioversão química da FA."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265856","number":"265856","sourceNumber":"265856","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Evidências recentes mostraram que a lidocaína apresentou mesma taxa de sobrevida\nquando comparada à amiodarona em PCR extra-hospitalar. Podemos indicar como CORRETO\nque:","options":{"A":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP não\npersistir, uma segunda dose de 0,5 a 0,75 mg/kg pode ser administrada. Seu uso pode ser\nconsiderado após a PCR em FV/TVSP em infusão contínua.","B":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso não pode ser considerado\napós a PCR em FV/TVSP em infusão contínua.","C":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso pode ser considerado após\na PCR em FV/TVSP em infusão não contínua.","D":"A dose inicial recomendada é de 1,0 a 1,5 mg/kg por via intravenosa. Se a FV/TVSP persistir,\numa segunda dose de 0,5 a 0,75 mg/kg pode ser\nadministrada. Seu uso pode ser considerado após\na PCR em FV/TVSP em infusão contínua."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265858","number":"265858","sourceNumber":"265858","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Estudos observacionais mostraram que a administração de sulfato de magnésio por via\nintravenosa pode finalizar TV polimórfica do tipo TdP, podemos indicar como CORRETO que:","options":{"A":"É efetiva para TV polimórfica em pacientes com intervalo QT normal.","B":"Não é efetiva para TV polimórfica do tipo TdP.","C":"Não é efetiva para TV polimórfica em pacientes com intervalo QT normal.","D":"Não é efetiva para TV polimórfica em pacientes com intervalo QT padrão."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265859","number":"265859","sourceNumber":"265859","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação à orientação do uso de drogas e manobras no Suporte Avançado de Vida\nem adultos, indique o item ERRADO:","options":{"A":"Amiodarona ou lidocaína devem ser considerados como antiarrítmico de primeira escolha para\nFV/TVSP que não responde a RCP, desfibrilação e vasopressor.","B":"O uso de lidocaína pode ser considerado alternativa na PCR em FV/TVSP.","C":"O uso precoce de betabloqueadores pode ser considerado em pacientes pós-RCE por ritmos de\nFV/TVSP","D":"O soco precordial pode ser considerado na TV instável em pacientes monitorizados, quando um\ndesfibrilador está imediatamente pronto para uso."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265861","number":"265861","sourceNumber":"265861","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O cálcio apresenta papel no mecanismo celular de contração miocárdica e da\nmusculatura lisa vascular. Indique o item com ERRO:","options":{"A":"Não há evidências científicas que deem suporte ao uso rotineiro do cálcio na RCP.","B":"Seu uso pode ser considerado, na dose de 0,5 a 1 g (gluconato de cálcio 10%, de 15 a 30 mL,\nou cloreto de cálcio 10%, de 5 a 10 mL).","C":"Seu uso pode ser considerado nas seguintes condições de PCR: hiperpotassemia, hipocalcemia\ne intoxicação por agentes bloqueadores dos canais\nde cálcio.","D":"Utilizar soluções de cálcio e bicarbonato de sódio simultaneamente na mesma via de\nadministração."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-281992","number":"281992","sourceNumber":"281992","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação à prevenção de fenômenos tromboembolicos na fibrilação atrial, é correto\nafirmar que:","options":{"A":"Os NOACs (novos anticoagulantes orais) reduzem as taxas de acidente vascular encefálico\nhemorrágico ao serem comparados aos antagonistas da vitamina K.","B":"A anticoagulação plena só é indicada nas formas persistente e permanente da fibrilação ou\nflutter.","C":"O escore CHADSVASC é usado para avaliar risco tromboembólico, sendo indicada\nanticoagulação com escores acima de 3 pontos.","D":"O anticoagulante de preferência em pacientes com prótese valvar mecânica aórtica é o\ndabigatrana."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265865","number":"265865","sourceNumber":"265865","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na Massagem do Seio Carotídeo (MSC), temos esse mesmo reflexo, sendo CORRETO\nque:","options":{"A":"Inibido pela pressão externa no bulbo carotídeo, estimulando seus barorreceptores.","B":"Deflagrado pela pressão externa no bulbo carotídeo, reprimindo seus barorreceptores.","C":"Deflagrado pela pressão interno no bulbo carotídeo, estimulando seus barorreceptores.","D":"Deflagrado pela pressão externa no bulbo carotídeo, estimulando seus barorreceptores."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-281996","number":"281996","sourceNumber":"281996","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O ano de 2020 foi um ano marcado por diversas atualizações publicadas pela AHA\n(American Heart Association) em que houve algumas modificações. Sobre isso, assinale a\nalternativa incorreta:","options":{"A":"Os elos da cadeia de sobrevivência bem como as medidas de cuidados pós-parada cardíaca\nforam ratificados em 2020, por recentes estudos e\nníveis de recomendações cada vez mais\nelevados.","B":"Nos ritmos em assistolia ou atividade elétrica sem pulso (AESP), a prioridade é a administração\nprecoce de adrenalina 1 mg. Além disso, o\nacesso intravenoso se tornou definitivamente a\npreferência, só devendo o intraósseo ser utilizado se não houve sucesso. A busca por causas\nreversíveis pelo 5H/5T não foram modificadas.","C":"No algoritmo das bradicardias instáveis foi dobrada a dose de atropina para 1mg a cada 3 a\n5min, assim como a dose mínima de dopamina de 2 para 5Mcg/kg/min.","D":"No caso da FV/TV, a prioridade é realizar desfibrilação elétrica na carga recomendada pelo\nfabricante (em geral 200J bifásico, mas na dúvida coloque a carga máxima do seu aparelho) e\nreiniciar a massagem cardíaca. A sequência de drogas, adrenalina e amiodarona, está mantida,\nbem como os ciclos de 30:2 compressão/ventilação."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-274478","number":"274478","sourceNumber":"274478","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente sexo feminino, 55 anos, chega ao pronto atendimento com queixa de\npalpitação. Ao avaliar paciente você não\nidentifica nenhum sinal de instabilidade clínica. Saturação\nadequada na oximetria. Ao monitorá-la, percebe uma taquicardia monomórfica de complexo largo.\nPaciente se mantém comunicando normalmente. Dentro deste contexto a conduta inicial MAIS\nADEQUADA é:","options":{"A":"Amiodarona venosa 300 mg em bolus.","B":"Amiodarona venosa 150 mg em 10 minutos.","C":"Milrinone venoso 300 mg em 10 minutos.","D":"Milrinone venoso 150 mg em bolus."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265869","number":"265869","sourceNumber":"265869","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"São antecedentes familiares importantes na avaliação de crianças e adolescentes que\napresentam síncope, EXCETO:","options":{"A":"Doença cardíaca congênita.","B":"Arritmias.","C":"Doenças metabólicas.","D":"História de pneumonia com derrame em pais ou irmãos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-265884","number":"265884","sourceNumber":"265884","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao exame físico de crianças com\nsíncope:","options":{"A":"Os sinais vitais devem ser registrados exclusivamente com o paciente em posição ortostática.","B":"Se a pressão sistólica de adolescentes, após a realização dos dois registros dos sinais vitais,\nfor\nmenor do que 80 mmHg ou houver variação de mais de 30mmHg, a etiologia provável é vagal\nmediada.","C":"A palpação do precórdio na avaliação cardiológica pode sugerir doenças cardíacas estruturais.","D":"Qualquer deficiência focal ou anormalidade no exame neurológico deve alertar o pediatra para\npossibilidade convulsão ou outra doença neurológica como causa da síncope."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-274834","number":"274834","sourceNumber":"274834","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Adolescente, sexo masculino, 12 anos, comparece a consulta solicitando atestado para\nprática de natação. Assintomático, sem história familiar de risco para doença cardiovascular.\n\nExame físico: dados vitais e exame segmentar normais. Traz eletrocardiograma realizado há um\nano para avaliação pré-operatória de cirurgia\nortopédica com laudo de arritmia sinusal. A conduta\nindicada neste caso é:","options":{"A":"indicar Tilt teste.","B":"realizar ecocardiograma.","C":"liberar para prática de natação.","D":"solicitar novo eletrocardiograma."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-229491","number":"229491","sourceNumber":"229491","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para os pacientes estáveis, com FA (Fibrilação Atrial) persistente, que vão se submeter\nà cardioversão elétrica ou química, recomenda-se a\nACO (Anticoagulante Oral) por pelo menos 3\nsemanas antes e 4 semanas após cardioversão na faixa terapêutica (RNI entre 2 a 3). Somente\nestá ERRADO o item:","options":{"A":"Após 2 semanas, a manutenção da ACO deve ser de acordo com score de risco de CHA2 DS2\nVASC.","B":"O uso de ACO está indicado para os pacientes com flutter atrial nas mesmas considerações que\nna FA.","C":"A dose preferencial de rivaroxabana deve ser de 20 mg/dia, desde que tenham baixo risco de\nsangramento.","D":"A dose preferencial de dabigatrana deve ser de 150 mg 2x/dia, desde que tenham baixo risco de\nsangramento."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-229495","number":"229495","sourceNumber":"229495","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para paciente submetidos à cardioversão elétrica guiada por ECOTE e sem trombos,\nrecomenda-se a HNF EV (bolus seguido de infusão contínua) antes da cardioversão e deve-se\nmantê-la até que a ACO plena seja atingida. Somente devemos indicar como ERRADO:","options":{"A":"Para pacientes com FA que necessitam de cardioversão elétrica de emergência, recomenda-se\na HNF EV (bolus seguido de infusão\nintermitente).","B":"Para paciente submetidos à cardioversão elétrica guiada por ECOTE e sem trombos,\nrecomenda-se a HBPM antes da cardioversão e\ndeve-se mantê-la até que a anticoagulação oral\nplena seja atingida.","C":"Para pacientes com FA que necessitam de cardioversão elétrica de emergência, recomenda-se\ndose plena de HBPM.","D":"Se for identificado trombo, anticoagulação dever ser mantida por 3 semanas."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249464","number":"249464","sourceNumber":"249464","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para que ocorra uma melhoria nas estruturas e nos sistemas de saúde, que é um dos\npontos essenciais no sucesso do atendimento da parada cardiorrespiratória (PCR), sendo\ninadequado apenas:","options":{"A":"Criação de um sistema integrado com treinamento de pessoas.","B":"Auxílio de materiais de emergência.","C":"Transportes para um atendimento unificado.","D":"Disponibilidade de DEA em locais públicos com baixa movimentação de pessoas."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249467","number":"249467","sourceNumber":"249467","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Atualização da Diretriz de Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares\nde Emergência da Sociedade Brasileira de\nCardiologia ? 2019. Listamos abaixo itens referentes à\ncadeia de elos de sobrevivência diferenciadas no contexto de uma parada cardiorrespiratória (PCR)\nintra-hospitalar, determine o item que não pode ser considerado como parte da mesma:","options":{"A":"RCP imediata de alta qualidade.","B":"Rápida desfibrilação.","C":"Suporte básico de Vida.","D":"Cuidados pós-PCR."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249468","number":"249468","sourceNumber":"249468","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Ressuscitação Cardiopulmonar e Cuidados Cardiovasculares inseridos nos Cuidados\npós-PCR, apresenta como importante ponto o item:","options":{"A":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom maior tolerância na variação de\ntemperatura e prevenção de febre.","B":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e prevenção\nde febre.","C":"Ênfase na avaliação neurológica, cumprimento das metas hemodinâmicas e controle térmico,\ncom menor variação de temperatura e sem\nprevenção de febre.","D":"Ênfase na avaliação neurológica, sem o cumprimento das metas hemodinâmicas e controle\ntérmico, com menor variação de temperatura e prevenção de febre."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249471","number":"249471","sourceNumber":"249471","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A adequada abordagem de Ressuscitação Cardiopulmonar e Cuidados\nCardiovasculares com ênfase nos cuidados após o\nretorno à circulação espontânea trouxe\nmelhorias nos resultados, contribuído ao prognóstico dos pacientes. Podemos assim determinar\ncomo adequado que:","options":{"A":"O reconhecimento precoce das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","B":"O reconhecimento tardio das causas desencadeantes, orientando a intervenção para cada\ncenário clínico.","C":"O reconhecimento precoce das causas desencadeantes, desorientando a intervenção para cada\ncenário clínico.","D":"O reconhecimento precoce das causas desencadeantes, não orientando a intervenção para\ncada cenário clínico."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-248912","number":"248912","sourceNumber":"248912","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, não podemos afirmar que:","options":{"A":"as células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo","B":"a reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional","C":"as arritmias cardíacas podem ser classificadas, quanto à repercussão clínica, em estável ou\ninstável","D":"cicatrizes (fibroses) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249477","number":"249477","sourceNumber":"249477","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O algoritmo do protocolo no atendimento de uma PCR é formado pela cadeia de elos\nde sobrevivência diferenciadas, está de acordo com o item:","options":{"A":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de\nreversibilidade do processo inicial que desencadeou o evento.","B":"O protocolo no atendimento de uma PCR segue uma sequência lógica, mas não fundamentada\nde condutas que melhoram as taxas de\nreversibilidade do processo inicial que desencadeou o\nevento.","C":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de\nreversibilidade do processo final que desencadeou o evento.","D":"O protocolo no atendimento de uma PCR segue uma sequência lógica e fundamentada de\ncondutas que melhoram as taxas de reversibilidade do processo inicial que não desencadeou o\nevento."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-247411","number":"247411","sourceNumber":"247411","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 57 anos, sexo masculino, é admitido no pronto-socorro com dor torácica\nem queimação, retroesternal, de início há três\nhoras, de forte intensidade, associada à sudorese e\npalpitações. Ao ser monitorizado, seus sinais vitais revelam PA = 164/98 mmHg, Frequência\nCardíaca (FC) de 172bpm, Frequência Respiratória (FR) de 24 irpm e Saturação de Oxigênio\n(SaO?) em 94%. O ritmo ao monitor é o seguinte: A conduta imediata é:","options":{"A":"cardioversão elétrica sincronizada.","B":"adenosina 6 mg IV.","C":"amiodarona 150mg IV.","D":"metoprolol 5mg IV."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/247411.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-249870","number":"249870","sourceNumber":"249870","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Pediatra recebe no pronto-socorro, trazida pelos bombeiros, uma criança, vítima de\nafogamento, em apneia, porém, com pulso central. Qual é a classificação do afogamento desta\ncriança?","options":{"A":"Grau 2.","B":"Grau 4.","C":"Grau 5.","D":"Grau 6."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-229547","number":"229547","sourceNumber":"229547","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina, 35 anos, sem comorbidades, admitida em leito de terapia intensiva\napós laparotomia exploradora por cisto de ovário\nroto. Após 12 horas de observação clínica,\napresenta dor torácica de forte intensidade, palpitações, associada a dispneia súbita. Nega\nvômitos. Permanece estável hemodinamicamente, sem alterações neurológicas. Realizado\neletrocardiograma abaixo. A conduta MAIS adequada neste caso é:","options":{"A":"amiodarona 300mg em bolus.","B":"amiodarona 150mg em bolus.","C":"metoprolol 25mg via oral.","D":"cardioversão elétrica."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/229547.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-229888","number":"229888","sourceNumber":"229888","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante uma reanimação cardiopulmonar, qual recomendação de massagem cardíaca\ne ventilação, após a obtenção de via aérea\navançada:","options":{"A":"1 ventilação a cada 30 compressões torácicas.","B":"2 ventilações a cada 30 compressões torácicas.","C":"1 ventilação a cada 6 segundos e compressões torácicas contínuas.","D":"1 ventilação a cada 10 segundos e compressões torácicas contínuas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-246606","number":"246606","sourceNumber":"246606","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A atividade física compreende qualquer movimento corporal produzido por músculos\nesqueléticos e que resulta em dispêndio de energia. Assinale, a seguir, uma atividade considerada\nde alta intensidade.","options":{"A":"Movimentar móveis.","B":"Limpar a casa.","C":"Realizar exercícios de alongamento.","D":"Executar trabalho de carpintaria.","E":"Caminhar lentamente."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-210541","number":"210541","sourceNumber":"210541","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Considere: paciente em consulta ambulatorial de Cardiologia, sexo masculino, 63 anos,\nportador de fibrilação atrial crônica, sem antecedentes de hipertensão arterial, diabetes ou doença\ncoronariana, apresenta história de ataque isquêmico transitório no ano anterior. Sobre o manejo\nclínico, assinale a afirmativa correta.","options":{"A":"A seleção da terapia antitrombótica independe da forma de apresentação da FA.","B":"O paciente apresenta 2 fatores de risco maiores pelo escore CHA2DS2VASc.","C":"Se portador de prótese mitral mecânica, é recomendada varfarina e manter RNI>2.","D":"Pode ser indicada neste caso a dabigatrana, na dose preferencial de 110mg 2x/dia.","E":"A combinação AAS + clopidogrel pode ser feita, com eficácia similar à da varfarina."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-218214","number":"218214","sourceNumber":"218214","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação ao tratamento da fibrilação atrial aguda, assinale a alternativa correta:","options":{"A":"A cardioversão elétrica não sincronizada está indicada na presença de QT longo.","B":"A administração de amiodarona intravenosa alcança taxas de reversão em torno de 99% em 24\nhoras.","C":"Quanto maior o átrio esquerdo, menor a chance de sucesso na cardioversão elétrica.","D":"O Sotalol por via oral é a droga de escolha para reversão em pacientes com insuficiência\ncardíaca."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-217036","number":"217036","sourceNumber":"217036","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 57 anos, sexo feminino, com queixa de mal-estar súbito há 1 hora, estável\nhemodinamicamente, admitida com o seguinte ECG: no caso apresentado, é recomendado o uso\nde qual fármaco?","options":{"A":"Procainamida.","B":"Adenosina.","C":"Verapamil.","D":"Cardizem.","E":"Digoxina."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/217036.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-202630","number":"202630","sourceNumber":"202630","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A adrenalina quando administrada como terapia na reanimação de parada cardíaca tem\ncomo objetivo promover:","options":{"A":"Vasoconstrição venosa.","B":"Aumento da resistência vascular arterial.","C":"Efeito beta-adrenérgico periférico.","D":"Aumento dos efeitos broncodilatadores."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-202712","number":"202712","sourceNumber":"202712","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Do ponto de vista do ciclo cardíaco,","options":{"A":"o componente tricuspídeo (T1) da primeira bulha ocorre antes do componente mitral (M1), pois a\npressão diastólica final do átrio direito é menor que a do átrio esquerdo.","B":"o componente aórtico (A2) da segunda bulha ocorre antes do componente pulmonar (P2), pois a\npressão gerada pela contração do ventrículo esquerdo é maior que a gerada pelo ventrículo direito.","C":"o desdobramento fisiológico da segunda bulha ocorre durante a expiração.","D":"o bloqueio de ramo direito é o responsável pelo desdobramento paradoxal da segunda bulha."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-201700","number":"201700","sourceNumber":"201700","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em pacientes idosos com fibrilação atrial paroxística, a melhor e mais segura maneira\nde reduzir a recorrência de AVC é:","options":{"A":"Aspirina, 325 mg ao dia.","B":"Aspirina, 325 mg ao dia, e clopidogrel, 75 mg ao dia.","C":"Apixabana.","D":"Warfarin."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-202643","number":"202643","sourceNumber":"202643","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O escore CHADS? é utilizado na avaliação da necessidade de anticoagulação nos\npacientes com fibrilação atrial de etiologia não valvular. Um paciente do sexo masculino, de 76\nanos, com fibrilação atrial, hipertenso crônico adequadamente tratado, obeso, antecedente de\ninfarto agudo sem disfunção sistólica de VE e sem outras comorbidades, apresenta qual valor no\nescore CHADS??","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-205562","number":"205562","sourceNumber":"205562","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um menino de um ano é levado ao pronto-socorro para ser avaliado por inapetência,\nagitação e sudorese. Na impressão inicial, ele\nse mostra letárgico, mas consegue despertar, tem\ndificuldade para respirar e apresenta-se cianótico. A primeira avaliação releva frequência\nrespiratória de 68 irpm, frequência cardíaca de 300 bpm que não varia com atividade ou sono,\npressão arterial de 70 x 45 mmHg, pulso braquial fraco e pulso radial ausente, enchimento capilar\nde 6 segundos, SatO2 de 85% em ar ambiente e ruídos respiratórios bilaterais bons. Você\nadministra oxigênio de alto fluxo e coloca a criança no monitor cardíaco. Não há histórico de\ndoença cardíaca congênita. Você observa o seguinte ritmo com pouca variabilidade da frequência\ncardíaca entre batimentos: o acesso EV foi estabelecido. Qual das seguintes terapias é a mais\nadequada para esta criança?","options":{"A":"Marcar uma consulta com o cardiologista pediátrico para o fim da semana.","B":"Infusão rápida de adenosina 0,1 mg/Kg EV; se a adenosina não estiver disponível\nimediatamente, realizar cardioversão sincronizada.","C":"Realizar desfibrilação imediata sem esperar por acesso IV.","D":"Estabelecer acesso IV e administrar um bolus de 20 ml/Kg de fluido cristalóide isotônico."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/205562.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-215454","number":"215454","sourceNumber":"215454","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"São fatores que podem precipitar o evento sincopal em crianças, EXCETO","options":{"A":"hiperextensão do pescoço.","B":"uso abusivo de celular.","C":"emoções.","D":"desidratação."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-217056","number":"217056","sourceNumber":"217056","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Nas Diretrizes de 2010 da American Heart Association (AHA) para Ressuscitação\nCardiopulmonar (RCP) em pediatria, alguns\nalgoritmos foram estabelecidos. Assinale a alternativa\nque não expressa o que foi exposto por tais diretrizes.","options":{"A":"Em se tratando de profissional de saúde no socorro à vítima de PCR, pulso e respiração devem\nser checados concomitantemente.","B":"Se o socorro à vítima de PCR está sendo prestado por um leigo, sozinho, é preferível que o\nmesmo acione o serviço de emergência antes de iniciar a RCP.","C":"Se a vítima encontra-se inconsciente, com respiração irregular e pulso acima de 60\nbatimentos/minuto, o profissional de saúde pode\nrealizar ventilações, sem compressões torácicas,\ndurante 2 minutos, ao fim dos quais deve reavaliar o paciente.","D":"Mesmo na presença de pulso detectável na vítima pediátrica, caso a frequência seja inferior a 60\nbatimentos/minuto, o profissional de saúde deve realizar compressões torácicas.","E":"A proporção de compressões: ventilações na população pediátrica é de 30:2, quando o\nsocorrista está sozinho, e de 15:2, quando há mais de 1 socorrista proficiente."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174400","number":"174400","sourceNumber":"174400","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A desfibrilação e cardioversão elétrica consistem na aplicação de corrente elétrica de\nalta energia para reversão de arritmias cardíacas geradas pelo mecanismo de reentrada. Somente\napresenta dados considerados inadequados a alternativa:","options":{"A":"Na desfibrilação, esta corrente elétrica é aplicada em qualquer momento do ciclo cardíaco,\nenquanto na cardioversão elétrica, esta\ncorrente é sempre sincronizada com os complexos QRS do\neletrocardiograma para que não seja administrada durante o período vulnerável da repolarização\nventricular (onda T), quando pode potencialmente desencadear uma fibrilação ventricular.","B":"Os desfibriladores/cardioversores podem ser classificados de acordo com o modo de operação\nem: a) manuais, no qual o reconhecimento do\nritmo cardíaco e a administração do choque\ndependem do operador; b) semiautomáticos, também,\n\nconhecidos como DEA, nos quais o reconhecimento do ritmo é realizado pelo dispositivo que\ninforma se o choque elétrico é\n\nrecomendado ou não no tratamento do paciente, sendo que a decisão de aplicar o choque continua\nsendo do operador.","C":"Desfibriladores também podem ser classificados em externos e internos. Nos externos, a\ncorrente elétrica é aplicada através da\nsuperfície externa do tórax do paciente por meio de pás\nmanuais ou adesivas, enquanto, nos internos, a corrente elétrica é aplicada por cabos eletrodos\ngeralmente implantados através do sistema venoso.","D":"Na cardioversão a corrente elétrica é aplicada em qualquer momento do ciclo cardíaco, esta\ncorrente é sempre sincronizada para que não seja administrada durante o período refratário da\nrepolarização ventricular (onda T), quando pode potencialmente desencadear uma arritmia."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175381","number":"175381","sourceNumber":"175381","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O átrio direito é a câmara cardíaca que normalmente recebe o sangue venoso\nsistêmico. Nessa câmara, encontra-se a valva de Eustáquio, que se relaciona com:","options":{"A":"veia cava inferior","B":"crista terminalis","C":"veia cava superior","D":"seio coronário","E":"junção átrio ventricular direita"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175387","number":"175387","sourceNumber":"175387","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 54 anos, portador de doença arterial coronariana crônica, apresenta,\napós intensa emoção, dor torácica precordial e\nperda da consciência. Os pulsos periféricos não são\nperceptíveis, e a pressão arterial não foi percebida. O mecanismo provável da parada é:","options":{"A":"assistolia","B":"atividade elétrica sem pulso","C":"taquicardia supraventricular","D":"fibrilação ventricular","E":"fibrilação atrial"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183254","number":"183254","sourceNumber":"183254","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O ECG é um exame simples, barato e não invasivo. Permite uma ideia da condição\ncardíaca do indivíduo e pode eventualmente\nidentificar situações de risco de morte súbita. Dentro\nda Definição do ritmo sinusal, sendo que podem ocorrer modificações de sua morfologia\ndependentes da FC, apenas não podemos considerar como sendo cabível o que se afirma na\nalternativa:","options":{"A":"O Ritmo Sinusal (RS) é um ritmo fisiológico do coração.","B":"Origina-se no átrio direito baixo.","C":"Observado no ECG de superfície pela presença de ondas P positivas nas derivações D1, D2 e\naVF.","D":"O eixo de P pode variar entre -30° e +90°."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-175405","number":"175405","sourceNumber":"175405","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual das afirmações a seguir sobre os efeitos da epinefrina durante a tentativa de\nressuscitação é verdadeira?","options":{"A":"a epinefrina reduz a resistência vascular periférica e diminui a pós-carga miocárdica, de modo\nque as contrações ventriculares são mais\neficazes","B":"a epinefrina melhora a pressão de perfusão da artéria coronária e estimula as contrações\nespontâneas quando há assistolia","C":"a epinefrina é contraindicada na fibrilação ventricular, pois aumenta a irritabilidade\nmiocárdica","D":"a epinefrina reduz o consume de oxigênio miocárdico","E":"nenhuma das respostas acima"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183321","number":"183321","sourceNumber":"183321","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para os paciente que apresentam parada cardíaca antes de receber qualquer\nabordagem, a medida mais importante e de\nmaior impacto seria a difusão global do conhecimento\nsobre atendimento básico da parada cardíaca. Sobre esse assunto, podemos considerar como\nINCORRETO apenas o item:","options":{"A":"O reconhecimento e o tratamento da Fibrilação Ventricular (FV) por profissional da saúde\n(Médico ou Enfermeiro com treinamento em\nACLS, sigla do inglês Advanced Cardiac Life Support)\nsão seguramente excelentes instrumentos para melhorar os resultados pré-hospitalares no IAM,\nmas apenas na possibilidade de ter uma aplicabilidade difusa, por meio de programas de\natendimento de urgência em unidades móveis que estejam equipadas e disponíveis para cobertura\nglobal da população.","B":"A importância da FV como mecanismo de óbito precoce e a habilidade na ressuscitação e na\ndesfibrilação foram os fatores que propiciaram o desenvolvimento de programas de tratamento\npré-hospitalar do IAM.","C":"Estima-se que a desfibrilação salve cerca de duas vezes mais vidas que o tratamento\ntrombolítico, mas depende de sua rápida aplicação ao paciente.","D":"Identificar o perfil dos casos de IAM que não chegam aos hospitais, qualificando o estado atual\nde atendimento e quantificando o impacto de uma nova estratégia de grande difusão na\npopulação.."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-178802","number":"178802","sourceNumber":"178802","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O ECG acima demonstra:","options":{"A":"taquicardia vetricular polimórfica.","B":"taquicardia vetricular monomórfica.","C":"fibrilação ventricular.","D":"taquicardia paroxística supraventricular.","E":"extrassístoles ventriculares."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/178802.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174502","number":"174502","sourceNumber":"174502","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando da opção para tratamento farmacológico, os principais medicamentos utilizados\nem pacientes portadores de fibrilação atrial,\napresentam efeitos adversos. Sobre isso, assinale a\nalternativa que demonstra INCORRETA correlação:","options":{"A":"Propafenona: depressão grave da contratilidade miocárdica, gosto metálico, visão borrada,\nnáusea, diarreia aquosa, tontura, agranulocitose.","B":"Betabloqueadores: bradicardia, broncoespasmo, erupção cutânea, fadiga, depressão mental,\npesadelos.","C":"Amiodarona: pneumonite (1-23%), neuropatia periférica, tremor, insônia e ataxia,\nfotossensibilização (90%), depósitos na córnea,\n\ncom repercussões visuais (3-13%), insuficiência cardíaca, bradicardia, intolerância digestiva,\nhepatite medicamentosa, coloração azulada da pele,\nexacerbação de asma brônquica, alterações\nno metabolismo dos glicídios e triglicerídeos, epididimite, disfunção renal.","D":"Sotalol: torsades de pointes (2,4%), bradicardia, fadiga, astenia, dispneia, tontura (2-4%)."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-178810","number":"178810","sourceNumber":"178810","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação à arritmia encontrada no eletrocardiograma, são condutas possíveis as\nlistadas a seguir, exceto uma. Qual?","options":{"A":"Sulfato de magnésio.","B":"Lidocaína.","C":"Isoproterenol.","D":"Marca-passo provisório com aumento da frequência cardíaca (Overdrive Pacing).","E":"Amiodarona."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/178810.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174405","number":"174405","sourceNumber":"174405","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Podemos obter o controle do ritmo na Fibrilação Atrial por diversas condutas, clínicas\nou intervencionistas. Indique a alternativa que\napresenta conduta INADEQUADA:","options":{"A":"Evidências sólidas indicam que a ablação da Fibrilação Atrial é mais eficaz do que as drogas\nantiarrítmicas para controle do ritmo.","B":"A ablação está indicada como opção para a falência de uma droga antiarrítmica e também como\nprimeira escolha em pacientes selecionados com FA paroxística, sem doença estrutural.","C":"Pacientes com cardiopatia estrutural e FA paroxística igualmente podem ser considerados para\nablação como terapia inicial, desde que se suspeite de taquicardiomiopatia e que o paciente deseje\nrealizar ablação.","D":"A eficácia da ablação da FA não varia conforme as características clínicas da arritmia e a\nextensão da cardiopatia de base."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-173565","number":"173565","sourceNumber":"173565","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 55 anos deu entrada no pronto-socorro e foi diagnosticada uma Parada\nCardiorrespiratória (PCR) por Fibrilação Ventricular (FV). Qual é o melhor momento para iniciar\nepinefrina 1 mg?","options":{"A":"Imediatamente, antes da primeira desfibrilação.","B":"Imediatamente, depois da primeira desfibrilação.","C":"Após reiniciada a Ressuscitação Cardiopulmonar (RCP), depois da segunda desfibrilação.","D":"Durante a RCP e imediatamente antes da segunda desfibrilação."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174468","number":"174468","sourceNumber":"174468","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente apresentando quadro de Fibrilação Atrial solicita sua orientação quanto às\nopções de tratamento disponíveis atualmente,\nseus riscos e benefícios. Dentre as alternativas\nabaixo, existe uma INCORRETA, assinale-a:","options":{"A":"As evidências mais robustas de benefício e os melhores resultados são obtidos nos pacientes\njovens com FA paroxística/persistente sintomática sem cardiopatia estrutural relevante.","B":"Existem evidências de que a intervenção seja superior à dos fármacos AA, no tocante à redução\nde desfechos duros, como mortalidade, IC e\nacidentes vasculares cerebrais.","C":"Nesse perfil de pacientes, a intervenção proporciona melhora significativa da sintomatologia e da\nqualidade de vida.","D":"Porém, faltam dados que comprovem o benefício do procedimento nos pacientes muito idosos,\ncom FA persistente de longa duração, ou IC avançada."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174506","number":"174506","sourceNumber":"174506","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentre os conceitos sobre o tratamento híbrido da Fibrilação Atrial, somente pode ser\nconsiderado INADEQUADO o seguinte conceito ou afirmativa:","options":{"A":"Os chamados ?procedimentos híbridos? combinam cirurgia epicárdica minimamente invasiva\ncom mapeamento eletrofisiológico e ablação por cateter endocárdico.","B":"O objetivo dessa técnica mista é tratar, em especial, pacientes com FA persistente, nos quais\nessas técnicas utilizadas isoladamente teriam resultados insatisfatórios.","C":"O objetivo dessa técnica mista é tratar, em especial, pacientes com FA persistente, nos quais\nessas técnicas utilizadas isoladamente teriam resultados satisfatórios.","D":"No geral, os resultados com os procedimentos híbridos são expressivos, principalmente\nconsiderando a maior complexidade da população tratada."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182497","number":"182497","sourceNumber":"182497","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com relação à fibrilação atrial, assinale a alternativa incorreta:","options":{"A":"devido à ação inotrópica negativa dos betabloqueadores, devem ser evitados nos pacientes com\nfibrilação atrial","B":"hipertireoidismo e intoxicação alcoólica aguda são causas bem definidas de fibrilação atrial","C":"idade >75 anos é um fator de risco para acidente vascular cerebral no paciente portador de\nfibrilação atrial","D":"os bloqueadores dos canais de cálcio verapamil e diltiazem podem ser utilizados para o controle\nda frequência cardíaca nos pacientes com\nfibrilação atrial"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-182494","number":"182494","sourceNumber":"182494","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual das doenças a seguir cursa mais habitualmente com pulso paradoxal?","options":{"A":"estenose aórtica","B":"pericardite constritiva","C":"insuficiência aórtica","D":"estenose mitral"},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-183271","number":"183271","sourceNumber":"183271","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação ao paciente vítima de acidente por\nsubmersão:","options":{"A":"Afogamentos em piscinas têm alto potencial de desenvolver infecção pulmonar precoce.","B":"O diagnóstico de pneumonia muitas vezes é feito de forma equivocada, por exames de\nradiografia solicitados no início do quadro, em decorrência da presença de opacificações que\ncorrespondem à água nos pulmões.","C":"Antes de tomar a decisão de iniciar a antibióticoterapia, recomenda-se observar o paciente\nclinicamente por meio da presença de\n\nfebre, leucocitose, novos infiltrados pulmonares na radiografia e exames de culturas.","D":"Na prática, a origem da água em que ocorreu o acidente, salgada ou doce, não diferencia a\nclínica de edema pulmonar ou os distúrbios eletrolíticos."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-185159","number":"185159","sourceNumber":"185159","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Você atende um paciente que está arresponsivo e sem pulsos. Uma vez iniciadas as\nmanobras de ressuscitação cardiopulmonar (RCP), ao chegar o monitor-desfibrilador bifásico, você\nidentifica o ritmo a seguir. A próxima conduta deve ser:","options":{"A":"desfibrilação a 200 Joules, reiniciar a RCP imediatamente.","B":"RCP por 2 minutos e, então, desfibrilação a 200 Joules.","C":"desfibrilação a 200 Joules, e reavaliar o ritmo em seguida.","D":"manter a RCP e infundir adrenalina 1mg IV."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/185159.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-185123","number":"185123","sourceNumber":"185123","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher de 32 anos é atendida no pronto-socorro com queixa de palpitações\ntaquicárdicas. Tem apresentado episódios\nfrequentes de taquiarritmia que revertem\nespontaneamente e duram aproximadamente 10 minutos. O episódio de hoje iniciou há 30 minutos,\no que a fez procurar atendimento. Ela está lúcida e orientada, sem outras queixas, a PA =\n132/76mmHg, FC 176bpm, saturação de oxigênio 97%. O ECG realizado revela o seguinte ritmo:\nDentre as opções abaixo, a conduta indicada para o caso deve ser?","options":{"A":"administrar atropina IV.","B":"administrar adenosina IV.","C":"realizar cardioversão elétrica sincronizada.","D":"administrar amiodarona IV."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/185123.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174527","number":"174527","sourceNumber":"174527","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 76 anos, pós-operatório imediato de gastrectomia subtotal por\nAdenocarcinoma Gástrico. Apresenta-se com\nPA=80x40mmHg Pulso=161bpm Sat=91%\nFR=27irpm, associado a sudorese, palidez cutânea. Apresentando o seguinte Eletrocardiograma:\nEm relação ao quadro clínico, assinale a alternativa que apresenta a melhor conduta:","options":{"A":"Cardioversão Elétrica.","B":"Amiodarona.","C":"Adenosina.","D":"Lidocaína."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/174527.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-178858","number":"178858","sourceNumber":"178858","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente, 67 anos, chega à Unidade de Emergência referindo que apresentou um\nepisódio de sincope em sua residência, mal-estar geral e sudorese intensa. Na avaliação,\n\nobserva-se que o paciente está com PA =84 x 62 mmHg, dispneia (saturação de oxigênio = 89%) e\nedema em membros inferiores, Com a suspeita de alguma patologia cardiológica, é solicitado um\neletrocardiograma (ECG), do qual se obteve o seguinte traçado. Após análise do traçado e\nmediante os sinais e os sintomas do paciente, assinale a alternativa correta quanto ao ritmo obtido\nno ECG e quanto à conduta mais adequada.","options":{"A":"Ritmo: bloqueio atrioventricular de segundo grau (Mobitz II / Wenckebach). Conduta: iniciar\nmanobra vagal; caso não haja resposta, prosseguir com adenosina 6 mg.","B":"Ritmo: bloqueio atrioventricular de segundo grau (Mobitz I / Wenckebach). Conduta: iniciar\natropina 0,5 mg e titular até no máximo 3 mg\nde 3 a 5 minutos, caso não haja resposta, prosseguir\ncom marcapasso transcutâneo ou dopamina ou epinefrina.","C":"Ritmo: bradicardia sinusal, Conduta: observar e, se necessário, chamar o especialista ou\nencaminhar para uma unidade especializada.","D":"Ritmo: bloqueio atrioventricular de primeiro grau. Conduta: iniciar atropina 0,5 mg e titular\naté no\nmáximo 3 mg de 3 a 5 minutos; caso não haja resposta, prosseguir com adenosina 6 mg e titular\naté no máximo 12 mg.","E":"Ritmo: bloqueio atrioventricular de terceiro grau. Conduta: cardioversão sincronizada iniciando\ncom carga de 50 J e aumentando progressivamente\naté 150 J; caso não haja resposta, prosseguir\ninfusão de dopamina."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/178858.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174426","number":"174426","sourceNumber":"174426","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Estudos epidemiológicos demonstram clara associação entre Fibrilação Atrial e risco de\nmorbimortalidade por diversos fatores. Sobre isso, assinale a alternativa CORRETA:","options":{"A":"Estudos epidemiológicos demonstram clara associação entre Fibrilação Atrial e risco de Acidente\nVascular Cerebral (AVC), isquêmico somente, sem alterar mortalidade.","B":"Alterações cognitivas, Insuficiência Cardíaca (IC) e implicações socioeconômicas também são\nconsequências importantes da FA.","C":"Em estudos clínicos envolvendo pacientes com IC, a FA não foi considerada fator de risco\nindependente para mortalidade.","D":"IC e FA coexistem em uma alta porcentagem de pacientes (22 a 42%). Além disso, o\naparecimento de FA em pacientes portadores de\nIC não está associado à elevação de do risco de\nmorte em comparação com os indivíduos sem o distúrbio do ritmo."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-174517","number":"174517","sourceNumber":"174517","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Muitos fatores de risco clínicos estão associados ao aumento no risco de FA e,\npossivelmente, participam da elevação na prevalência observada nas últimas décadas, somente\nnão podemos considerar completamente correta a alternativa:","options":{"A":"Fatores clínicos predisponentes a FA ocorrem quando anormalidades eletrofisiológicas alteram o\ntecido atrial e promovem formação/propagação anormal do impulso elétrico.","B":"Muitos fatores de risco clínicos clássicos estão associados, tais como hipertensão, diabetes,\ndoença valvar, infarto do miocárdio e Insuficiência Cardíaca (IC).","C":"Podemos observar novos fatores de risco como presença de Apneia Obstrutiva do Sono (AOS),\nobesidade, uso de bebidas alcoólicas, exercício físico, história familiar e fatores genéticos.","D":"Na prática clínica, a influência da obesidade e da AOS parece impactar muito pouco na\nabordagem terapêutica dos pacientes portadores de FA."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157328","number":"157328","sourceNumber":"157328","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre as principais mudanças no ACLS 2015, qual recomendação é INCORRETA?","options":{"A":"Em via aérea avançada, preconizam-se 10 ventilações por minuto (1 ventilação a cada 6\nsegundos).","B":"A vasopressina não é mais utilizada no protocolo ACLS.","C":"Em via aérea avançada, ETCO2 menor que 10 mmHg na capnografia após 10 minutos de\nressuscitação pode ser utilizado para determinar fim dos esforços.","D":"Utilização precoce da adrenalina em pacientes com ritmo não chocável.","E":"Está recomendado o uso de circulação extracorpórea para ressuscitação em pacientes que não\nrespondem à ressuscitação convencional e que possam apresentar algum benefício."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-150265","number":"150265","sourceNumber":"150265","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na semiologia do tórax, qual é o ponto anatômico que serve de referência para a\nidentificação e a contagem dos espaços intercostais, que é importante na ausculta cardíaca (focos\nde ausculta) e na realização de procedimentos invasivos, como toracocentese e drenagem\ntorácica?","options":{"A":"Ângulo esternal.","B":"Linha hemiclavicular.","C":"Linha paraesternal.","D":"Linha axilar."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157433","number":"157433","sourceNumber":"157433","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A desfibrilação é uma aplicação de corrente elétrica de alta energia para reversão de\narritmias cardíacas geradas pelo mecanismo de reentrada. Na desfibrilação, esta corrente elétrica é\naplicada em qualquer momento do ciclo cardíaco, enquanto na cardioversão elétrica esta corrente é\nsempre sincronizada com os complexos QRS do eletrocardiograma para que não seja administrada\ndurante o período vulnerável da repolarização ventricular (onda T), quando pode potencialmente\ndesencadear uma fibrilação ventricular. A desfibrilação está indicada no tratamento da fibrilação\nventricular e na taquicardia ventricular sem pulso, ambas em situações compatíveis com parada\ncardiorrespiratória. Este procedimento também está indicado para reversão de taquicardia\nventricular polimórfica sustentada devido à dificuldade de sincronização com os diferentes\ncomplexos QRS observados nesta arritmia. Em relação à necessidade de adequada classificação\nda arritmia para sua correta indicação, aponte a alternativa que se mostra INADEQUADA na\nclassificação ou uso da desfibrilação.","options":{"A":"Nos desfibriladores externos, a corrente elétrica é aplicada através da superfície externa do\ntórax\ndo paciente por meio de pás manuais ou\nadesivas.","B":"Nos desfibriladores internos, a corrente elétrica é aplicada por cabos eletrodos geralmente\nimplantados através do sistema venoso.","C":"Quanto ao formato da onda, podem ser classificados em monofásicos ou bifásicos. Nos\nmonofásicos, toda a energia elétrica selecionada é aplicada em duplo único sentido vetorial.","D":"Nos desfibriladores bifásicos, parte da corrente é administrada em um sentido e a outra parte, no\nsentido inverso (inversão de polaridade)."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157439","number":"157439","sourceNumber":"157439","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Desfibrilação precoce é o tratamento de escolha para vítimas em Fibrilação Ventricular\nde curta duração, como vítimas que apresentaram\ncolapso súbito, sendo este o principal ritmo de\nparada cardíaca. Podemos alegar, como uma conduta INADEQUADA, uma das opções a seguir.\nAssinale-a.","options":{"A":"Nos desfibriladores externos, o choque elétrico é aplicado por intermédio das pás manuais, as\nquais o operador posiciona sobre o tórax, exercendo pressão de aproximadamente 13 kg.","B":"Deve-se ter o cuidado de colocar gel na interface entre as pás e o tórax, visando diminuir a\nresistência à passagem da corrente elétrica; já as pás adesivas são coladas sobre o tórax do\npaciente, dessa maneira dispensando a utilização do gel e da compressão.","C":"Em relação ao posicionamento das pás manuais e adesivas, o local mais adequado é a posição\nanterolateral, onde uma das pás é colocada na região infraclavicular direita e a outra pá na região\nprecordial.","D":"Posições alternativas, como anteroposterior e laterolateral, podem ser utilizadas em situações\nespeciais, como presença de marca-passo ou\ncardioversor-desfibrilador implantável, no qual as pás\ndevem ser obrigatoriamente posicionadas por, pelo menos, 3 cm de distância do gerador."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157448","number":"157448","sourceNumber":"157448","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Ocorre grande importância a tomada de decisão a respeito de terapêutica elétrica,\nsendo que a cardioversão elétrica está indicada para a reversão das taquiarritmias com\ninstabilidade hemodinâmica. Considera-se como critérios de instabilidade a presença de pelo\nmenos um dos critérios seguintes, EXCETO por:","options":{"A":"Hipotensão mesmo sem sinais de choque circulatório.","B":"Dor torácica anginosa.","C":"Dispneia associada à congestão pulmonar.","D":"Rebaixamento do nível de consciência."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157455","number":"157455","sourceNumber":"157455","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A estimulação cardíaca temporária, através do Marca-Passo Transcutâneo (MPTC), é\num procedimento de emergência que tem a vantagem de ser uma técnica não invasiva e de\ninstalação praticamente imediata. O MPTC é um dispositivo que pode estimular o ritmo cardíaco\npelo fornecimento de corrente elétrica por eletrodos colados na pele. Há despolarização elétrica,\nque levará à contração cardíaca. Dentre as suas indicações e características, DESCONSIDERE,\napenas, o contido em uma das alternativas. Assinale-a.","options":{"A":"A principal indicação de seu uso é em pacientes com bradicardia sintomática.","B":"A vantagem do MPTC é a necessidade de baixa energia em razão da necessidade de fazer a\nenergia aplicada chegar ao miocárdio.","C":"Pode também ser utilizado na superestimação para supressão de taquicardias refratárias com o\nintuito de eliminar taquicardia supraventricular (TSV) e taquicardias ventriculares (TV) malignas.","D":"O aumento das placas de eletrodos para oito ou dez centímetros de diâmetro minimizam a\ndensidade de corrente elétrica, além da melhor condução."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157460","number":"157460","sourceNumber":"157460","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O Marca-Passo Transcutâneo (MPTC), é um procedimento de emergência que tem a\nvantagem de ser uma técnica não invasiva e de instalação praticamente imediata. Mas, como por\ndefinição, é utilizado através da parede torácica, apresentando diversas interferências em seu uso\ne indicação, NÃO sendo uma delas o contido em uma das opções. Aponte-a.","options":{"A":"A impedância transtorácica consiste na resistência da parede torácica ao fluxo da corrente\nelétrica e pode também ser influenciada pelo tamanho dos eletrodos.","B":"O aumento das placas de eletrodos para oito ou dez centímetros de diâmetro minimizam a\ndensidade de corrente elétrica, além da melhor condução.","C":"Pode também ser utilizado na superestimulação para supressão de taquicardias refratárias.","D":"O MPTC é um dispositivo que, em geral, não causa desconforto e dor ao paciente, visto que\ncorrentes elétricas de 50 a 100 miliampéres (mA) são necessárias."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-160550","number":"160550","sourceNumber":"160550","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 52 anos é admitido com história de náuseas, vômitos e desconforto torácico.\nA triagem encaminha o paciente rapidamente para\na sala de emergência para monitorização, pois\ndetectou FC = 160 bpm e PA = 80/50 mmHg. O ECG realizado é mostrado a seguir (conforme\nimagem do caderno de questões). A conduta imediata mais apropriada é:","options":{"A":"Realizar cardioversão elétrica sincronizada com 100 joules.","B":"Realizar desfibrilação com 200 joules.","C":"Prescrever amiodarona endovenosa.","D":"Prescrever diltiazem endovenoso."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157464","number":"157464","sourceNumber":"157464","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante o seu último plantão, ocorreu um caso de parada cardíaca que não se\nconseguia acesso a drogas, e um membro da equipe pediu para deixar de realizar a RCP por\nalguns instantes para se obter uma via central. Entretanto, podemos considerar que durante a\nparada cardíaca, a prioridade sempre será administrar RCP de boa qualidade e desfibrilação\nimediata; a administração de drogas será secundária. Depois da tentativa de desfibrilação, os\nsocorristas devem estabelecer um acesso para a medicação. A respeito disso, assinale a\nalternativa INCORRETA:","options":{"A":"Deve-se escolher, de preferência, o acesso venoso periférico nos membros superiores (veia\nantecubital). O acesso periférico é de fácil obtenção, fácil aprendizado, apresenta menor risco de\ncomplicações e não necessita de interrupção das manobras de RCP.","B":"Se não for possível estabelecer acesso IV, a via intraóssea (IO), para administração de drogas,\npode proporcionar concentrações plasmáticas\nadequadas, similares às alcançadas pelo acesso\nintravenoso.","C":"A administração de medicamentos por um acesso central pode ser considerada se não houver\nnenhuma contraindicação. Essa via de administração\nde medicamentos oferece a vantagem de\nviabilizar maior concentração plasmática apesar de um maior tempo para circulação, além de\npermitir a determinação da saturação venosa central e estimar a pressão de perfusão coronariana\ndurante a RCP.","D":"Estudos relatam que drogas como lidocaína, adrenalina, atropina e naloxone podem ser\nabsorvidas por via endotraqueal. A\nadministração dessas drogas pela via endotraqueal, durante a\nRCP, resulta em menores concentrações plasmáticas quando comparadas com as mesmas doses\nadministradas por via IV."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157454","number":"157454","sourceNumber":"157454","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Das condutas frente à parada cardíaca, as intervenções medicamentosas têm sido\nindicadas no manuseio da PCR desde longa\ndata, porém ocorrem muitas controvérsias, e\ndificuldades de indicações mudam constantemente, sendo o uso de Bicarbonato de Sódio uma das\ncondutas mais controversas, mas podemos admitir:","options":{"A":"Que o melhor tratamento da acidose na PCR é a compressão torácica adequada, além disso,\nnão ocorre benefício ganho com a ventilação.","B":"Que o uso de bicarbonato pode ter alguns efeitos benéficos, tais como aumento na geração de\nCO2.","C":"Bicarbonato de sódio exacerbando a acidose intracelular; efeito inotrópico negativo no miocárdio\nisquêmico.","D":"Bicarbonato de sódio, aumento da osmolaridade sérica e desvio da curva de dissociação da\nhemoglobina para a direita."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149168","number":"149168","sourceNumber":"149168","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Idosa, 67 anos de idade, foi trazida por familiares ao hospital, desacordada. Logo na\nsua chegada, o caso foi reconhecido como de\nparada cardíaca, provavelmente decorrente de\nataque cardíaco em que ela se queixou de fortes dores no tórax logo quando iniciou o mal-estar,\nantes que perdesse a consciência. Foi iniciado manobras, com uso do CAB, dando grande ênfase\nnas compressões torácicas que foram vigorosas, com profundidade, a uma frequência, em média,\nde 145 por minuto. Sobre essa situação clínica, pode-se afirmar que:","options":{"A":"Essa frequência foi abaixo do necessário.","B":"A conduta foi inadequada, por comprometer a profundidade das compressões.","C":"Melhora fortemente as chances de se obter sucesso na RCP conforme o protocolo atual de\nfrequência.","D":"Somente foi possível graças ao grande treinamento técnico da equipe, que se atualizou sobre o\ntratamento adequado a PCR."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157458","number":"157458","sourceNumber":"157458","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Das medicações utilizadas em emergência, a atropina foi uma das que mais perdeu\nindicações e apresenta controvérsias. A respeito dela, marque a opção considerada INCORRETA:","options":{"A":"A atropina é agonista da ação da acetilcolina, um neurotransmissor parassimpático nos\nreceptores muscarínicos.","B":"Atropina bloqueia o efeito do nervo vago, tanto no nó sinoatrial (NSA) como no nó\natrioventricular (NAV).","C":"Atropina aumenta a frequência de disparos do nó SA.","D":"Atropina facilitando a condução atrioventricular."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149173","number":"149173","sourceNumber":"149173","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Podemos considerar como boas práticas, durante as manobras de reanimação\ncardiorrespiratória, diversos itens como, por\nexemplo, frequência respiratória e massagem cardíaca,\ncom EXCEÇÃO do contido em uma das opções a seguir. Assinale-o.","options":{"A":"Permitir o retorno do tórax à sua posição sempre.","B":"Comprimir o tórax minimamente 6 cm.","C":"Realizar a compressão entre 100 e 120 por minuto.","D":"Minimizar as interrupções torácicas."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157379","number":"157379","sourceNumber":"157379","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente, sabidamente cardiopata, foi ao hospital trazido por familiares, que o\nconsideraram prostado nesta manhã. Foi deixado\nna sala de emergência e monitorizado, seu\neletrocardiograma demonstrava uma baixa frequência cardíaca. Foi, então, solicitado avaliação da\ncardiologia e o colega o solicitou para discutir e decidir sobre as condutas, inadequadamente\nfundamentada na seguinte alternativa. Indique-a.","options":{"A":"Os sinais e sintomas, mesmo leves, e os pacientes assintomáticos necessitam de tratamento.\n\nOs pacientes devem ser monitorados à procura dos sinais de deterioração das condições. Deve-se\nfornecer terapia imediata antes que os\npacientes\n\ntenham hipotensão, convulsões e outros sinais de choque relacionados à bradicardia.","B":"A bradicardia é definida como uma frequência cardíaca inferior a 60 bpm; quando a bradicardia é\na causa de sintomas, a frequência geralmente\né menor que 50 bpm. Este limite é individual e\nfrequências menores do que essas podem ser\n\nconsideradas fisiológicas para alguns pacientes e inadequadas para outros.","C":"As causas podem ser: não cardíacas, como uso de drogas; causas metabólicas ou endócrinas,\nespecialmente na tireoide; distúrbio eletrolítico, fatores neurológicos e reflexos autonômicos;\nfatores\nsituacionais, como o repouso prolongado no leito; e autoimunidade. As causas de origem cardíaca\nincluem a doença cardíaca isquêmica aguda ou crônica, doença cardíaca vascular, doença\ncardíaca valvular, ou doença degenerativa primária elétrica.","D":"Os pacientes assintomáticos não devem receber nenhum tratamento. O tratamento é indicado\nsomente nos casos em que a bradicardia, independente do seu tipo ou causa, provoca uma\nredução significativa da pressão arterial sistêmica com sinais clínicos de baixo débito cardíaco."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149179","number":"149179","sourceNumber":"149179","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante as manobras de reanimação cardiotorácicas, devemos nos atentar a diversos\nfatores, como a frequência das compressões e\na qualidade delas. Além de uma frequência de 100\naté 120 bpm e uma profundidade de 5 a 6 cm, podemos, também, considerar que:","options":{"A":"Se apoiar sobre o tórax, entre as compressões, melhora e promove otimização da pressão\ntorácica.","B":"Aumenta em muito o achado de lesões fatais e promove o apoio do socorrista no tórax entre as\ncompressões.","C":"A pressão intratorácica negativa relativa melhora o fluxo cardiopulmonar.","D":"O retorno intratorácico parcial não causa mudança de fluxo circulatório."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157392","number":"157392","sourceNumber":"157392","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As arritmias cardíacas apresentam importante conhecimento médico, sendo que\napenas uma das alternativas abaixo se apresenta\ncomo ADEQUADA para o correto entendimento\ndo Bloqueio Atrioventricular de primeiro grau. Assinale-a.","options":{"A":"Caracteriza-se pela aceleração na chegada do estímulo aos ventrículos. A relação\natrioventricular permanece 1:1, uma onda P para um\ncomplexo QRS. O intervalo PR é fixo, mas\nnão varia, medindo mais de 0,20 segundos, ou 200 milissegundos.","B":"A maioria localiza-se no nó sinusal e casionalmente nos átrios, raramente sendo infranodal.","C":"As síndromes coronárias agudas envolvendo a artéria coronária direita podem afetar a\ncirculação para o nó AV, levando à isquemia do nó AV e retardando a condução.","D":"Agentes que atuam no NAV, como betabloqueadores, digitálicos, bloqueadores dos canais de\ncálcio e outros, podem acelerar o intervalo PR."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157416","number":"157416","sourceNumber":"157416","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Do ponto de vista eletrocardiográfico, os Bloqueios Atrioventriculares (BAV) podem ser\ndivididos de acordo com a gravidade. Referente aos chamados BAV do segundo grau, aponte a\nalternativa INCORRETA:","options":{"A":"No BAV de segundo grau, ocorre a interrupção na condução do estímulo para os ventrículos,\nalterando a relação P: QRS usual, que é de\n1:1.","B":"Bloqueio atrioventricular de segundo grau tipo I ? Mobitz I ou Wenckebach\nEletrocardiograficamente, caracteriza-se pelo\naumento progressivo do intervalo PR, acarretando em\numa onda P ?bloqueada?, ou isolada, gerando uma pausa no traçado. Sua totalidade se origina na\nregião infranodal.","C":"No ECG, surgem ondas P isoladas, ditas \"bloqueadas?, porque aparecem isoladas, sem o\ncomplexo QRS correspondente.","D":"O digital, por sua ação vago mimética e sua ação indireta no nó AV, também pode causar esse\ntipo de alteração. É necessária a atenção para a associação desses fármacos, principalmente nos\npacientes idosos, em função da ação sinérgica sobre o nó atrioventricular."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149204","number":"149204","sourceNumber":"149204","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Diversos são os fatores listados como adequados ou mesmo prejudiciais às condutas\nde reanimação cardiorrespiratória. Assim, podemos\nadequar as nossas condutas ao melhor\npossível em termos de sobrevivência da vítima. Dentre as afirmações a seguir, indique aquela que\nNÃO se enquadra nesse conceito.","options":{"A":"Apresenta grande importância o achado de lesões fatais, ocorridas quando da profundidade de\nmassagem cardíaca acima de 6 cm.","B":"Manter uma frequência de compressões torácicas adequadas aumenta o percentual de\nmassagem efetivamente eficiente.","C":"Permitir fluxo sanguíneo torácico com a massagem cardíaca adequada melhora as chances de\nsucesso.","D":"Hiperventilação se mostra prejudicial durante as manobras de reanimação."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157426","number":"157426","sourceNumber":"157426","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre os estudos eletrocardiográficos do dito bloqueio atrioventricular de segundo grau\ntipo I ? Mobitz I ou Wenckebach, marque a alternativa CORRETA:","options":{"A":"Eletrocardiograficamente, caracteriza-se pelo aumento fixo do intervalo PR, acarretando em uma\nonda P ?bloqueada?, ou isolada, gerando\numa pausa no traçado. Em torno de 85 a 90% desses\nbloqueios localizam-se no nó AV, sendo o restante infranodal.","B":"Ocorrem nas situações em que há redução importante do tônus vagal, como no atleta\n\nbem-condicionado, nas crianças e durante o repouso. Nestes casos, observa-se desaparecimento\ndo bloqueio durante o exercício, quando o tônus\nsimpático é aumentado e o vagal é diminuído.","C":"Os fármacos que atuam no NAV como os betabloqueadores, os bloqueadores dos canais de\ncálcio, os agentes da classe III, como a amiodarona, e os da classe IC, como a propafenona,\nreduzem a velocidade de condução do NAV, causando BAV do segundo grau tipo I.","D":"A pausa caracteriza-se por ser menor que dois ciclos básicos menores, e o PR pós-pausa é\nsempre igual ou menor que o intervalo PR do início de cada sequência. Sequências variadas\npodem ocorrer como 3:2, 4:3, 5:4, significando que há sempre um complexo QRS a menos, uma\nvez que sempre existe uma onda P bloqueada, sem o QRS correspondente."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149210","number":"149210","sourceNumber":"149210","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando avaliamos o tratamento de taquiarritmias, diversos fatores inerentes às\nalternativas medicamentosas, bem como ao caso clínico,\ndevem ser consideradas quanto à tomada\nda decisão. Dessa maneira, podemos considerar como fatores importantes nesse contexto,\nespecificamente da Fibrilação Atrial, os listados abaixo, com EXCEÇÃO:","options":{"A":"Da apneia obstrutiva do sono.","B":"Da obesidade.","C":"Do uso de bebidas alcoólicas.","D":"Do uso de anti-inflamatórios."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157442","number":"157442","sourceNumber":"157442","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante o último plantão de interno no hospital, você foi chamado em caráter de\nemergência na sala de recuperação anestésica, por complicação cardíaca no pós-operatório\nimediato de cardiopata que fez laparotomia exploradora de emergência. Tanto o monitor cardíaco\nquanto o ECG demonstrava um padrão de bloqueio do segundo grau avançado. Sobre o caso,\naponte a alternativa que é considerada INADEQUADA:","options":{"A":"O BAV avançado do segundo grau é classificado como do tipo 2:1 e 3:1 etc., ou seja, para cada\ncomplexo QRS, existem duas ou três ondas P, respectivamente. Isso significa que não há\nintervalos PR consecutivos para serem comparados, ou seja, não é possível avaliar se o intervalo\nPR mantém-se constante ou prolonga-se antes de surgir a onda P bloqueada.","B":"Cerca de dois terços dos BAV avançados são localizados abaixo do NAV, no sistema\n\nHis-Purkinje, de onde talvez se origine a concepção equivocada de classificá-los como BAV tipo II.","C":"Nos casos em que está associado a complexos QRS finos, que são a maioria, está localizado no\nsistema His-Purkinje.","D":"O BAV avançado pode ser assintomático ou sintomático, apresentando-se sob a forma de\ntontura, pré-síncope ou mesmo episódios sincopais\nintermitentes. Em geral, é secundário à lesão\nanatômica bem-definida do sistema de condução, como na cardiopatia isquêmica."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149221","number":"149221","sourceNumber":"149221","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Além de aspectos cardiológicos com importantes complicações, a Fibrilação Atrial\ncausa enormes outras complicações à distância,\nentre elas os fenômenos emboligênicos. Sobre\nisso, concluímos que:","options":{"A":"O escore de risco para hemorragia não contraindica o uso de anticoagulante oral, mas orienta\nquanto à necessidade de cuidados especiais para tornar o tratamento mais seguro.","B":"Não ocorre risco de interação de anticoagulação e consumo de álcool.","C":"Não há necessidade de avaliar, concomitantemente, risco emboligênico e de sangramento.","D":"O conceito ?benefício líquido? não leva em consideração os aspectos positivos da redução de\nrisco de tromboembolismo bem como de hemorragia."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157446","number":"157446","sourceNumber":"157446","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre as bradiarritimias, assinale a alternativa CORRETA:","options":{"A":"Todo BAVT significa dissociação atrioventricular, mas nem toda dissociação AV significa BAVT.","B":"Nos casos de BAVT, a frequência atrial é sempre menor que a ventricular.","C":"A frequência atrial pode ser somente o de ritmo sinusal, no achado de bloqueio atrioventricular\ntotal.","D":"Na ECG, observam-se ondas P bloqueadas, dissociadas do complexo QRS, que pode ser\nsomente alargado com padrão de bloqueio de ramo."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149232","number":"149232","sourceNumber":"149232","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando avaliamos o tratamento da Fibrilação Atrial, devemos considerar, quanto ao\ntratamento proposto, o seguinte, com EXCEÇÃO de uma das alternativas a seguir. Indique-a.","options":{"A":"O uso de carvedilol associado à digoxina não auxiliou no controle da frequência, bem como na\nmelhora da função ventricular de pacientes portadores de IC.","B":"Os bloqueadores de canais de cálcio não diidropiridínicos, como o verapamil e o diltiazem,\nbloqueiam os canais de cálcio do tipo L do\nsistema de condução cardíaco, principalmente no nó\nAV.","C":"O verapamil e o diltiazem podem ser utilizados em associação com outro fármaco (digital, por\nexemplo), podendo permitir doses menores com consequente melhor tolerância.","D":"O uso intravenoso de esmolol, propranolol e metoprolol foi efetivo em casos de FA aguda."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157452","number":"157452","sourceNumber":"157452","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em termos de conduta de emergência, no caso do encontro das taquiarritmias, assinale\na alternativa INCORRETA:","options":{"A":"Pode-se, de um ponto de vista prático, classificar inicialmente as taquicardias em dois grupos,\nindependente do diagnóstico eletrocardiográfico: instáveis e estáveis.","B":"As taquiarritmias instáveis são aquelas que apresentam frequência cardíaca geralmente superior\na 150 bpm (caso não haja disfunção\nventricular acentuada).","C":"Independente do diagnóstico eletrocardiográfico, a cardioversão elétrica sincronizada deve ser\nprontamente instituída de modo a restaurar um ritmo cardíaco organizado e com frequência menor\ncapaz de produzir débito cardíaco mais efetivo.","D":"Do ponto de vista de atendimento emergencial, podemos dividi-las em dois tipos, de acordo com\na duração do complexo QRS: QRS estreito (< 140\nms) e QRS largo (=140 ms)."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157466","number":"157466","sourceNumber":"157466","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O Bloqueio Atrioventricular Total adquirido no nosso meio é mais comumente causado\npor cardiopatia chagásica, além de doença\nisquêmica, cardiopatia dilatada, pós-cirurgia cardíaca,\ncausa degenerativa, entre outros. O nível do bloqueio é baixo, frequentemente infranodal, e o foco\nde escape, às vezes, fornece frequência muito baixa, como 15 a 20 bpm, configurando quadro de\nemergência, NÃO relacionado a uma das opções apresentadas a seguir. Indique-a.","options":{"A":"A sintomatologia vai depender da frequência ventricular. Com a interrupção do fluxo sanguíneo\npara o cérebro, o indivíduo pode apresentar\ntontura, vertigem, pré-síncope e síncope.","B":"A síncope do BAVT é conhecida como ataque de Stokes-Adams, em homenagem aos dois\ncientistas que a descreveram. A síncope\ncardiológica provoca a perda total dos sentidos por curto\nperíodo de tempo, sem aviso prévio, acarretando, frequentemente, lesão corporal, e o paciente\nrecupera-se imediatamente, sem ter noção do que aconteceu.","C":"Podem ser assintomáticos. Com frequência, o BAVT congênito só causa repercussão clínica na\nadolescência ou no adulto jovem.","D":"Os estímulos gerados na região supraventricular não são todos bloqueados, causando uma\ndissociação atrioventricular parcial de modo que os átrios tenham sua frequência própria, sendo\nsinusal ou não."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157471","number":"157471","sourceNumber":"157471","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Você foi chamado a explicar a um amigo de outra especialidade o porquê de o paciente\ndele ser considerado como de alto risco para\na cirurgia e, assim, indicado pós-operatório de UTI.\nIsso ocorreu devido a um lado de ECG que indicou internação imediata não para a cirurgia, e sim\npara a cardiologia. No laudo, estava escrito Bloqueio Atrioventricular Total (BAVT). A respeito\ndessa\nsituação, aponte a alternativa considerada INADEQUADA:","options":{"A":"O BAVT ou BAV de terceiro grau é a interrupção completa do estímulo de condução para os\nventrículos. Os estímulos gerados na região supraventricular são todos bloqueados, causando uma\ndissociação atrioventricular completa de modo que os átrios tenham sua frequência própria, sendo\nsinusal ou não, e completamente independente da frequência ventricular.","B":"Quando os ventrículos ficam privados de sua fonte estimuladora, tornam-se dependentes de\noutro grupo de células, que assume a função\nde marca-passo, sendo chamado de foco de escape.\nA frequência ventricular é completamente dissociada da atrial e depende exclusivamente da\ncapacidade cronotrópica do foco de escape.","C":"À medida que se aproximam do nó sinusal em direção aos ventrículos, as células especializadas\napresentam frequências de despolarização cada vez menores.","D":"As células do sistema His-Purkinje, como o próprio feixe, têm frequência em torno de 35 bpm, e\nos ramos do feixe de His, de 25 a 30 bpm.\nLogo, quanto mais baixo for o bloqueio, menos confiável\ne mais instável será o foco de escape, além de apresentar frequências baixas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157474","number":"157474","sourceNumber":"157474","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Recentemente um tio de seu colega de clube apresentou uma palpitação e teve muito\nmal-estar. Como você era o único médico que ele conhecia, pediu para convencer o tio de que\ndevia ir a um cardiologista. Sobre esse caso, você o orientou ADEQUADAMENTE, conforme uma\ndas alternativas apresentadas. Assinale-a.","options":{"A":"A menos que disfunção ventricular importante esteja presente, é consenso entre os especialistas\nque somente ritmos acima de 120 batimentos por\nminuto causam sintomas de comprometimento\nhemodinâmico.","B":"Nos pacientes sintomáticos, há que se estabelecerem dois aspectos fundamentais. O primeiro\ndiz respeito à intensidade dos sintomas. Assim,\npacientes sintomáticos podem apresentar sintomas\ndesconfortáveis, como palpitações, tontura e/ou dispneia leve, mas não apresentar qualquer sinal\nclínico de comprometimento hemodinâmico.","C":"Um aspecto fundamental é o estabelecimento de uma relação causal entre a presença das\ntaquiarritmias e os sintomas. Em que pese o fato de existir comprometimento hemodinâmico que\nnecessite de tratamento imediato, sempre é possível estabelecer uma relação direta para o\ntratamento.","D":"Em indivíduos assintomáticos, uma ampla gama de taquiarritmias pode ser identificada e sempre\nvão necessitar de tratamento específico\nimediato, já que não determinam alterações clínicas, mas\npodem degenerar."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149261","number":"149261","sourceNumber":"149261","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O exame de eletrocardiograma pode ser capaz de determinar suspeitas e diagnósticos\nde diversas doenças, tanto cardíacas como à\ndistância, NÃO sendo listado, entre estas capazes de\nalterar o ECG:","options":{"A":"Hipotermia.","B":"Hipertensão intracraniana.","C":"Glaucoma.","D":"Obesidade."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157467","number":"157467","sourceNumber":"157467","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As taquicardias de QRS estreito podem, para melhor raciocínio terapêutico, também ser\npossível dividi-las de acordo com a dependência do nó AV para seu início e manutenção. Assim,\ntemos as taquicardias em que o circuito da arritmia utiliza o nó, muitas das vezes sendo indicada\nterapêutica farmacológica. Dessa forma, aponte a alternativa INCORRETA:","options":{"A":"Adenosina é uma droga que diminui a condução pelo NAV e que promove vasoconstricção\ncoronária.","B":"Possui meia-vida de menos de 5 a 10 segundos, tendo assim efeito fugaz, porém efetivo no\ntérmino da maioria das taquicardias de QRS estreito.","C":"Efeitos colaterais podem ocorrer em até 60% dos casos.","D":"É importante orientar previamente o paciente que poderá apresentar pressão torácica importante\ncom sensação de ?morte? iminente, porém tais\nefeitos são transitórios."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-157470","number":"157470","sourceNumber":"157470","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A respeito do tratamento de emergência de taquiarritmias, marque a alternativa\nINCORRETA:","options":{"A":"Drogas antiarrítmicas têm potencial pró-arrítmico e causam hipotensão arterial e bradicardias\napós reversão de uma arritmia, quando vários\nantiarrítmicos são utilizados em sequência.","B":"Com exceção da adenosina, não se recomenda a administração sucessiva de várias drogas\nantiarrítmicas sequenciais.","C":"Após a adequada utilização de uma droga até sua dose máxima, se não houver reversão da\narritmia ou comprometimento hemodinâmico, o paciente deve ser considerado como ?instável? e a\ndesfibrilação elétrica deve ser realizada.","D":"Para pacientes com disfunção ventricular sistólica, a amiodarona e a digoxina são as drogas\nmais utilizadas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-149216","number":"149216","sourceNumber":"149216","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Dentre as seguintes complicações do afogamento, assinale a mais CORRETA.","options":{"A":"A pneumonia ocorre em 100% dos casos e necessita de tratamento imediato à chegada do\npaciente na emergência.","B":"O vômito é a complicação mais frequente no período pré-hospitalar.","C":"Nas primeiras 48 horas, a febre e a leucocitose representam infecção.","D":"A lesão pulmonar do afogamento pode ser reduzida com o uso de corticoide iniciado nas\nprimeiras 48 horas."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-141558","number":"141558","sourceNumber":"141558","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"No atendimento de um paciente com assistolia ou atividade elétrica sem pulso, deve-se:","options":{"A":"Realizar desfibrilação cardíaca imediata com carga máxima do desfibrilador.","B":"Checar os cabos, a derivação e o ganho do monitor em caso de assistolia.","C":"Usar atropina no tratamento da parada cardiorrespiratória em atividade elétrica sem pulso.","D":"Utilizar as manobras de ressuscitação cardiopulmonar sem valorizar as causas da parada."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127652","number":"127652","sourceNumber":"127652","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 62 anos dá entrada no serviço de emergências referindo sensação de\npalpitações há uma semana, com piora após realização de esforço físico. Ao exame, apresenta-se\nconsciente, orientado, eupneico, ritmo cardíaco irregular, pressão arterial de 140 x 80 mmHg e\nfrequência cardíaca de 128 bpm. O ritmo cardíaco está ilustrado no ECG abaixo. (VER IMAGEM) A\nconduta a ser tomada é:","options":{"A":"Cardioversão elétrica imediata.","B":"Cardioversão química imediata.","C":"Controle da frequência cardíaca e anticoagulação por 3-4 semanas, seguidos de cardioversão.","D":"Controle da frequência cardíaca seguido de ablação do nó atrioventricular e implante de\nmarca-passo."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/127652.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-136883","number":"136883","sourceNumber":"136883","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Você está atendendo um paciente inconsciente em parada cardiorrespiratória. Assim\nque o monitor fica disponível, o ritmo verificado é o seguinte: (VER IMAGEM) Nesse caso, o\npróximo passo deve ser:","options":{"A":"amiodarona em bolus intravenoso.","B":"cardioversão elétrica sincronizada com carga de 100J.","C":"epinefrina em bolus intravenoso.","D":"desfibrilação com carga bifásica de 200J."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/136883.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-136618","number":"136618","sourceNumber":"136618","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Recentemente houve uma importante atualização de protocolos de manejo das\nemergências cardiovascular, como parada cardíaca. Caso seja necessária a aplicação dessas\nmanobras, podemos considerar ADEQUADO","options":{"A":"Manter uma frequência de massagem cardíaca acima de 120 por minuto.","B":"Verificar o pulso após desfibrilação.","C":"Limitar a profundidade da massagem cardíaca a 6 cm.","D":"Aplicar sempre Amiodarona EV."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-137015","number":"137015","sourceNumber":"137015","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mulher de 82 anos, em acompanhamento regular no ambulatório por hipertensão\narterial, vem para consulta de rotina queixando\npalpitações, ECG com fibrilação atrial e FC entre\n100 e 110 bpm. Nesse caso, a melhor conduta é:","options":{"A":"anticoagulação por via oral e cardioversão elétrica eletiva.","B":"encaminhar ao pronto-socorro para cardioversão elétrica imediata.","C":"controlar a frequência cardíaca, anticoagulação por via oral, e cardioversão elétrica eletiva.","D":"controlar a frequência cardíaca e não anticoagular pelo risco de sangramento."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-136620","number":"136620","sourceNumber":"136620","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante manobras de reanimação cardiorrespiratória, você observou o colega\nsocorrista se esforçando para ventilar o\npaciente com máscara e ambu + Oxigênio, o mais rápido\npossível. Das alternativas apresentadas, aponte aquela contendo a conduta que o colega socorrista\nconseguiu devido ao seu esforço.","options":{"A":"Melhorar o prognóstico do paciente em PCR.","B":"Piorar o retorno venoso.","C":"Melhorar a oxigenação do paciente.","D":"Reduzir o tempo de parada cardíaca."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127367","number":"127367","sourceNumber":"127367","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente apresenta súbito mal-estar de início há algumas horas, embora tenha\nacordado se sentindo bem. Refere ser\ntabagista e hipertenso com controle inadequado por uso\nirregular de betabloqueador que alega lhe causar mal-estar. Durante seu exame físico, é notada\nalteração no ritmo cardíaco e por isso solicitado ECG. Realizado o exame, é notado padrão de QRS\nfino, ritmo irregular e uma FC de 140 bpm. Ocorre, então, uma grande piora do paciente, que\napresenta agora dispneia com queda da SPO2, ausculta pulmonar e edema agudo de pulmão. A\nrespeito do caso e da conduta, indique a alternativa CORRETA.","options":{"A":"Trata-se de parada cardíaca, portanto iniciar CAB.","B":"O diagnóstico é o de Insuficiência Coronariana com TV a seguir, portanto desfibrilar.","C":"Fibrilação Atrial Aguda, portanto fazer Desfibrilação Química com Lidocaína.","D":"Fibrilação Atrial, portanto, como evolui com instabilidade, Cardioversão Elétrica está indicada."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-136640","number":"136640","sourceNumber":"136640","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente foi trazido por resgate sem sinais vitais. Iniciado protocolo CAB. Qual dos\naspectos abaixo é considerado, a fim de evitar perda de efetividade da massagem cardíaca?","options":{"A":"Limitar a frequência de massagem a 120 por minuto.","B":"Limitar a massagem a 5 cm no tórax.","C":"Limitar a troca de quem está fazendo rcp ao menor número de vezes possíveis.","D":"Limitar as vezes que se apoia sobre o tórax no momento do retorno."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127360","number":"127360","sourceNumber":"127360","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Quando das manobras de reanimação, seguindo o protocolo do CAB, a hiperventilação\ncom AMBU pode ocorrer, caso esta ultrapasse a\nfrequência de 10 por minutos. Qual é a POSSÍVEL\nconsequência dessa manobra?","options":{"A":"Melhora com hiperoxia.","B":"Aumento da pressão sistólica.","C":"Dificuldade de retorno venoso.","D":"Piora da hipercapnia."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127254","number":"127254","sourceNumber":"127254","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A principal terapêutica atual para correção de arritmias ventricular, que levam à\nParada Cardíaca, é a Desfibrilação. Qual das alternativas listadas mostra-se INADEQUADA\npara esse caso?","options":{"A":"Checar pulso após aplicar o choque.","B":"Indicar monofásico, caso bifásico não esteja disponível.","C":"Iniciar com maior carga disponível.","D":"Reiniciar o ciclo, quando indicado cada dois minutos"},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127255","number":"127255","sourceNumber":"127255","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Existem diversos achados no ECG que direcionam ao diagnóstico correto. Essa\ncorrelação se mostra INCORRETA no seguinte exemplo. Aponte-o.","options":{"A":"Variação de amplitude na mesma derivação, no caso de derrame pericárdico.","B":"Supra do segmento ST regional na pericardite.","C":"Baixa voltagem no hipotireoidismo.","D":"Alteração de repolarização ventricular, no caso de intoxicação digitálica."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127262","number":"127262","sourceNumber":"127262","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Indique os antiarrítmicos contidos em uma das alternativas, que estão correlacionados\ncom modulação dos canais de sódio para seu efeito:","options":{"A":"Lidocaína e propafenona.","B":"Amiodarona e metoprolol.","C":"Diltiazem e verapamil.","D":"Deslanosídeo e esmolol."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-127264","number":"127264","sourceNumber":"127264","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A correta interpretação do eletrocardiograma se mostra importante para o correto\ndiagnóstico etiológico, ou mesmo para a suspeita\nclínica de diversas síndromes cardíacas e até\nextracardíacas. O achado de variações de amplitude do complexo QRS, no derrame pericárdico, é\nADEQUADAMENTE explicado da seguinte forma. Aponte-a:","options":{"A":"Ectopia do marca passo.","B":"Origem abaixo do nó átrio ventricular.","C":"Proximidade da massa muscular ventricular.","D":"Reentrada nodal."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-136547","number":"136547","sourceNumber":"136547","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Das drogas abaixo, quais podem ser administradas via endotraqueal?","options":{"A":"Naloxone e atropina.","B":"Epinefrina e gluconato de cálcio.","C":"Lidocaína e bicarbonato.","D":"Atropina e gluconato de cálcio."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-111455","number":"111455","sourceNumber":"111455","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Durante a interpretação de um ECG, a onda P está bem evidente. Neste caso, que\narritmia podemos descartar?","options":{"A":"Bloqueio sinoatrial.","B":"Bradicardia sinusal.","C":"Fibrilação atrial.","D":"Taquicardia atrial multifocal.","E":"Taquicardia sinusal."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-112350","number":"112350","sourceNumber":"112350","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Na fibrilação atrial permanente, a estratégia de reversão para ritmo sinusal foi\nabandonada. Nesta situação,","options":{"A":"o risco de fenômenos tromboembólicos é pequeno e dispensa tratamento profilático.","B":"o controle da frequência cardíaca pode ser obtido\ncom utilização de betabloqueadores.","C":"o uso de aspirina impede a ocorrência de um acidente vascular cerebral isquêmico.","D":"o tratamento com estatinas concorre para a redução da morbimortalidade dos pacientes."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-109317","number":"109317","sourceNumber":"109317","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 66 anos apresenta perda súbita de consciência após dar entrada no\npronto-socorro com queixa de dor torácica. Ao exame físico, se apresenta arresponsivo, sem\nrespiração e sem pulso. Pressão arterial inaudível. O traçado eletrocardiográfico no monitor é\n\napresentado na figura a seguir. (VER IMAGEM) Dentro do tratamento ideal para este paciente, qual\ndeve ser o primeiro fármaco a ser utilizado?","options":{"A":"Atropina 1 mg IV.","B":"Amiodarona 300 mg IV.","C":"Epinefrina 1 mg IV.","D":"Bicarbonato de sódio 1 mEq/kg EV."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/109317.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-103731","number":"103731","sourceNumber":"103731","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente feminina de 58 anos, deu entrada no Hospital se queixando de mal estar e\ndiscreto desconforto torácico de início nessa tarde, após discussão familiar. Logo após realização\nde ECG, apresentou síncope e dispneia, logo a seguir seu pulso central desapareceu. Qual das\nafirmativas abaixo pode ser considerada INADEQUADA?","options":{"A":"Primeira atitude é intubar a paciente devido à dispneia.","B":"Dentro da cadeia de sobrevivência, devemos solicitar por socorro.","C":"Iniciado manobras de reanimação, a sequência se dá utilizando ciclo de C-A-B.","D":"Iniciado manobras de reanimação, a sequência se dá utilizando ciclos de 30 massagens e duas\nventilações."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-103741","number":"103741","sourceNumber":"103741","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente deu entrada na sala de emergência sem pulso central, trazido por familiares\nque encontraram o mesmo desacordado no seu quarto.\nIniciado protocolo de parada cardíaca, são\nrealizados massagem cardíaca externa em ritmo de aproximadamente 100 por minuto, a seguir\nduas ventilações, trocando após dois minutos quem realiza a massagem, simultaneamente\nchecando pulso. Prioridade para massagem cardíaca. Dessa descrição, qual dos critérios de\nqualidade da reanimação necessita ser MELHOR explicado?","options":{"A":"O tempo que ocorreu a parada cardíaca.","B":"Apesar da prioridade de realizar a massagem cardíaca externa, a mesma deve obedecer a\nrelação de 30 massagens para duas\n\nventilações; na explicação, dá a impressão de se ter realizado 100 massagens antes de ventilar.","C":"Não é necessária a troca de quem realiza a massagem cardíaca tão rapidamente, a mesma\nocorre somente após 5 minutos.","D":"Não foi avaliado o ritmo que se encontra o paciente em parada cardíaca, não se pode iniciar o\nprotocolo sem essa informação."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-103661","number":"103661","sourceNumber":"103661","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Atualmente, uma das medicações mais utilizadas em emergências cardíacas é a\nAmiodarona. Dentre as alternativas abaixo, qual NÃO podemos considerar adequada?","options":{"A":"Quando utilizada via oral, pode levar semanas para obter efeito.","B":"Não têm atividade em arritmias supraventriculares.","C":"Somente pode ser utilizada em bolus, em arritmias ventriculares sem pulso.","D":"Causa potencialmente deterioração de disfunção tiroidiana."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-103685","number":"103685","sourceNumber":"103685","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente referia dor torácica típica ao dar entrada no hospital e, enquanto aguardava\nseu atendimento para realizar ECG, apresentou\nsíncope, sendo, então, levada à sala de\nemergência. Na avalição inicial da sala de emergência, foi diagnosticado PCR em ritmo de\nfibrilação ventricular, iniciado, então, ciclo de massagem cardíaca. Qual das alternativas de\nconduta\nNÃO se mostra adequada, segundo as atuais normas de abordagem da parada cardíaca?","options":{"A":"Caso a Desfibrilação elétrica não seja efetiva, opção por Amiodarona em dose de 300 mg em\nbolus.","B":"Checar pulso logo após desfibrilação monofásica de 360 J.","C":"Desfibrilação bifásica de 120 J.","D":"Adrenalina a cada 3 minutos."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-86335","number":"86335","sourceNumber":"86335","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um paciente portador de Doença de Chagas foi admitido no pronto-socorro torporoso,\ncom sudorese fria, pele pegajosa e dispneia\nintensa. Ao exame físico se constatou: pressão\narterial 80/50 mmHg, frequência cardíaca 220 bpm. A melhor conduta a ser realizada nesse caso é:","options":{"A":"administração endovenosa de metoprolol em bolus.","B":"cardioversão elétrica sincronizada.","C":"administração endovenosa de estreptoquinase 1500000UI em 40 minutos.","D":"administração endovenosa de amiodarona 900 mg em bomba de infusão continua a 10 ml/hora."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-89995","number":"89995","sourceNumber":"89995","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre arritmias cardíacas, é incorreto afirmar:","options":{"A":"Podem surgir sem doença cardíaca estrutural.","B":"Hipertireoidismo e uso de bebidas alcoólicas são causas.","C":"Pode haver palpitações, dor precordial e/ou dispneia.","D":"ECG não é suficiente para o diagnóstico.","E":"A Síndrome de Wolff-Parkinson-White é uma doença por alteração de condução."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-78125","number":"78125","sourceNumber":"78125","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A perda súbita de consciência na síndrome de Stokes-Adams é devido:","options":{"A":"A espasmos vasculares cerebrais decorrentes de crises hipertensivas.","B":"A acidente vascular cerebral isquêmico por liberação de trombos de cavidades cardíacas.","C":"A baixo fluxo cerebral por presença de estenose valvar aórtica severa.","D":"À diminuição do débito cardíaco por bloqueio atrioventricular total intermitente."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-83819","number":"83819","sourceNumber":"83819","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Faz parte da síndrome de Wolff-Parkinson-White, EXCETO:","options":{"A":"Intervalo PR < 0,12 segundos.","B":"QRS > 0,12 segundos.","C":"Não progressão das ondas R.","D":"Onda delta.","E":"Presença de alterações secundárias da onda T."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-84609","number":"84609","sourceNumber":"84609","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual a melhor conduta, segundo o último consenso da American Heart Association\n2010 e ACLS Advanced Cardiovascular Life\nSupport a ser imediatamente realizada em um paciente\ncom este eletrocardiograma com QRS regular e com os sintomas de pele fria, diaforético, adinamia,\nepisódios de síncope e pressão arterial de 60 x 30? (VER IMAGEM)","options":{"A":"Manobra Vagal.","B":"Adenosina 6 mg.","C":"Desfibrilação com 360 J.","D":"Cardioversão Sincronizada entre 50 - 100 J.","E":"Amiodarona endovenosa 150 mg em soro 100 ml e correr em 10 minutos."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/84609.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-85808","number":"85808","sourceNumber":"85808","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para um paciente com ECG acima , que dá entrada na emergência apresentando sinais\nde instabilidade como nível de consciência\nalterado, hipotensão e choque , está correto iniciar\ntratamento imediato com: (VER IMAGEM)","options":{"A":"cardioversão","B":"amiodarona","C":"atropina","D":"desfibrilação","E":"estreptoquinase"},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/85808.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-85401","number":"85401","sourceNumber":"85401","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Diretrizes da American Heart Association 2010 para RCP (Reanimação\nCardiopulmonar) e ACE (Atendimento\nCardiovascular de Emergência) trouxeram algumas\nmudanças. Essas alterações foram concebidas para simplificar o treinamento do profissional de\nsaúde e continuar enfatizando a necessidade de aplicar a RCP de alta qualidade, o quanto antes,\nem vítimas de PCR. Marque a alternativa CORRETA sobre os principais componentes de SBV\n(Suporte Básico de Vida) para profissionais de saúde.","options":{"A":"A frequência de compreensão deve ser de aproximadamente 100/minuto.","B":"Inicialmente, deve-se empregar o \"ver, ouvir e sentir se há respiração\".","C":"A relação compressão-ventilação, até a colocação da via aérea avançada é de 15:2 quando\nestão presentes dois socorristas profissionais de\nsaúde.","D":"Iniciar RCP após verificação da ausência do pulso por 30 segundos."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61717","number":"61717","sourceNumber":"61717","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em um paciente com síndrome de Wolff-Parkinson-White, durante um episódio de FA,\ndeve-se evitar a administração de:","options":{"A":"lidocaína.","B":"procainamida.","C":"ibutilide.","D":"digital."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61719","number":"61719","sourceNumber":"61719","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Considera-se recomendação classe III para manejo da fibrilação atrial na síndrome de\nWolff-Parkinson-White, EXCETO:","options":{"A":"Digital.","B":"Adenosina.","C":"Verapamil.","D":"Betabloqueador.","E":"Procainamida."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61722","number":"61722","sourceNumber":"61722","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 17 anos, portador de WPW, deu entrada na emergência\nhemodinamicamente estável, com taquicardia, com\nQRS largo irregular e R-R mais curto medindo\n180 ms. Entre as drogas abaixo assinale aquela mais adequada para esta situação.","options":{"A":"Verapamil.","B":"Adenosina.","C":"Esmolol.","D":"Procainamida.","E":"Digital."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-69210","number":"69210","sourceNumber":"69210","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma mulher com 48 anos tem fibrilação atrial com frequência ventricular de 140 bpm.\nEstá levemente tonta, com pressão arterial 77 x 48 mmHg. Dos seguintes passos, qual é o mais\nadequado?","options":{"A":"Digoxina intravenosa.","B":"Cardioversão elétrica.","C":"Iniciar manobras vagais.","D":"Cardizem (diltiazem) intravenoso.","E":"Sotalol intravenoso."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-63670","number":"63670","sourceNumber":"63670","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Você está em um banco pagando a inscrição de um dos concursos de residência\nmédica que irá prestar, quando uma senhora ao\nseu lado tem um colapso. Ela aparenta ter uns 45\nanos de idade e está desacompanhada. Ao chegar junto a ela e chamando-a, a mesma não\nresponde a qualquer chamado. Qual deve ser sua conduta visto tratar-se de uma situação que\nnecessita suporte básico de vida?","options":{"A":"Virar a paciente de lado em posição de espera e chamar o SAMU, checando seu pulso a cada 2\nminutos e monitorar o nível de consciência.","B":"Solicitar ajuda (acionamento do SAMU e localização do DEA). Enquanto o socorro não chega,\nchecar pulso central da paciente por não mais\nque 10 segundos. Se não houver pulso, iniciar as\nmanobras de ressuscitação cardiopulmonar, iniciando pelas compressões torácicas. Lembrar-se\nque o foco no suporte básico é uma RCP eficaz e desfibrilação precoce se choque indicado.","C":"Solicitar ajuda (acionamento do SAMU e localização do DEA). Enquanto o socorro não chega,\nchecar pulso central da paciente por não mais\nque 10 segundos. Se não houver pulso, iniciar as\nmanobras de ressuscitação cardiopulmonar, iniciando pelas manobras de ventilação. Lembrar-se\nque o foco no suporte básico é uma RCP eficaz e desfibrilação precoce se choque indicado.","D":"Solicitar ajuda (acionamento do SAMU e localização do DEA). Enquanto o socorro não chega,\nchecar pulso central da paciente por não mais\nque 5 segundos. Se não houver pulso, iniciar as\nmanobras de ressuscitação cardiopulmonar, iniciando pelas compressões torácicas. Lembrar-se\nque o foco no suporte básico é a chegada de recursos para acesso venoso precoce para\nadministração de adrenalina e intubação orotraqueal."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-63687","number":"63687","sourceNumber":"63687","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Num plantão no pronto-socorro, em seu primeiro dia de residência, chega trazido pelo\nSAMU um paciente de 30 anos, com queixa de palpitação. O paciente nega doenças prévias,\nreferindo apenas estar dormindo mal nos últimos dias por ansiedade, devido a compromissos\nprofissionais. Na avaliação, o paciente está lúcido, orientado, eupneico, ausculta pulmonar normal.\nNa ausculta cardíaca, paciente tem frequência de 170 bpm com bulhas hiperfonéticas e ritmo\nregular. PA 120/80 mmHg. Ao realizar um ECG, você percebe frequência de 170 bpm, RR regular,\nausência de onda P, QRS estreito (< 0,12 segundos). Você monitoriza, solicita acesso venoso e\ncolocação de cateter de O2. Em seguida, realiza manobra vagal sem sucesso. Qual seria a melhor\nconduta no atendimento sequencial do caso e qual a hipótese diagnóstica mais provável?","options":{"A":"Sedação com propofol e analgesia com fentanil. Realização de cardioversão sincronizada, pois\ntrata-se de uma fibrilação atrial com sinais de instabilidade hemodinâmica.","B":"Sedação com midazolam e analgesia com fentanil. Realização de cardioversão não sincronizada\ncom 100 J, pois trata-se de uma fibrilação\natrial com sinais de instabilidade hemodinâmica.","C":"Administração EV em bolus de 6 mg de adenosina avisando para o paciente que ele terá uma\nsensação tensitória de mal-estar. Trata-se de\num caso de taquicardia paroxística supraventricular\npor provável reentrada nodal. Betabloqueador ou bloqueador do canal de cálcio são outras opções\npossíveis no caso.","D":"Administração EV em bolus de 6 mg de adenosina avisando para o paciente que ele terá uma\nsensação transitória de mal-estar. Trata-se de\num caso de taquicardia paroxística supraventricular\npor provável reentrada nodal. Betabloqueador ou bloqueador do canal de cálcio são drogas\nproscritas e aumentam a mortalidade em casos como esse."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61790","number":"61790","sourceNumber":"61790","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Reconheça o ritmo do traçado eletrocardiográfico e conduta terapêutica (VER\nIMAGEM):","options":{"A":"Taquicardia sinusal, pesquisar causas.","B":"Taquicardia sinusal, amiodarona 5 mg/kg.","C":"Taquicardia supraventricular, adenosina 0,1 mg/kg.","D":"Taquicardia ventricular, cardioversão sincronizada 0,5-1 J/kg.","E":"Taquicardia ventricular, desfibrilação 2 J/kg."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/61790.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-63480","number":"63480","sourceNumber":"63480","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente, 45 anos, masculino, com quadro de palpitação há 20 minutos chega ao\npronto-socorro e ao exame físico apresenta\nsudorese fria, pele pegajosa, desconforto torácico\nopressivo com irradiação para ombro esquerdo. PA = 90 x 50 mmHg e FC = 182 bpm, QRS menor\ndo que 0,12 segundos; irregular. Qual a melhor conduta, de acordo com o guideline 2010 da\nAmerican Heart Association?","options":{"A":"Manobra Vagal, Adenosina 6 mg e Betabloqueador.","B":"Manobra Vagal, Adenosina 12 mg e Bloqueador de Canal de Cálcio.","C":"Desfibrilação 360 J monofásico, Adenosina 12 mg e nipride 1 mcg/kg/min.","D":"Cardioversão Sincronizada 120 Joules bifásico podendo chegar até 200 Joules.","E":"Cardioversão Sincronizada 100 Joules, Adenosina 6 mg, Procainamida 20 mg/min até supressão\nda arritmia."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61818","number":"61818","sourceNumber":"61818","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"A Síndrome da Apneia-Hipopneia Obstrutiva do Sono (SAHOS) é uma doença de\ngrande impacto na qualidade de vida dos\npacientes. Dentre as comorbidades a seguir, qual NÃO\ntem relação com esta doença?","options":{"A":"Hipertensão arterial.","B":"DPOC.","C":"Dislipidemia.","D":"Alterações no metabolismo da glicose.","E":"NDA."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-61801","number":"61801","sourceNumber":"61801","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Uma situação de Parada Cardiorrespiratória (PCR) representa prioridade e rapidez de\natendimento na prática médica. Considerando as diretrizes atuais da American Heart Associacion\n(AHA) sobre Suporte Avançado de Vida Cardiovascular, pode-se afirmar que:","options":{"A":"O exame clínico é o método mais confiável para monitorar a posição adequada do tubo\nendotraqueal, não sendo mais recomendado a capnografia com forma de onda contínua.","B":"As causas mais comuns da AESP (Atividade Elétrica Sem Pulso) são os 5 Hs (Hipovolemia,\nHipóxia, Hipo/Hipercalemia, Hipoglicemia, Hipotermia) e\n5 Ts (Pneumotórax, Tamponamento\ncardíaco, Toxinas, Trombose pulmonar ou coronária).","C":"As vias de acesso para os medicamentos durante uma PCR, em ordem de prioridade, são:\nendovenosa, endotraqueal e intraóssea; devendo-se evitar esta última em crianças menores de 5\nanos.","D":"No algoritmo de cuidados imediatos pós-PCR do adulto, deve-se otimizar o estado ventilatório e\nhemodinâmico do paciente: não hiperventilar, manter a saturação de oxigênio \"maior ou igual a\"\n90% e tratar hipotensão (PA sistólica < 90 mmHg).","E":"A hipotermia terapêutica é a única intervenção que mostrou ter melhorado a recuperação\nneurológica após uma PCR com duração ideal de, no mínimo, 12 horas."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-48303","number":"48303","sourceNumber":"48303","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 42 anos, branco, ao realizar caminhada matinal, cai subitamente ao solo e\nfica imóvel. A primeira conduta é:","options":{"A":"Respiração boca a boca ou boca-nariz","B":"Soco precordial","C":"Massagem cardíaca externa","D":"Avaliar responsividade e chamar ajuda","E":"Nenhuma das alternativas anteriores"},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-47666","number":"47666","sourceNumber":"47666","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Para tratar de fibrilação ventricular, num paciente adulto, as diretrizes de 2010 sobre\nreanimação cardiopulmonar (RCP) preconizam:","options":{"A":"Relação compressão-ventilação única (15:2);","B":"Inserção imediata de via aérea avançada;","C":"Choque (desfribilação) único seguido de início imediato de massagem cardíaca;","D":"Imediata utilização de drogas."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-53603","number":"53603","sourceNumber":"53603","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Fibrilação atrial com episódios que duram até mais de sete dias e sem resposta à\ncardioversão é classificada como:","options":{"A":"Paroxística.","B":"Permanente.","C":"Persistente.","D":"Terminal.","E":"Subaguda."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-48486","number":"48486","sourceNumber":"48486","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O Tilt teste positivo demonstra:","options":{"A":"Susceptibilidade do paciente diábético em desenvolver úlceras em membros inferiores.","B":"Tendência em apresentar hemorragia digestiva de origem alta ou baixa, no paciente renal\ncrônico.","C":"Comprometimento renal no Diabetes Mellitus tipo II.","D":"Confirmação do diagnóstico de hipertensão arterial essencial.","E":"Vulnerabilidade do indivíduo em apresentar episódios de síncope devido o comprometimento da\ninervação autonômica."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-48498","number":"48498","sourceNumber":"48498","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Analise os traçados e escolha os diagnósticos correspondentes, respectivamente (VER\nIMAGEM).","options":{"A":"Fibrilação ventricular, Taquicardia ventricular monomórfica e Fibrilação ventricular.","B":"Taquicardia ventricular monomórfica, Taquicardia ventricular polimórfica e Fibrilação\nventricular.","C":"Taquicardia ventricular monomórfica, Taquicardia ventricular polimórfica e Fibrilação atrial.","D":"Taquicardia supraventricular paroxística, Fibrilação ventricular e Fibrilação ventricular.","E":"Taquicardia supraventricular paroxística, Taquicardia ventricular polimórfica e Fibrilação\nventricular."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":["question_bank/media/medcurso/medcurso-cardiologia-car-1/48498.png"],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-48503","number":"48503","sourceNumber":"48503","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Toxicômano dá entrada na emergência com crise convulsiva. O médico que o atende\nsuspeita de intoxicação aguda por cocaína, porque há concomitantemente:","options":{"A":"Hipotermia e nistagmo.","B":"Arritmia cardíaca e nistagmo.","C":"Arritmia cardíaca e hipertermia.","D":"Hipotermia e hipertensão arterial.","E":"Hipotermia e hipotensão arterial."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-48868","number":"48868","sourceNumber":"48868","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em relação ao uso de medicações no atendimento da parada cardiorrespiratória,\npodemos afirmar que:","options":{"A":"o bicarbonato de sódio deve ser administrado logo no início do atendimento dos pacientes em\nparada cardíaca","B":"o cálcio é essencial no manuseio da parada cardíaca por hipopotassemia ou hipomagnesemia","C":"a atropina é a droga de escolha nas paradas cardíacas em assistolia ou atividade elétrica sem\npulso (dissociação eletromecânica), devendo ser repetida quantas vezes for necessário, sem\nlimitação de dose","D":"drogas vasopressoras como a adrenalina e/ou vasopressina são fundamentais, devendo ser\nusadas no atendimento da parada\ncardiorrespiratória com a finalidade de aumentar a pressão de\nperfusão coronariana","E":"a amiodarona deve ser usada nos casos de parada cardíaca por fibrilação ventricular,\npodendo-se postergar a desfibrilação elétrica."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35612","number":"35612","sourceNumber":"35612","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Um homem de 24 anos dá entrada no pronto-socorro com queixa de dor em aperto na\nregião retroesternal. Relata ter usado cocaína inalatória há cerca de 40 minutos. Está sudoreico,\ncom extremidades frias, pupilas dilatadas e fasciculações na pálpebra esquerda; pulso = 124\nbat/min, PA = 180 x 90, T = 36,9ºC, frequência respiratória de 24 mr/min, com ausculta cardíaca e\npulmonar normais, pulsos centrais e periféricos palpáveis e simétricos. O médico deve de imediato:","options":{"A":"Administrar betabloqueador VO ou EV.","B":"Administrar flumazenil EV.","C":"Confirmar a intoxicação através de exame de urina.","D":"Solicitar eletrocardiograma.","E":"Administrar naloxona IM ou EV."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35626","number":"35626","sourceNumber":"35626","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Homem de 56 anos, hipertenso e diabético deu entrada no Pronto-Socorro com duas\nhoras de dor precordial de forte\nintensidade, irradiada para membro superior esquerdo e\nacompanhada de sudorese. O eletrocardiograma apresentava 2 mm de supradesnivelamento do\nsegmento ST em DII, DIII e AVF. Ao exame, estava em bom estado geral com palidez cutânea\n\n+/++, PA = 100 x 70 mmHg, P = 60 (2 extrassístoles por minuto). Coração e pulmão sem\nalterações. Nega cirurgias ou traumas\nrecentes. Teve infarto há cerca de 4 meses quando recebeu\nestreptoquinase. Após ter recebido 5 mg de Isordil sublingual e 1 mg de morfina endovenosa, o\npaciente evoluiu com confusão mental, queda da pressão para 50 x 30 mmHg e no\neletrocardiograma apresentou bloqueio A-V total. Qual conduta imediata mais adequada dentre as\nalternativas abaixo?","options":{"A":"Cateterismo de emergência.","B":"Marca-passo externo transcutâneo.","C":"Atropina 0,25 mg intravenosa.","D":"Dobutamina 2,5 mg/kg/min intravenosa.","E":"Nitroglicerina intravenosa."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35627","number":"35627","sourceNumber":"35627","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Considere o caso de uma jovem senhora de 36 anos, portadora de estenose da valva\nmitral com área valvar de 1,5 cm² e\nfribilação atrial crônica em uso de digoxina e que procura\nmédico para prosseguir o acompanhamento. A paciente não apresenta limitação física ou sintomas\ne sua frequência cardíaca média é 72 batimentos por minuto. Qual das drogas abaixo deve ser\nassociada ao tratamento?","options":{"A":"Warfarina.","B":"Captopril.","C":"Amiodarona.","D":"Quinidina.","E":"Diurético tiazídico."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35846","number":"35846","sourceNumber":"35846","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O tratamento de pacientes com fibrilação atrial (FA) varia de acordo com a\nmanifestação clínica, mas envolve três\ncomponentes: (1) avaliação da necessidade para\nrestauração do ritmo sinusal, (2) anticoagulação para prevenir AVC e (3) droga para controle da\nFC. Marque a opção verdadeira em relação ao manuseio da FA.","options":{"A":"Os resultados do estudo AFFIRM demonstram que a estratégia de manutenção do ritmo sinusal\ncom antiarrítmicos é superior sobre a estratégia de controle da FC.","B":"Nos pacientes com FA < 48 horas de duração, pode-se realizar a cardioversão elétrica sem\nnecessidade de anticoagulação prolongada.","C":"Nos pacientes com FA > 48 horas de duração recomenda-se a anticoagulação com aspirina pelo\nmenos três semanas antes de cardioversão elétrica.","D":"Nos pacientes com FA e WPW a reversão química pode ser realizada com verapamil.","E":"Se a existência de trombo atrial for excluída por ecocardiograma transtorácico, pode-se efetuar a\ncardioversão nestes pacientes mais rapidamente."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-35852","number":"35852","sourceNumber":"35852","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente portador de Síndrome de WPW que apresenta taquicardia supraventricular de\nQRS estreito com instabilidade hemodinâmica. A\nmelhor opção para reversão da arritmia em\nambiente hospitalar é:","options":{"A":"Amiodarona endovenosa administrada lentamente.","B":"Adenosina endovenosa administrada em bolus.","C":"Cardioversão elétrica.","D":"Manobra vagal com compressão do globo ocular.","E":"Conduta expectante, pois o índice de reversão espontânea das arritmias supraventriculares é\nalto."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-26938","number":"26938","sourceNumber":"26938","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Maria, 40 anos, sem antecedentes patológicos, apresentou súbita tontura seguida de\npré-síncope após caminhada de 30 minutos no plano. Avaliada em ambulatório, constatou-se\napenas ritmo cardíaco irregular e pulso de 170bpm. O ECG demonstrou ausência de onda P e\nintervalo RR irregular. Qual dos exames abaixo é mais importante na avaliação da causa desta\narritmia.","options":{"A":"dosagem sérica de potássio e de magnésio","B":"Holter cardíaco de 24 horas","C":"ecocardiograma de estresse","D":"teste ergométrico","E":"dosagem sérica de TSH"},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-27200","number":"27200","sourceNumber":"27200","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Maiores causas de morte súbita em atletas:","options":{"A":"infarto agudo do miocárdio; doença de Chagas; crise hipertensiva.","B":"infarto agudo do miocárdio; estenose aórtica; taquicardia supraventricular.","C":"miocardiopatia hipertrófica, displasia arritmogênica de VD; WPW.","D":"estenose subaortica; doença de Chagas; tromboembolismo.","E":"displasia arritmogênica de VD; acidente vascular cerebral; ICC."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-27150","number":"27150","sourceNumber":"27150","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Em qual situação não se deve indicar marcapasso definitivo:","options":{"A":"Doença do nódulo sinusal.","B":"Bloqueio infra hissiano.","C":"BAV total.","D":"Síndrome taquibradi.","E":"Bloqueio supra Hissiano."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-27151","number":"27151","sourceNumber":"27151","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Qual a melhor maneira para diagnóstico de uma síndrome taquicárdica:","options":{"A":"Holter 24h.","B":"Gravador de eventos.","C":"Teste de esforço.","D":"ECG durante a arritmia.","E":"Cintilografia miocárdica."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-11090","number":"11090","sourceNumber":"11090","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Os novos conceitos em reanimação cardiopulmonar tem mudado constantemente.\nDentre as últimas recomendações está a técnica\npara massagem cardíaca externa e a ventilação\npulmonar. Com relação a estas recomendações podemos afirmar que:","options":{"A":"A massagem cardíaca externa deve ser realizada numa relação de 15:1 ventilação quando\nexistem dois reanimadores.","B":"Independente do número de reanimadores a relação será sempre de 15:1.","C":"A relação massagem cardíaca:ventilação recomendada é de 30:2","D":"A ventilação só será iniciada após a massagem cardíaca desde o primeiro atendimento.","E":"N.r.a."},"answer":"C","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-16029","number":"16029","sourceNumber":"16029","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Com o tratamento da parada cardíaca pela Fase 1 (suporte básico) e Fase 2 (suporte\navançado), pode-se recuperar a respiração e a\ncirculação espontânea e chega-se à Fase 3, que é\na da recuperação cerebral. Todos os esforços no tratamento da parada cardiorrespiratória devem\nvisar à preservação do sistema nervoso central e suas funções, no período crítico em que este\nsistema sofre os efeitos da hipóxia. Uma série de medidas deve ser tomada, algumas já provadas\nna prática, enquanto que outras possuem somente bases teóricas. Dentre essas medidas,\ndestaca-se a diminuição:","options":{"A":"da pressão arterial com expansores plasmáticos.","B":"do consumo de oxigênio por hipotermia.","C":"do aporte de oxigênio ao cérebro.","D":"do edema cerebral com transfusão de sangue."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-274007","number":"274007","sourceNumber":"274007","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"O uso da adrenalina na parada cardiorrespiratória tem como objetivo principal:","options":{"A":"Aumentar a pressão diastólica e automaticidade miocárdica melhorando a perfusão renal.","B":"Restabelecer a circulação espontânea e melhorar a sobrevida pós-parada cardíaca.","C":"Aumentar o consumo de oxigênio pelo miocárdio e, assim, restabelecer o débito cardíaco.","D":"Restabelecer a circulação espontânea através do aumento da pressão de perfusão coronária e\nmanter a perfusão cerebral."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-250228","number":"250228","sourceNumber":"250228","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente 65 anos, avaliado em consulta ambulatorial, apresenta antecedente de\nacidente vascular encefálico isquêmico e fibrilação atrial. Previamente hipertenso e com doença\nvascular periférica. Exames laboratoriais: creatinina: 1,1 mg/dl, hemoglobina: 12 g/dl, plaquetas:\n260.000/mm³, ecocardiograma: estenose mitral moderada a grave. Com base nas informações,\nassinale a alternativa CORRETA:","options":{"A":"Está indicada a anticoagulação com antagonistas da vitamina K.","B":"A rivaroxabana 20 mg é o anticoagulante de escolha.","C":"Está indicado o uso de dupla antiagregação: aspirina 100 mg e clopidogrel 75 mg.","D":"Não está indicado o uso de terapia antiagregante ou anticoagulante nesse caso."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-216386","number":"216386","sourceNumber":"216386","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Paciente de 35 anos, sexo feminino, apresentando queixa de palpitações há alguns\ndias. História pregressa de febre reumática. À\nausculta, ritmo cardíaco irregular. Realizado ECG\nque mostrou: QRS estreito, intervalos R-R variáveis e ausência de onda P identificável. A arritmia\nMAIS PROVÁVEL para essa paciente é:","options":{"A":"Flutter atrial.","B":"Fibrilação atrial.","C":"Taquicardia por reentrada nodal atrioventricular.","D":"Taquicardia ortodrômica por via acessória."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-176131","number":"176131","sourceNumber":"176131","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"As arritmias cardíacas são decorrentes, basicamente, de alterações na geração do\nimpulso (automatismo anormal e atividade deflagrada) e/ou na condução do impulso (reentrada).\nSobre os principais mecanismos de taquiarritmia mais prevalentes na população pediátrica, sua\nclassificação e tratamento, podemos afirmar, EXCETO:","options":{"A":"As células miocárdicas atriais e ventriculares normalmente não apresentam atividade de\nmarca-passo.","B":"A reentrada é o mecanismo gerador de taquiarritmias supraventriculares e ventriculares mais\nfrequente e relevante, podendo ser anatômica ou funcional.","C":"As arritmias cardíacas podem ser classificadas quanto à repercussão clínica em estável ou\ninstável.","D":"A distinção entre taquicardia supraventricular e taquicardia ventricular é de fundamental\nimportância, não somente para a reversão aguda, mas para adoção de estratégias para a\nprevenção de recorrências em longo prazo.","E":"Cicatrizes (fibrose) miocárdicas secundárias à cardiopatia estrutural não favorecem o\ndesenvolvimento de reentrada."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155255","number":"155255","sourceNumber":"155255","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Sobre a Fibrilação Atrial é correto afirmar, EXCETO:","options":{"A":"Essa arritmia se apresenta obrigatoriamente com taquicardia.","B":"Os pacientes com fibrilação atrial, mesmo quando paroxística, podem ter indicação para\nanticoagulação, mantida indefinidamente naqueles\nsem contraindicação e com pelo menos um fator\nde risco CHADS2","C":"É a arritmia crônica mais comum, com incidência e prevalência que aumentam com a idade.","D":"Um paciente masculino, 60 anos, diabético, portador de fibrilação atrial, sem outras\ncomorbidades, poderá trocar a anticoagulação oral pelo AAS.","E":"A rivaroxabana foi aprovada para anticoagulação em pacientes com fibrilação atrial não valvar."},"answer":"A","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-155261","number":"155261","sourceNumber":"155261","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Mãe traz à emergência criança de 6 meses com queixa de irritabilidade há dois dias,\nvômitos, recusa alimentar e cansaço que piorou nas últimas 12 horas associada à palidez. Ao\nexame físico, é observado desconforto respiratório, pulsos finos, gemência, tiragem inter e\nsubcostal. Paciente é colocado com máscara de oxigênio não reinalante a 10 litros/min e\nmonitorizado. Observado no monitor ritmo cardíaco sem onda p, duração do QRS de 70ms,\nfrequência cardíaca de 260 bpm, sem variações durante todo o atendimento. Qual a medida MAIS\nADEQUADA para restabelecer a estabilidade hemodinâmica desse paciente?","options":{"A":"Adenosina - 0,1 mg/kg máximo 6mg.","B":"Cardioversão elétrica - Choque inicial de 0,5 a 1 J/kg.","C":"Amiodarona - 5mg/kg EV.","D":"Cardioversão elétrica - Choque inicial de 2J/kg.","E":"Procainamida - 15mg/kg."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-131920","number":"131920","sourceNumber":"131920","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Ao avaliar um adulto de 41 anos com síncope, assinale qual dos achados fala a favor\nde síncope de bom prognóstico e NÃO indicaria\nnecessidade de internação para avaliação\nadicional.","options":{"A":"Síncope ocorrida durante atividade física.","B":"Síncope desencadeada por odor específico.","C":"Presença de anemia importante ao hemograma.","D":"Palpitações precedendo a síncope.","E":"História familiar de morte cardíaca súbita."},"answer":"B","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-80850","number":"80850","sourceNumber":"80850","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Assinale a alternativa que caracteriza o bloqueio atrioventricular de 3º grau.","options":{"A":"Aumento fixo do intervalo PR.","B":"Aumento progressivo do intervalo PR até interrupção do estímulo, com onda P sem preceder o\ncomplexo QRS.","C":"Ocorre interrupção da condução AV sem prévio alongamento do intervalo PR.","D":"Toda onda P é seguida de complexo QRS.","E":"Inexistência de relação entre atividade atrial e ventricular."},"answer":"E","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-cardiologia-car-1-47395","number":"47395","sourceNumber":"47395","collectionBlock":"medcurso:medcurso-cardiologia-car-1","collectionLabel":"Medcurso · CAR 1","documentBlock":"","area":"Cardiologia","specialty":"Cardiologia","topic":"CAR 1","subtopic":"","stem":"Entre as causas reversíveis de fibrilação atrial, encontram-se:","options":{"A":"Hipotireoidismo e infarto agudo do miocárdio.","B":"Uso de ácido acetilsalicílico e embolia pulmonar.","C":"Miocardite e labirintite.","D":"Choque elétrico e ingesta de álcool.","E":"Pericardite e hipotireoidismo."},"answer":"D","source":"Cardiologia/CAR 1/CAR 1.txt","sourceLabel":"Medcurso · CAR 1","images":[],"optionImages":{},"commentImages":[],"tags":["Cardiologia","CAR 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
